// Scored viva question banks, one array per case id, inlined into the hub at build time by
// build.py. Kept out of app/case-files.html because the banks are the bulk of the words in
// this project and the hub is the bulk of its logic, and because a question is edited far
// more often than the drill around it.
//
// Each question:
//   id    unique across every bank, because a student's answers are stored against it and
//         a reused id would merge two questions' histories. Prefix per case.
//   lv    1 Foundation, 2 Clinical, 3 Examiner's edge. Level 1 and 2 are what an Indian
//         final-year examiner actually asks at the bedside; level 3 is the hardest of those,
//         not registrar material.
//   type  the topic the progress screen groups by: Anatomy, Examination, History,
//         Classification, Investigation, Management, Treatment, Complications, Pathology.
//   q     the question, as an examiner would put it. Never "what does the book say".
//   a     the answer. It answers the question in its first clause, and only then adds any
//         note about where the three books disagree.
//   ref   the page citation, in the same form the guides use: "Das 38 p.594 · B&L 64 p.1060".
//         Every one is checked by check_bank.py against the chapter and page it names.

var VIVA_BANKS = {

  "inguinal-hernia": [
      {id:"h01", lv:1, type:"Anatomy", q:"Define a hernia.",
       a:"S Das: a hernia is defined as protrusion of whole or a part of a viscus through the wall that contains it. Bailey & Love: a hernia is an abnormal protrusion of an organ or tissue through an opening in the layer that normally confines it. Either is accepted; S Das is the one an Indian examiner is most likely to be marking against.", ref:"Das 38 p.594 · B&L 64 p.1058"},
      {id:"h02", lv:1, type:"Anatomy", q:"Name the three parts of a hernia, and the four parts of its sac.",
       a:"Covering, sac and contents. The sac has a mouth, neck, body and fundus.", ref:"SRB 18 p.741"},
      {id:"h03", lv:1, type:"Anatomy", q:"By what route does an indirect inguinal hernia leave the abdomen?",
       a:"Through the deep inguinal ring, lateral to the inferior epigastric vessels, obliquely along the inguinal canal, emerging at the superficial ring. Lateral by origin, oblique by course.", ref:"Das 38 p.594 · B&L 64 p.1066"},
      {id:"h04", lv:1, type:"Anatomy", q:"Give the boundaries of Hesselbach's triangle.",
       a:"Lateral border of rectus abdominis medially, inferior epigastric vessels laterally, inguinal ligament below. B&L names the pubic bone and iliopubic tract as the lower border. The neck of a direct sac lies medial to the inferior epigastric vessels.", ref:"Das 38 p.603 · B&L 64 p.1066"},
      {id:"h05", lv:1, type:"Examination", q:"What are the two classical signs of an uncomplicated hernia, and the two caveats?",
       a:"Impulse on coughing and reducibility. Caveats: a swelling with a cough impulse is not necessarily a hernia, and a swelling with no cough impulse may still be one.", ref:"Das 38 p.598 · B&L 64 p.1061"},
      {id:"h06", lv:1, type:"Classification", q:"When is an inguinal hernia 'complete'?",
       a:"Only when the contents reach the bottom of the scrotum. Short of that, incomplete; still inside the superficial ring, a bubonocele.", ref:"Das 38 p.594, p.603"},
      {id:"h07", lv:1, type:"History", q:"Which inguinal hernia is typical of the young, and which of the old?",
       a:"Indirect in the young, and always the congenital type in neonates and young children. Direct mostly in older subjects, more common above 40.", ref:"Das 38 p.594, p.604 · B&L 64 p.1066"},
      {id:"h08", lv:1, type:"Classification", q:"Name the possible contents of a hernial sac.",
       a:"Omentum (omentocele/epiplocele), intestine (enterocele), bladder (cystocele), Meckel's diverticulum (Littre's), part of the bowel circumference (Richter's), appendix (Amyand's), ovary with fallopian tube, and fluid.", ref:"SRB 18 p.741–742"},
      {id:"h09", lv:1, type:"Examination", q:"Why must the patient be examined standing?",
       a:"A direct hernia disappears the moment he lies down. S Das examines standing first; B&L lies the patient down first to reduce and assess. Do both: standing to demonstrate, supine to assess the defect.", ref:"Das 38 p.596 · B&L 64 p.1061"},
      {id:"h10", lv:1, type:"Examination", q:"How far must you expose the patient?",
       a:"Both inguinal regions, from the umbilicus to mid-thigh. Inadequate exposure of this area is exactly why femoral hernias are missed.", ref:"Das 38 p.595 · B&L 64 p.1071"},
      {id:"h11", lv:1, type:"Classification", q:"Name the clinical types of hernia.",
       a:"Reducible, irreducible, obstructed, inflamed, strangulated, and SRB adds occult. B&L's complexity scale ends in infarcted.", ref:"Das 38 p.604–605 · SRB 18 p.742–743 · B&L 64 p.1060"},
      {id:"h12", lv:1, type:"Anatomy", q:"Where is the superficial inguinal ring, and what should it admit?",
       a:"A triangular opening in the external oblique aponeurosis, 1.25 cm above the pubic tubercle, bounded by a superomedial and an inferolateral crus. Normally it does not admit the tip of the little finger, or only just.", ref:"SRB 18 p.743"},
      {id:"h13", lv:1, type:"Examination", q:"Where does an inguinal hernia lie relative to the pubic tubercle? And a femoral hernia?",
       a:"Inguinal: above the inguinal ligament and medial to the pubic tubercle. Femoral: below the ligament and lateral to the tubercle. Edition note, not a live disagreement: B&L 26e said 'above and lateral' for the inguinal hernia and 28e has deleted that sentence, so the books now agree. The only relation 28e prints is the femoral one, and it matches S Das.", ref:"Das 38 p.597 · B&L 64 p.1071"},
      {id:"h14", lv:1, type:"History", q:"What proportion of adult hernia repairs are inguinal?",
       a:"Inguinal hernia is by far the commonest, and the figure usually quoted is that it accounts for about 80% of all hernia repairs. Then the detail: B&L 28e no longer prints that 80% figure. What it says is that inguinal hernia is the most common hernia in men and around 10 times more common in men than in women, that more than 80% of inguinal hernias are indirect, and that almost all hernias in children and women are indirect.", ref:"B&L 64 p.1065 · Das 38 p.603"},

      {id:"h20", lv:2, type:"History", q:"Describe the pain of an early hernia. What does it mean when it stops?",
       a:"Dragging and aching, worse as the day passes, often appearing before the lump. It ceases once the hernia is fully formed: so settling pain means the hernia has finished forming, not that he is improving. B&L: sharp intermittent pain suggests pinching; severe pain means high risk of strangulation.", ref:"Das 38 p.594 · B&L 64 p.1061"},
      {id:"h21", lv:2, type:"History", q:"Give the four set questions for any inguinoscrotal swelling.",
       a:"How did it start: on straining? Where did it first appear: groin descending, or below the crease ascending? What size when first seen, bottom of scrotum at once, or gradual? Does it disappear on lying down?", ref:"Das 38 p.594–595"},
      {id:"h22", lv:2, type:"History", q:"Is a hernia caused by heavy lifting?",
       a:"Classically yes. But B&L 28e begins from the premise that a normal abdominal wall has sufficient strength to resist high pressure, so the strain brings the hernia to the patient's attention rather than causing it. The evidence favours an inherited imbalance of collagen types, supported by the association with aortic aneurysm, by the difficulty of repair in Ehlers-Danlos syndrome, and by smoking raising risk through impaired collagen maturation. SRB agrees in its own words, 'metastatic emphysema of Read'. Edition note: the Olympic weightlifters line was 26e's way of making this argument and has been removed from 28e, so quote the mechanism, not the weightlifters.", ref:"B&L 64 p.1060 · SRB 18 p.741"},
      {id:"h23", lv:2, type:"Examination", q:"A hernia with no cough impulse. What does that mean?",
       a:"A complication, strangulated or incarcerated: or a neck blocked by adhesions. It is also typical of femoral hernia, where its absence leads to misdiagnosis as a lymph node. A saphena varix and a varicocele give false positives.", ref:"Das 38 p.597, p.599 · B&L 64 p.1061, p.1071"},
      {id:"h24", lv:2, type:"Examination", q:"Describe Zieman's technique and its precondition.",
       a:"Index on the deep ring (indirect), middle on the superficial ring (direct), ring finger on the saphenous opening 4 cm below and lateral to the pubic tubercle (femoral); the patient holds his nose and blows, or coughs. Only valid with no obvious swelling, or after complete reduction.", ref:"Das 38 p.599"},
      {id:"h25", lv:2, type:"Examination", q:"In the invagination test, what does the direction of the finger tell you?",
       a:"Directly backwards, direct. Upwards, backwards and outwards: indirect. Impulse on the pulp means direct; on the tip, oblique.", ref:"Das 38 p.600–601"},
      {id:"h26", lv:2, type:"Examination", q:"Explain the ring occlusion test and its logic.",
       a:"Standing, hernia reduced, thumb over the deep ring, cough. An indirect hernia comes through that ring so it is blocked; a direct one comes medial to it and bulges medial to your finger. B&L warns even experienced surgeons cannot distinguish the two with certainty.", ref:"Das 38 p.601 · B&L 64 p.1067"},
      {id:"h27", lv:2, type:"Examination", q:"Distinguish an enterocele from an omentocele at the bedside.",
       a:"Enterocele: elastic, resonant, reduces with a gurgle, first part difficult and last part easy, may show peristalsis. Omentocele: doughy and granular, dull, no gurgle, first part easy and last part resists.", ref:"Das 38 p.598, p.600 · SRB 18 p.742"},
      {id:"h28", lv:2, type:"Examination", q:"Why is rectal examination obligatory in a case of hernia?",
       a:"To exclude chronic constipation and an enlarged prostate, causes of straining that recur the hernia. And prostatic symptoms predict postoperative urinary retention.", ref:"Das 38 p.603 · B&L 64 p.1070"},
      {id:"h29", lv:2, type:"Complications", q:"Differentiate an irreducible from a strangulated hernia.",
       a:"Both are irreducible. The strangulated one is extremely tense and tender, may have red overlying skin, and has lost its cough impulse. All absent in pure irreducibility.", ref:"Das 38 p.604–605"},
      {id:"h30", lv:2, type:"Complications", q:"Define obstructed hernia, and say why the diagnosis is dangerous.",
       a:"Irreducibility plus intestinal obstruction with blood supply intact. It shares two of the three features of strangulation, so calling a strangulated hernia 'obstructed' wastes the time that would have saved the patient.", ref:"Das 38 p.604–605"},
      {id:"h31", lv:2, type:"Examination", q:"Why examine abdominal muscle tone, and how?",
       a:"To choose the operation, herniorrhaphy if tone is good, hernioplasty if poor. Observe in profile; the rising test, where weak obliques give Malgaigne's bulgings; and a finger in the superficial ring during a cough.", ref:"Das 38 p.602"},
      {id:"h32", lv:2, type:"History", q:"A hernia that enlarges before micturition and shrinks after. What is in it?",
       a:"Urinary bladder: a cystocele, only in a direct or sliding hernia. Pressing it provokes a desire to micturate. The medially placed bladder is pulled into a direct hernia.", ref:"Das 38 p.604 · B&L 64 p.1066"},
      {id:"h33", lv:2, type:"Management", q:"Which investigation establishes the diagnosis?",
       a:"None, it is clinical. Investigations are for fitness and cause. In doubt: ultrasound first, low cost but highly operator dependent; CT for complex or incisional hernia, and for planning abdominal wall reconstruction; MRI for sportsman's groin; laparoscopy for an occult contralateral hernia, though it will not show an intraparietal hernia. Plain x-ray is of little value. Herniography is SRB's answer, not B&L 28e's. And a negative scan does not exclude the hernia you felt, because groin hernias tend to reduce in a supine patient.", ref:"B&L 64 p.1061, p.1062"},
      {id:"h34", lv:2, type:"Management", q:"State the four principles of any hernia repair.",
       a:"Reduce the contents and remove non-viable tissue; excise and close the peritoneal sac, though small sacs may be reduced intact; close the defect if possible; reinforce with mesh, since closure alone has a high recurrence rate and mesh reduces but does not prevent recurrence. B&L 28e adds a fifth: excise redundant skin if necessary for cosmesis.", ref:"B&L 64 p.1062"},
      {id:"h35", lv:2, type:"History", q:"A right direct hernia in a man with a right iliac fossa scar. Connect them.",
       a:"Appendicectomy through a McBurney incision injured the ilioinguinal nerve, weakening the inguinal region and producing a right-sided direct hernia.", ref:"SRB 18 p.741 · Das 38 p.595"},

      {id:"h40", lv:3, type:"Anatomy", q:"Where exactly is the deep inguinal ring?",
       a:"S Das and SRB: 1.25 cm above the mid-inguinal point, midway between the ASIS and the symphysis pubis. B&L: midway between the ASIS and the pubic tubercle, the midpoint of the inguinal ligament: 2–3 cm above the femoral pulse. The mid-inguinal point overlies the femoral artery; the midpoint of the ligament overlies the deep ring.", ref:"Das 38 p.599 · SRB 18 p.743 · B&L 64 p.1065"},
      {id:"h41", lv:3, type:"Complications", q:"Which hernia strangulates most often?",
       a:"Two answers to two questions. The most common strangulated hernia is the indirect inguinal, because inguinal hernias are far more numerous. The highest rate of strangulation is in the femoral hernia. Fifty per cent of femoral hernias present as an emergency, against five per cent of inguinal.", ref:"SRB 18 p.743 · B&L 64 p.1070, p.1071"},
      {id:"h42", lv:3, type:"Complications", q:"Why can a small hernia be more dangerous than a large one?",
       a:"Risk depends on the neck, not the bulk. A small rigid-walled defect traps contents, acts as a constriction ring, impedes venous return and progresses to strangulation. A wide-necked direct hernia rarely strangulates.", ref:"B&L 64 p.1060, p.1062"},
      {id:"h43", lv:3, type:"Complications", q:"What is Garrey's stricture?",
       a:"An ischaemic narrowing of small bowel that has been reduced from an obstructed hernia, a stricture forming later at the site of the constriction ring.", ref:"SRB 18 p.742–743"},
      {id:"h44", lv:3, type:"Classification", q:"What is Amyand's hernia? And Littre's?",
       a:"Amyand's, the appendix in an inguinal hernial sac, often incarcerated. Littre's: a Meckel's diverticulum in the sac; Littre described it 81 years before Meckel was born.", ref:"SRB 18 p.742–743"},
      {id:"h45", lv:3, type:"Complications", q:"What is Richter's hernia, and why is it treacherous?",
       a:"Strangulation of only part of the circumference of the bowel, often complicating a femoral hernia. It mimics gastroenteritis: colic, bowels opening normally, sometimes diarrhoea, so operation is delayed. It may be impossible to detect clinically, yet the bowel can necrose and perforate.", ref:"Das 38 p.605–606 · B&L 64 p.1060"},
      {id:"h46", lv:3, type:"Classification", q:"Classify a hernia by the European Hernia Society system.",
       a:"Primary or recurrent (P/R); lateral, medial or femoral (L/M/F); defect size in finger breadths at 1.5 cm each. A primary indirect hernia with a 3 cm defect is PL2.", ref:"B&L 64 p.1067"},
      {id:"h47", lv:3, type:"Classification", q:"What is a sliding hernia, and what is the surgical danger?",
       a:"Extraperitoneal viscus, caecum on the right, sigmoid on the left, bladder either side, slides outside the sac and forms part of its wall. B&L: the sac forms secondarily, which distinguishes it from a classic indirect hernia; the large bowel wall may not be covered by peritoneum and can be damaged at operation.", ref:"Das 38 p.605 · B&L 64 p.1066"},
      {id:"h48", lv:3, type:"Management", q:"Choose the operation, and justify it.",
       a:"Herniotomy in a child: the wall is normal and in infants the rings are superimposed with no obliquity. Herniorrhaphy in a young adult with good tone. Hernioplasty with mesh where tone is poor, Malgaigne's bulgings are present, or the hernia is large or recurrent. Lichtenstein is commonest worldwide; laparoscopic TEP or TAPP for bilateral or recurrent hernia.", ref:"SRB 18 p.743 · Das 38 p.602 · B&L 64 p.1068-1069"},
      {id:"h49", lv:3, type:"Management", q:"Describe the Shouldice repair and how it differs from Bassini.",
       a:"Bassini sutures conjoint tendon to inguinal ligament from pubic tubercle to deep ring. Shouldice first incises the transversalis fascia from deep ring to pubic tubercle and closes it as a double-thick, two-layered posterior wall, double breasting: then the external oblique likewise. The only one of 150+ modifications with benefit; under 2% lifetime failure in expert hands, identical to Bassini in general hands.", ref:"B&L 64 p.1068"},
      {id:"h50", lv:3, type:"Management", q:"What size mesh, and what must it cover?",
       a:"Lichtenstein: 8 × 15 cm over the posterior wall, split around the cord at the deep ring. Laparoscopic: 10 × 15 cm crossing the midline into the retropubic space and 5 cm lateral to the deep ring, covering Hesselbach's triangle, the deep ring and the femoral canal together. At least 2 cm overlap, up to 5 cm.", ref:"B&L 64 p.1068, p.1069"},
      {id:"h51", lv:3, type:"Management", q:"Why are lightweight large-pore meshes preferred?",
       a:"Better integration, less contracture, less foreign body reaction, more flexibility and better comfort. Heavyweight mesh provokes a greater fibrous reaction, with collagen contraction and stiffening, impaired abdominal wall mobility, foreign body sensation and pain. Note the vocabulary: the mesh does not shrink, the fibrous tissue grown into it contracts, so 'mesh contracture' is the accurate term, and it can exceed 50% of area. Edition note: 28e has dropped the weight thresholds in g/m² and argues from pore size instead, favouring at least 1 mm in all directions.", ref:"B&L 64 p.1063, p.1064"},
      {id:"h52", lv:3, type:"Management", q:"Groin pain four months after a Lichtenstein repair. What is it?",
       a:"Chronic pain: defined as pain at three months, the commonest complication of open flat mesh repair, reported up to 20%. Most severe form is neuralgic, from injury to or irritation of the ilioinguinal, iliohypogastric or genital branch of the genitofemoral nerve, or from mesh shrinkage.", ref:"B&L 64 p.1069, p.1070"},
      {id:"h53", lv:3, type:"Management", q:"Laparoscopic or open, what does the evidence say?",
       a:"Laparoscopic repair gives less pain both immediately and up to five years later, faster return to full activity, and fewer wound complications: infection, bleeding and seroma. Particular benefit in bilateral hernias and in recurrence after open repair. Note what is not claimed: recurrence is no different between open and laparoscopic, nor between mesh types. The limit is a long learning curve. Robot assistance has shown little additional patient benefit so far and is hard to justify on cost for a simple repair. Edition note: 28e no longer cites the 'over 60 randomised trials' figure.", ref:"B&L 64 p.1069, p.1070"},
      {id:"h54", lv:3, type:"Management", q:"Would you repair the asymptomatic other side?",
       a:"Occult contralateral hernias are present in up to 20% of patients, so the other groin must always be examined, and a patient with a single hernia has a 50% lifetime risk of developing one on the other side. Some surgeons have suggested offering bilateral repair, especially if laparoscopic surgery is planned, but that is not widespread practice. Edition note: the lifetime risk was 33% in 26e and is 50% in 28e.", ref:"B&L 64 p.1061, p.1067"},
      {id:"h55", lv:3, type:"Examination", q:"List the differential diagnosis of a groin swelling.",
       a:"Integument: sebaceous cyst, lipoma, neurofibroma. Hernia: inguinal, femoral. Lymphatic: inguinal lymphadenopathy. Vascular: saphena varix, aneurysm. Inguinal canal: ectopic testis, lipoma or hydrocele of the cord, hydrocele of the canal of Nuck. Deep: psoas abscess. The common four are inguinal hernia, femoral hernia, inguinal lymphadenopathy and saphena varix.", ref:"SRB 18 p.741"},
      {id:"h56", lv:3, type:"Complications", q:"A patient has unexplained small bowel obstruction. What must you do?",
       a:"Examine the groins carefully for a femoral hernia. It is missed because the area is inadequately exposed, it may be only 1–2 cm, it loses its cough impulse early, and it is mistaken for a lymph node. CT in obstruction can identify one the clinician missed.", ref:"B&L 64 p.1071"},
      {id:"h57", lv:3, type:"Management", q:"Does every hernia need repair?",
       a:"No. Small hernias can be more dangerous than large, because risk follows the defect and not the lump. Femoral hernia should always be repaired. Recommend repair when complications are likely, for symptomatic or irreducible hernias, when reduction is getting harder or the hernia is enlarging, and in younger adults. Watchful waiting in an asymptomatic inguinal hernia in an elderly patient appears generally safe, with an annual crossover to surgery of around 10% as symptoms develop. Trusses are not recommended.", ref:"B&L 64 p.1062"}
  ],

  "lipoma-and-sebaceous-cyst": [
    {id:"lip01", lv:1, type:"Pathology", q:"What is a lipoma?",
     a:"A benign neoplasm arising from yellow fat, composed of mature adipocytes with uniform nuclei identical to normal adult fat. S Das adds the structure you can feel: normal fat with overactive fat cells, arranged in lobules separated by fibrous septa and enclosed in a delicate capsule.", ref:"SRB 1 p.68 · Das 3 p.48"},
    {id:"lip02", lv:1, type:"Pathology", q:"Why is a lipoma called the universal or ubiquitous tumour?",
     a:"Because it can occur anywhere in the body except the brain. It is the commonest benign tumour, with a karyotype 12q change, and a prevalence of 2.1 per 100 people.", ref:"SRB 1 p.68"},
    {id:"lip03", lv:1, type:"Examination", q:"Give the signs of a lipoma.",
     a:"Soft, lobulated, mobile, non-transilluminant, with the edges slipping between the palpating fingers, the slip sign, and the skin free over it. It may be pedunculated, and it is rare in children.", ref:"SRB 1 p.69"},
    {id:"lip04", lv:1, type:"Examination", q:"What is the slip sign?",
     a:"Press the edge of the swelling and the margin slips away from under the palpating finger, because the lobulated fat is soft and the capsule thin. S Das gives its value: in a cyst the edge does not slip away but yields to the finger, so the sign separates a solid fatty swelling from a cystic one.", ref:"Das 3 p.48 · SRB 1 p.69"},
    {id:"lip05", lv:1, type:"Examination", q:"Where do lipomas commonly occur, and at what age?",
     a:"Anywhere, but commonly in the neck, the back, around the shoulder and in the upper limbs. Any age, but rarely in children, so a soft subcutaneous swelling in a child deserves a wider differential.", ref:"Das 3 p.48 · SRB 1 p.69"},
    {id:"lip06", lv:1, type:"Pathology", q:"What is a sebaceous cyst, and what is in it?",
     a:"S Das: a cyst of the sebaceous gland caused by blockage of its duct, which opens mostly into the hair follicle, so the gland becomes distended by its own secretion. It contains sebum, a yellowish-white cheesy pultaceous material, and it can be squeezed out through the punctum.", ref:"Das 3 p.56"},
    {id:"lip07", lv:1, type:"Examination", q:"What is the punctum, how often is it present, and why is it black?",
     a:"A depressed black spot over the summit of the cyst, which is the blocked duct opening. Present in 70% of cases, because there the sebaceous duct opens directly into the skin and gets blocked. It is black because of the denuded squamous epithelium, that is keratin.", ref:"SRB 1 p.75"},
    {id:"lip08", lv:1, type:"Examination", q:"One manoeuvre to separate a lipoma from a sebaceous cyst. What is it?",
     a:"Move the skin over the swelling. A sebaceous cyst is fixed to the skin and cannot be separated from it, and usually has a punctum; a lipoma lies beneath the skin, so the skin can be pinched up and moved freely over it. Then confirm the lipoma with its two signs, a lobulated surface and a positive slip sign.", ref:"B&L 45 p.645 · SRB 1 p.69, p.75"},
    {id:"lip09", lv:1, type:"Examination", q:"Where do sebaceous cysts occur, and where do they never occur?",
     a:"Anywhere in the body except the palm and the sole, which have no sebaceous glands. Commonly on the scalp, the face and the scrotum, in young adults, single or multiple.", ref:"Das 3 p.57"},
    {id:"lip10", lv:1, type:"Examination", q:"Is a sebaceous cyst fluctuant? Does it transilluminate?",
     a:"Fluctuation is always present; transillumination is always negative, because the contents are opaque pultaceous material and not clear fluid. S Das groups it with the dermoid cyst for exactly that reason.", ref:"Das 3 p.57, p.31"},
    {id:"lip11", lv:1, type:"Examination", q:"Is a sebaceous cyst mobile?",
     a:"It is fixed to the skin but quite movable over the deeper structures, because it arises in the skin itself and has no attachment below. That pattern, fixed above and free below, is the diagnosis.", ref:"Das 3 p.56 · B&L 45 p.645"},
    {id:"lip12", lv:1, type:"Diagnosis", q:"Distinguish swelling, mass and lump.",
     a:"A swelling is an obvious enlargement of a part of the body, from congenital, inflammatory or neoplastic causes. A mass is a lesion whose extent is difficult to define, as in a mass per abdomen. A lump is a defined lesion within an organ, or one that alters the gross shape of a part or organ, as in a breast lump.", ref:"SRB 1 p.68"},
    {id:"lip13", lv:1, type:"Examination", q:"What do you do before you touch this patient?",
     a:"Hand hygiene, introduce yourself and check the patient's name and date of birth, request a chaperone as appropriate, explain what you are going to do, obtain verbal consent, and make sure the patient is comfortable. Expose what you need and cover the rest.", ref:"B&L 35 p.472 · B&L 21 p.285"},

    {id:"lip20", lv:2, type:"Examination", q:"How do you elicit fluctuation, and what is Paget's test?",
     a:"Fix the swelling with two fingers of the left hand, the watching fingers, and press on it with the right index finger, the displacing finger, so that fluid inside is displaced and felt by the watching fingers. Repeat in two planes at right angles. On a small swelling, pressure from a single finger merely displaces the whole swelling, so the test cannot be done that way. SRB's wording: the swelling is fixed with two fingers and the summit is indented to get a yielding sensation due to fluid.", ref:"Das 3 p.30 · SRB 1 p.72"},
    {id:"lip21", lv:2, type:"Examination", q:"What is the moulding sign?",
     a:"The cyst moulds on finger indentation, keeping the shape of your finger for a moment, because its contents are putty-like keratin rather than free fluid. It sits alongside fluctuation, a positive Paget's test and absent transillumination.", ref:"SRB 1 p.75"},
    {id:"lip22", lv:2, type:"Examination", q:"There is no punctum. Can this still be a sebaceous cyst?",
     a:"Yes. The punctum is present in only 70% of cases; in the other 30% the duct opens into a hair follicle rather than directly onto the skin, so no punctum is seen. S Das notes the same difficulty and gives the alternative origins proposed for a cyst without a punctum: a fragment of epidermal cell nest following blunt or penetrating injury, or the hair follicle.", ref:"SRB 1 p.75 · Das 3 p.57"},
    {id:"lip23", lv:2, type:"Examination", q:"Why is the skin fixed over one of these swellings and free over the other?",
     a:"Because the cyst arises from the skin itself, from a hair follicle infundibulum, so it cannot be separated from it; the lipoma lies under the skin, so the skin moves over it.", ref:"B&L 45 p.645 · SRB 1 p.69"},
    {id:"lip24", lv:2, type:"Examination", q:"You move the skin over a lipoma and the skin dimples. Does that make it a cyst?",
     a:"No. Fibrous strands connect the capsule of the lipoma to the skin, so moving the overlying skin dimples it, and S Das describes this in a swelling that is otherwise clearly not attached to the skin. Dimpling on traction is not the same as fixity: you can still pinch the skin up away from a lipoma.", ref:"Das 3 p.48"},
    {id:"lip25", lv:2, type:"Examination", q:"How do you show that a swelling on the back of the neck is subcutaneous and not deep to the muscle?",
     a:"Make the underlying muscle taut, trapezius by shrugging the shoulder up against resistance, and move the swelling with the other hand. A subcutaneous lipoma stays freely mobile over the contracted muscle, along its long axis and at right angles to it. For the abdominal wall the equivalent is the muscle-contraction test: an intra-abdominal mass becomes less prominent, a parietal one persists and becomes less mobile.", ref:"Das 3 p.48 · SRB 16 p.723"},
    {id:"lip26", lv:2, type:"History", q:"The patient has lost a great deal of weight. Will the lipoma have shrunk?",
     a:"No. The fat in a lipoma is considered unavailable for general metabolism, so it persists and may look more prominent in a patient who has lost weight.", ref:"SRB 1 p.68"},
    {id:"lip27", lv:2, type:"Classification", q:"Which lipoma is difficult to remove, and why?",
     a:"The diffuse type. It is neither encapsulated nor localised, is common in the palm, the sole, the head and the neck, and lies in subcutaneous and intermuscular tissue, so it is difficult to remove surgically and recurrence is high after incomplete removal. The localised type is encapsulated and yellowish-orange and shells out easily, which is the whole difference between a five-minute excision and a recurrence.", ref:"SRB 1 p.68"},
    {id:"lip28", lv:2, type:"Examination", q:"The scalp over this swelling is bald and there is an unpleasant smell. Explain both.",
     a:"Hair loss over the surface is common, from constant pressure on the roots of the hair follicles, and the unpleasant odour of the sebum content is typical of a sebaceous cyst. Both are found before you touch the patient.", ref:"SRB 1 p.76 · Das 3 p.57"},
    {id:"lip29", lv:2, type:"Treatment", q:"How would you treat this lipoma?",
     a:"Excision, usually under local anaesthetic for a small localised one, and the capsule makes enucleation easy. A diffuse lipoma must be excised completely and the patient warned, because recurrence is high after incomplete removal.", ref:"SRB 1 p.68"},
    {id:"lip30", lv:2, type:"Treatment", q:"How would you treat this sebaceous cyst, and what if it were infected?",
     a:"Excise the cyst with its wall intact, including the punctum, because any retained wall recurs. If it is infected, drain it first and excise later once the inflammation has settled; infection and abscess formation are its commonest complications.", ref:"SRB 1 p.76"},
    {id:"lip31", lv:2, type:"Complications", q:"List the complications of a sebaceous cyst.",
     a:"S Das gives seven: infection, when the cyst becomes enlarged and painful; ulceration; rupture and sinus formation; calcification; carcinomatous change; Cock's peculiar tumour; and sebaceous horn. SRB's shorter list is infection and abscess formation, surface ulceration, Cock's peculiar tumour and sebaceous horn. Carcinomatous change is in S Das and not in SRB's list, so give S Das's seven to an Indian examiner.", ref:"Das 3 p.57 · SRB 1 p.76"},

    {id:"lip40", lv:3, type:"Complications", q:"What is Cock's peculiar tumour?",
     a:"An ulcerated sebaceous cyst that forms a painful fungating mass with discharge, closely resembling an epithelioma. It is a misnomer: it is not a tumour at all but a chronic granuloma on the ulcerated surface of a sebaceous cyst. Because it looks like a squamous carcinoma, biopsy it, and excise once the diagnosis is secure. S Das adds that it follows rupture of the cyst with chronic infection spreading into the surrounding tissue.", ref:"SRB 1 p.76 · Das 3 p.57"},
    {id:"lip41", lv:3, type:"Complications", q:"What is a sebaceous horn?",
     a:"A projection formed by hardening of slowly discharged sebum through the punctum, a horn being something with greater length than breadth.", ref:"SRB 1 p.76 · Das 3 p.57"},
    {id:"lip42", lv:3, type:"Examination", q:"A soft swelling that seems to fluctuate, and a big one that transilluminates. Can it still be a lipoma?",
     a:"Yes, and this is the trap in the case. S Das: at body temperature the fat is almost semiliquid, so slight fluctuation may be elicited and lipoma is often called a semifluctuant swelling; very soft swellings, lipoma among them, give a false positive fluctuation test, and the way to tell is that they yield to pressure but fail to expand in the other parts of the swelling as a truly fluctuant swelling does. He also records that a large lipoma may transilluminate with an ordinary torch. SRB flatly lists a lipoma as non-transilluminant. The books disagree, and the safe answer is SRB's for the small lipoma in front of you with S Das's caveat attached.", ref:"Das 3 p.48, p.30 · SRB 1 p.69"},
    {id:"lip43", lv:3, type:"Diagnosis", q:"Is \"sebaceous cyst\" the correct name?",
     a:"Clinically yes, strictly no, and the honest answer gives the clinical name first. B&L 28e calls these epidermoid cysts, derived from hair follicle infundibuli or from traumatic inclusion, and says they are commonly known as sebaceous cysts, fixed to the skin and usually with a central punctum. The contents are keratin rather than sebum, which is why the name is regarded as a misnomer, and why the punctum is black with denuded squamous epithelium. SRB and S Das use sebaceous cyst throughout, and so will your examiner, so do not refuse the term.", ref:"B&L 45 p.645 · SRB 1 p.75 · Das 3 p.56"},
    {id:"lip44", lv:3, type:"Diagnosis", q:"A midline swelling over the bridge of the nose in a child. Would you simply excise it?",
     a:"No. Consider a dermoid cyst: skin free, no punctum, often extending into a deeper plane or cavity through a suture line, commonly with bone resorption and indentation, with restricted mobility. It needs proper evaluation with a radiograph or CT first, and excision under general anaesthesia. Restricted mobility, or a position over a suture line, means image before you cut, because of possible deep or intracranial extension. That is the one way this short case can go badly wrong.", ref:"SRB 1 p.76"},
    {id:"lip45", lv:3, type:"Complications", q:"When would you worry about a fatty swelling?",
     a:"If it is large, rapidly growing, deep, painful, intermuscular or retroperitoneal: raise liposarcoma, and image and biopsy rather than shelling it out. S Das lists the changes a long-standing lipoma may undergo, particularly in the thigh, buttock or retroperitoneum: myxomatous degeneration, saponification, calcification, infection, ulceration from repeated trauma, and malignant change. He adds the counter-view that certain authorities believe a lipoma never turns malignant, and that liposarcoma, commonest in retroperitoneal tissue, arises de novo rather than in a benign lipoma.", ref:"Das 3 p.49"},
    {id:"lip46", lv:3, type:"Classification", q:"Name the varieties of lipoma that have their own names.",
     a:"Naevolipoma, which contains dilated blood vessels; fibrolipoma, with excessive fibrous tissue; and neurolipoma, which contains nerve tissue and is therefore painful. The diffuse variety, having none of the typical features, is often called pseudolipoma, is seen in subcutaneous and intermuscular tissue of the neck spreading to the cheek, has no capsule, and is often found in people taking excessive alcohol.", ref:"Das 3 p.48, p.49"},
    {id:"lip47", lv:3, type:"Classification", q:"What is Dercum's disease?",
     a:"A variety of multiple lipomatosis in which there are tender lipomatous swellings, particularly affecting the trunk, and it is commoner in women. Multiple lipomas, lipomatosis, otherwise stay small or moderate, lie mostly in the limbs and trunk, and are no different from a solitary lipoma macroscopically or microscopically; when they contain nerve tissue and hurt they are called neurolipomatosis.", ref:"Das 3 p.49"},
    {id:"lip48", lv:3, type:"Examination", q:"Separate a lipoma, a sebaceous cyst and a dermoid cyst, sign by sign.",
     a:"Lipoma: skin free and moves over it, no punctum, lobulated surface, soft, slip sign positive, no fluctuation, subcutaneous or intermuscular, bone beneath normal. Sebaceous cyst: fixed to skin, punctum in 70%, smooth, moulds on indentation, fluctuant with a positive Paget's test, lies in the skin, bone normal. Dermoid: skin free, no punctum, smooth and often tense, fluctuant, but it extends into a deeper plane through a suture line, mobility is restricted, and bone resorption and indentation are common. None of the three transilluminates.", ref:"SRB 1 p.68, p.69, p.75, p.76 · Das 3 p.57"},
  ],

  "oral-cavity-lesions": [
    {id:"orc01", lv:1, type:"Anatomy", q:"What does the oral cavity include?",
     a:"B&L, following ICD-11: the lip, gum, tongue, palate and floor of the mouth, as well as the rest of the mouth. The nasopharynx, hypopharynx and major salivary glands are excluded, and the base of the tongue belongs to the oropharynx. SRB's list is lips, buccal mucosa, alveolar margins or gingiva, retromolar area and the rest.", ref:"B&L 53 p.813 · SRB 3 p.356"},
    {id:"orc02", lv:1, type:"Pathology", q:"How common is oral cancer in India, and where in the mouth does it sit?",
     a:"It is one of the commonest cancers in India, with an age-adjusted incidence of 20 per 100 000, over one-third of all cancers in India, and 100 000 new cases a year. Two-thirds of the world's oral cancers occur in low-income countries, half of those in South Asia. The subsite differs from the West: buccogingival and retromolar cancers account for over 40% of cases in India and South East Asia, reflecting betel quid, gutka and smokeless tobacco.", ref:"B&L 53 p.813"},
    {id:"orc03", lv:1, type:"Pathology", q:"Define leukoplakia and erythroplakia.",
     a:"A leukoplakia is a white patch or plaque that cannot be rubbed off; an erythroplakia is a bright red velvety plaque; and neither can be characterised clinically or pathologically as any other recognisable condition. Both are diagnoses of exclusion, and \"cannot be rubbed off\" is the clause that excludes candidiasis. SRB adds that leukoplakia is hyperkeratotic, irreversible, persistent and adherent, and the commonest premalignant lesion of the oral cavity.", ref:"B&L 53 p.815 · SRB 3 p.359"},
    {id:"orc04", lv:1, type:"Classification", q:"Name the premalignant lesions of the oral cavity.",
     a:"Leukoplakia, erythroplakia, erythroleukoplakia, proliferative verrucous leukoplakia, oral submucous fibrosis, oral lichen planus and lupus erythematosus, plus the inherited conditions epidermolysis bullosa and dyskeratosis congenita.", ref:"B&L 53 p.815"},
    {id:"orc05", lv:1, type:"Pathology", q:"What causes leukoplakia?",
     a:"SRB's list is a set of S's: smoking, spirit, sepsis, superficial glossitis, syphilis, spices, sharp tooth, and susceptibility with vitamin deficiencies. Add pan chewing with areca, tobacco and slaked lime, and chronic hypertrophic candidiasis. Eighty per cent occur after the age of 40.", ref:"SRB 3 p.359"},
    {id:"orc06", lv:1, type:"Classification", q:"Give the types of leukoplakia.",
     a:"Homogeneous: uniform white patches, the commonest type, prevalent in buccal mucosa, with the least malignant potential. Nodular: fine nodules on the surface, more potential. Speckled: white flecks with fine nodules on an atrophic erythematous base, much higher potential but less common.", ref:"SRB 3 p.359"},
    {id:"orc07", lv:1, type:"Pathology", q:"What is oral submucous fibrosis?",
     a:"A progressive fibrosis deep to the mucosa of the oral cavity which causes trismus and ankyloglossia, with a mottled or marbled pallor of the mucosa of cheek, gingivae, palate and tongue. It is common among Asians and Indians, it is premalignant, and it appears on B&L's list of lesions from which oral cancer arises. It was described in five Indian women from Kenya, and S.G. Joshi coined the term in 1953.", ref:"SRB 3 p.360 · B&L 53 p.815"},
    {id:"orc08", lv:1, type:"Pathology", q:"Where does carcinoma of the tongue arise, and in what proportions?",
     a:"The lateral margin is commonest at 47 to 50%, then the posterior third at 20%, the tip at 10%, the ventral surface at 9% and the dorsum at 6.5%. Incidence is equal in both sexes, and it is rising in women with the number of women smoking.", ref:"SRB 3 p.382"},
    {id:"orc09", lv:1, type:"Classification", q:"Which ulcers of the tongue are painful and which are painless?",
     a:"Painful: dental, aphthous and tuberculous ulcers. Painless: syphilitic ulcers, ulcers of lichen planus, and the malignant ulcer. So a painless ulcer is the one that should worry you.", ref:"SRB 3 p.379"},
    {id:"orc10", lv:1, type:"Anatomy", q:"Give the lymphatic drainage of the tongue.",
     a:"From the tip to the submental nodes and the jugulo-omohyoid; from the margin to the submandibular nodes and the upper deep cervical group; from the back to the jugulodigastric and jugulo-omohyoid nodes. The posterior third also drains to the pharyngeal group. The lymph vessels decussate, so both sides must be examined even when the lesion is unilateral.", ref:"Das 24 p.347, p.348 · SRB 3 p.379"},
    {id:"orc11", lv:1, type:"Examination", q:"How do you inspect the inside of the mouth?",
     a:"In daylight or good light, always with a spatula. Retract the lips to see their mucosal surface, retract the cheeks to see the buccal mucosa and the buccal side of the gum, push the tongue to one side to see the gum and floor of the mouth, ask the patient to protrude the tongue to see the anterior two-thirds and push it aside with the spatula for the lateral aspect of the posterior third, and depress the tongue to see the fauces, tonsils and the beginning of the pharynx. Gauze aids the examination, and intraoral palpation may be needed, done gently.", ref:"Das 24 p.342 · B&L 52 p.778"},
    {id:"orc12", lv:1, type:"Examination", q:"Give the clinical features of carcinoma of the tongue.",
     a:"A painless ulcer or swelling that later becomes painful; pain from infection, ulceration or lingual nerve involvement, referred to the ear; excessive salivation, often blood-stained; dysphagia; a visible ulcer in the anterior two-thirds that bleeds on touch, with an indurated edge, base and surrounding area; inability to articulate; foetor; change in voice with posterior third tumours; and hard nodular neck nodes, fixed in advanced disease. Aspiration may give bronchopneumonia of a lower segment.", ref:"SRB 3 p.382, p.383"},
    {id:"orc13", lv:1, type:"Examination", q:"What do you do before you examine this patient's mouth?",
     a:"Hand hygiene, introduce yourself and check the patient's name and date of birth, request a chaperone as appropriate, explain what you are going to do, obtain verbal consent, and make sure the patient is comfortable. For the mouth you also need good light, a spatula, gloves and gauze.", ref:"B&L 35 p.472 · B&L 52 p.778"},

    {id:"orc20", lv:2, type:"Examination", q:"How do you palpate a tongue ulcer for induration?",
     a:"With the tongue relaxed and at rest inside the mouth. S Das is explicit that this is the one that goes wrong: if the tongue is kept protruded the contracted muscles give a false impression of induration and lead to error in diagnosis. Note also whether the ulcer bleeds readily on palpation, which happens in a malignant ulcer, and feel for a sharp tooth or denture against it.", ref:"Das 24 p.346, p.347"},
    {id:"orc21", lv:2, type:"Examination", q:"What does induration mean in an oral ulcer?",
     a:"It is an important clinical sign of epithelioma, and induration is best felt in squamous cell carcinoma. It may be present in a gummatous ulcer but it is absent in a tuberculous ulcer. In the mouth an everted edge with induration is a squamous carcinoma.", ref:"Das 24 p.347 · SRB 1 p.15"},
    {id:"orc22", lv:2, type:"Examination", q:"The site of a tongue ulcer tells you the diagnosis. How?",
     a:"A dental ulcer lies on the side of the tongue where it meets a sharp tooth or denture. Tuberculous ulcers are on the tip and sides. A gummatous ulcer is on the dorsum. A carcinomatous ulcer is usually on the margin, or on the dorsum where it is superimposed on chronic superficial glossitis.", ref:"Das 24 p.343"},
    {id:"orc23", lv:2, type:"History", q:"An elderly man has an ulcer on his tongue and no pain at all. What does that tell you?",
     a:"It is an ominous sign. Pain is conspicuously absent in leukoplakia, in a mucous retention cyst and in the early stage of carcinoma of the lip or tongue, although in late cases pain does appear. If pain is referred to the ear of the affected side, that is because the lingual and auriculotemporal nerves are both branches of the mandibular nerve.", ref:"Das 24 p.341"},
    {id:"orc24", lv:2, type:"History", q:"An old man sits in the clinic holding a handkerchief to his mouth. What is he likely to have?",
     a:"Carcinoma of the tongue. Excessive salivation is a very common and specific complaint, and SRB adds that the saliva is often blood-stained. Inability to protrude the tongue suggests either tongue-tie or a late carcinoma invading the floor of the mouth, and deviation of the tip towards the side of the lesion on protrusion is a sign of carcinoma.", ref:"Das 24 p.341 · SRB 3 p.382"},
    {id:"orc25", lv:2, type:"Examination", q:"Which leukoplakia would worry you, and where would you take the biopsy from?",
     a:"SRB's five dangerous features: the speckled type, a hard and indurated patch, the nodular type, the presence of epithelial dysplasia, and erosions or ulcerations. B&L agrees that speckled leukoplakia or erythroleukoplakia carries the greatest risk. Biopsy the most suspicious part, which is the speckled, nodular, indurated, eroded or ulcerated area, with a margin of normal mucosa.", ref:"SRB 3 p.359 · B&L 53 p.815"},
    {id:"orc26", lv:2, type:"Pathology", q:"Why does betel nut cause submucous fibrosis?",
     a:"Two steps from one habit: arecoline stimulates collagen synthesis, and tannin stabilises the collagen fibrils and makes them resistant to degradation. So the nut both lays collagen down and prevents its removal, which is why the fibrosis is progressive. Hypersensitivity to chilli, betel nut, tobacco and vitamin deficiencies alters collagen metabolism, producing juxtaepithelial progressive inflammatory fibrosis of the submucosa with epithelial atrophy and dysplasia.", ref:"SRB 3 p.360"},
    {id:"orc27", lv:2, type:"Examination", q:"This patient can barely open his mouth. What does that tell you, and what do you do about it?",
     a:"Trismus means either oral submucous fibrosis, where progressive submucosal fibrosis causes trismus and ankyloglossia, or a carcinoma invading deeply. B&L puts trismus with reduced tongue movement, sensory nerve deficit, otalgia and dysphagia as features of late-stage disease, and trismus from tumour involvement of the pterygoid musculature as a poor prognostic sign. Either way it is a problem in itself: it makes clinical examination of the mouth inadequate, and it is one of the indications for nasal rather than oral intubation. Measure and record the interincisal opening.", ref:"SRB 3 p.360 · B&L 53 p.818 · B&L 52 p.784, p.781, p.798"},
    {id:"orc28", lv:2, type:"Examination", q:"Which neck nodes would you expect this cancer to involve?",
     a:"Level I for the lip, anterior tongue and floor of the mouth; level II for the posterolateral oral cavity, tonsil and oropharynx, which is the commonest site of nodal enlargement and holds the jugulodigastric node. Examine both sides, because midline tongue and floor-of-mouth lesions drain bilaterally. For the lip, S Das's method for the submandibular nodes is to bend the head towards the side being palpated with one hand, relaxing platysma, and palpate with the other.", ref:"B&L 52 p.778 · Das 24 p.345"},
    {id:"orc29", lv:2, type:"Diagnosis", q:"A bluish translucent swelling in the floor of the mouth. What is it, and what else could it be?",
     a:"A ranula: a unilateral bluish translucent cyst over which Wharton's duct can often be seen, fluctuant with positive translucency. The alternative is a sublingual dermoid, which is opaque and not translucent, lies exactly in the midline, is tense and fluctuant, and may extend into the submental region.", ref:"Das 24 p.345, p.347"},
    {id:"orc30", lv:2, type:"Examination", q:"How do you work out the extent of a swelling in the floor of the mouth?",
     a:"Bimanual palpation, a finger in the floor of the mouth and the other hand on the submandibular triangle. It is how you find a deep or plunging ranula, which has a cervical prolongation into the submandibular region and can be obvious in the submandibular triangle. Carcinoma of the floor of the mouth shows itself by an indurated base and probable fixation to the structures beneath.", ref:"Das 24 p.345, p.347"},
    {id:"orc31", lv:2, type:"Investigation", q:"How would you investigate this lesion?",
     a:"Biopsy, always: an incisional or wedge biopsy of the lesion with a margin of normal mucosa, because biopsy is advocated for accurate diagnosis. The neck is assessed by ultrasound with guided sampling, preferring a core biopsy of a node because immunohistochemistry needs tissue. CT or MRI for the primary, for bone invasion and for the neck, and CT of the thorax where head and neck malignancy is suspected, to detect distant metastases. SRB adds laryngoscopy for a posterior third growth and an orthopantomogram for the mandible.", ref:"B&L 53 p.815 · B&L 52 p.780, p.781 · SRB 3 p.383"},
    {id:"orc32", lv:2, type:"Management", q:"A white patch in a 30-year-old who has never chewed or smoked. Does it still need a biopsy?",
     a:"Yes. Biopsy is advocated for accurate diagnosis whatever the history, and B&L records a rising incidence of oral cancer in patients of 45 years or younger, many of whom lack exposure to the traditional risk factors. Proliferative verrucous leukoplakia is itself not tobacco-related, so the absence of a habit is not reassurance.", ref:"B&L 53 p.815, p.813 · SRB 3 p.359"},

    {id:"orc40", lv:3, type:"Pathology", q:"Which premalignant lesion carries the highest risk, and what is the transformation rate?",
     a:"The highest-risk lesions are erythroleukoplakia or speckled leukoplakia, proliferative verrucous leukoplakia, and dyskeratosis congenita. On the rate, give the range and not a single figure: a 2016 review of observational studies found malignant transformation in oral leukoplakia varying from 0.13% to 34%, because the natural history remains unclear and the nomenclature is inconsistent internationally. SRB is the one that gives a hard number, for one lesion: proliferative verrucous leukoplakia, rare but aggressive, with 85% malignant potential, common in elderly women and not associated with tobacco. So B&L refuses a number and SRB gives one; answer with both, then with B&L's principle, that risk assessment of the individual lesion by size, location and carcinogen exposure, with biopsy, is the cornerstone of management.", ref:"B&L 53 p.815 · SRB 3 p.359"},
    {id:"orc41", lv:3, type:"Management", q:"What is the survival in oral cancer, and what would change it?",
     a:"Eighty per cent at five years for early-stage disease but 50% overall, and in South Asia often below 50%, with a reported five-year survival of 35% in India. The gap between 80% and 50% is stage at presentation, so what changes the figure is earlier presentation and stopping the habit, not any operative refinement. India's national screening programme includes cancer of the mouth alongside breast and cervix for all women aged 30 to 65.", ref:"B&L 53 p.813 · B&L 58 p.943"},
    {id:"orc42", lv:3, type:"Anatomy", q:"Where does the oral cavity end and the oropharynx begin, and why does the line matter?",
     a:"The anterior two-thirds of the tongue is oral cavity; the base of the tongue is oropharynx. It matters because the two differ in lymphatic drainage, in staging and in treatment, and because the posterior third drains early to the pharyngeal nodes, which carries a poor prognosis. SRB's anatomy explains why: the anterior two-thirds develops from the first arch and is supplied by the lingual nerve, with taste by the chorda tympani, while the posterior third develops from the third arch and is supplied by the glossopharyngeal nerve for both sensation and taste.", ref:"B&L 53 p.813 · SRB 3 p.379"},
    {id:"orc43", lv:3, type:"Diagnosis", q:"This patient has a massive tongue. What causes macroglossia?",
     a:"Lymphangioma, haemangioma and neurofibroma, and muscular macroglossia, which is commonly seen in cretins.", ref:"Das 24 p.342"},
    {id:"orc44", lv:3, type:"Examination", q:"The patient cannot protrude his tongue. Work through the possibilities.",
     a:"Tongue-tie, where the frenum linguae is short, thick and fibrous, so that on protrusion the lateral margin and tip evert with the dorsal mid part heaping up, causing a speech defect and difficulty cleaning the teeth; look for the short frenum. Or a late carcinoma of the tongue invading the floor of the mouth, in which case the tip deviates towards the side of the lesion. Or submucous fibrosis with ankyloglossia.", ref:"Das 24 p.341, p.344 · SRB 3 p.381, p.360"},
    {id:"orc45", lv:3, type:"Diagnosis", q:"An angioma-like swelling at the foramen caecum. What is it, and what is the trap?",
     a:"A lingual thyroid. The trap is that it may be the only thyroid gland the patient possesses, so it should not simply be removed.", ref:"Das 24 p.343"},
    {id:"orc46", lv:3, type:"Pathology", q:"What is hairy leukoplakia?",
     a:"A dense pigmented friable lesion, commonly on the tongue, common in patients with AIDS, and caused usually by Epstein-Barr virus. The name is a misnomer: there are no hairs, and the surface only looks hairy because of thickening and corrugation from severe hyperkeratosis and acanthosis.", ref:"SRB 3 p.359"},
    {id:"orc47", lv:3, type:"Diagnosis", q:"There are pigmented patches on the lips and buccal mucosa. What does that suggest?",
     a:"Pigmentation of the lips and buccal mucous membrane is seen in Addison's disease, and small bluish-black spots on the lips and the buccal and palatal mucosa are seen in Peutz-Jeghers syndrome, a familial autosomal dominant condition whose main pathology is adenomatous polyps of the small bowel, which may cause intussusception or intestinal colic but rarely turn malignant.", ref:"Das 24 p.342, p.345"},
    {id:"orc48", lv:3, type:"Diagnosis", q:"What is cancrum oris, and how does it start?",
     a:"It starts as a painful purple-red indurated papule on the alveolar margin near the molar or premolar teeth. An ulcer then forms which rapidly exposes the underlying bone and extends to the cheek and lip, with a foul smell. SRB classes it with phagedena, destruction without proliferation, and treats it with improved nutrition, penicillin and metronidazole; squamous cell carcinoma can occasionally develop in it.", ref:"Das 24 p.344 · SRB 1 p.27"},
    {id:"orc49", lv:3, type:"Pathology", q:"How does carcinoma of the tongue spread?",
     a:"Locally, from the anterior two-thirds into genioglossus, the floor of the mouth, the opposite side and the mandible; from the posterior third into tonsil, side of pharynx, soft palate, epiglottis, larynx and cervical spine. By lymphatics, from the tip to submental nodes, from the lateral margin to submandibular and then deep cervical nodes, and from the posterior third to pharyngeal and upper deep cervical nodes. SRB's four notes: a lesion more than 4 mm deep has a 30% chance of nodal metastasis; carcinoma tongue is the most aggressive of the oral cancers and has the highest incidence of nodal spread; bilateral spread is common because the lymph vessels cross; and the lingual node between tongue and submandibular gland should be cleared because it may hold micrometastasis.", ref:"SRB 3 p.383"},
    {id:"orc50", lv:3, type:"Examination", q:"What do you look for in the gums?",
     a:"Healthy gums are bright pink. The earliest sign of pyorrhoea alveolaris is a deep red line along the free edge. Vincent's stomatitis gives ulceration of the gingival margin with a pseudomembrane and a very bad smell. Gums become swollen, spongy, tender and bleeding in scurvy, and may bleed in uraemia without being as spongy. A blue line suggests lead exposure, and a swollen gum may be a dental abscess. An epulis is a swelling of the alveolar margin, and its margin, consistency, surface and mobility decide the type. Each lip must be everted fully, with a spatula and torch for the posterior gums.", ref:"Das 24 p.344, p.347"},
    {id:"orc51", lv:3, type:"Diagnosis", q:"A man's voice has changed and he has pain in one ear. Where is the tumour?",
     a:"In the posterior third of the tongue. Alteration of voice may be the first symptom of carcinoma of the posterior third and can go unnoticed for some time; pain on swallowing and pain referred to the ear belong there too, and tumours of the posterior third are more aggressive. They drain early to the pharyngeal nodes as well as the upper deep cervical nodes, and early pharyngeal nodal spread carries a poor prognosis.", ref:"Das 24 p.341 · SRB 3 p.379, p.383"},
  ],

  "cervical-lymphadenopathy": [
    {id:"cln01", lv:1, type:"Anatomy", q:"Give the levels of the cervical lymph nodes.",
     a:"Level I submental (Ia) and submandibular (Ib). Level II upper jugular, base of skull to hyoid. Level III middle jugular, hyoid to omohyoid or the cricothyroid membrane. Level IV lower jugular, down to the clavicle. Level V posterior triangle, including the supraclavicular nodes, between the posterior border of sternocleidomastoid and the anterior border of trapezius. Level VI anterior compartment, the central group including the thyroid, Delphian and paratracheal nodes. Level VII superior mediastinal. SRB calls it the Memorial Sloan Kettering levelling.", ref:"SRB 5 p.435 · B&L 52 p.778"},
    {id:"cln02", lv:1, type:"Anatomy", q:"Which level is the commonest site of enlargement, and what does it drain?",
     a:"Level II, which contains the jugulodigastric node and is also the most readily palpated. It drains the naso- and oropharynx including the tonsils, the posterolateral aspects of the oral cavity, and the superior aspects of the larynx and the piriform fossae.", ref:"B&L 52 p.778"},
    {id:"cln03", lv:1, type:"Diagnosis", q:"Give the differential diagnosis of cervical lymphadenopathy.",
     a:"Tuberculous lymphadenitis, secondaries in lymph nodes, HIV infection and lymphoma carry almost all the cases. Then chronic lymphatic leukaemia, non-specific lymphadenitis, infectious mononucleosis, sarcoidosis, actinomycosis, brucellosis and toxoplasmosis. In India add filarial lymphadenitis.", ref:"SRB 5 p.431 · Das 35 p.535"},
    {id:"cln04", lv:1, type:"Pathology", q:"Give the stages of tuberculous lymphadenitis.",
     a:"Five. One, infection and lymphadenitis. Two, periadenitis with matting. Three, caseating necrosis with cold abscess formation. Four, collar stud abscess. Five, formation of a sinus, which discharges. Every physical sign in the case belongs to one of those five stages, so name the stage rather than just the disease.", ref:"SRB 5 p.432"},
    {id:"cln05", lv:1, type:"Examination", q:"What does the consistency of the nodes tell you?",
     a:"Lymphoma: smooth, non-tender, firm, of India-rubber consistency, and discrete. Tuberculous: matted, and fluctuant once a cold abscess has formed. Secondary carcinoma: hard and nodular, discrete at first and fixed later. Acute pyogenic lymphadenitis: tender and warm.", ref:"SRB 5 p.431 · Das 35 p.535"},
    {id:"cln06", lv:1, type:"Examination", q:"What is matting, and what causes it?",
     a:"Adjacent nodes adherent to each other and to the surrounding tissue, so that they move as one mass. It is caused by periadenitis, inflammation spreading beyond the node capsule, and it is stage 2 of five. B&L calls a matted nodal mass the typical clinical feature of tuberculous cervical lymphadenitis, and it is the single most useful sign in this case.", ref:"SRB 5 p.432 · B&L 6 p.87"},
    {id:"cln07", lv:1, type:"Examination", q:"How do you palpate an enlarged lymph node?",
     a:"With the palmar aspects of three fingers, rolling them against the swelling with slight pressure maintained, so that you feel the actual consistency. Note the number, the situation, the local temperature, tenderness, the surface and the margin. For cervical nodes the patient sits on a stool and you palpate from behind, with the neck slightly flexed, because a patient who extends the neck obscures the swelling.", ref:"Das 8 p.111 · Das 26 p.366"},
    {id:"cln08", lv:1, type:"Anatomy", q:"Give the lymphatic drainage of the skin of the body.",
     a:"S Das divides the body by two horizontal lines, at the clavicle and at the umbilicus. Cervical nodes take the head, face, mouth, pharynx and neck. Axillary nodes take that upper limb and the trunk from clavicle to umbilicus, including the breast. Inguinal nodes take the whole lower limb and the skin below the umbilicus, with penis, scrotum, perineum, vulva, anus, buttock and the lower back, plus the ectodermal terminal parts of the anal canal, urethra and vagina. The left supraclavicular node takes the left upper limb, the left chest including the breast, and the abdominal viscera including both testes.", ref:"Das 8 p.113, p.112"},
    {id:"cln09", lv:1, type:"Diagnosis", q:"A hard node in the left supraclavicular fossa. What is it called?",
     a:"Virchow's node, and its presence is Troisier's sign. Classically it comes from carcinoma of the stomach, but also from pancreas, oesophagus, lung and testis. It is level IV or V, and it sends you to the abdomen.", ref:"SRB 20 p.841 · Das 8 p.112"},
    {id:"cln10", lv:1, type:"History", q:"Which group of nodes is affected first in which disease?",
     a:"The cervical group first in Hodgkin's disease and in tuberculosis; the inguinal group first in filariasis and lymphogranuloma inguinale; the epitrochlear and occipital groups in the secondary stage of syphilis. S Das's own caveat: do not lay too much stress on this point.", ref:"Das 8 p.109, p.110"},
    {id:"cln11", lv:1, type:"Examination", q:"What must you establish and record about a lump in the neck?",
     a:"B&L's printed list: the history; the physical signs; size; site; shape; surface; consistency; fixation, deep or superficial; pulsatility; compressibility; transillumination; and bruit. Run that list and nothing is left out.", ref:"B&L 52 p.805"},
    {id:"cln12", lv:1, type:"Examination", q:"What do you do before you touch this patient?",
     a:"Hand hygiene, introduce yourself and check the patient's name and date of birth, request a chaperone as appropriate, explain what you are going to do, obtain verbal consent, and make sure the patient is comfortable.", ref:"B&L 35 p.472 · B&L 21 p.285"},

    {id:"cln20", lv:2, type:"History", q:"What does the pattern of fever tell you?",
     a:"An evening rise in temperature is characteristic of tuberculosis, and B&L lists evening pyrexia with cough and malaise, and failure to thrive in a child. In filariasis a periodic fever is common, especially at the full or new moon. In Hodgkin's disease intermittent bouts of remittent fever, Pel-Ebstein fever, are peculiar to the disease.", ref:"Das 8 p.109 · B&L 6 p.87"},
    {id:"cln21", lv:2, type:"History", q:"Are these nodes painful? What does the answer mean?",
     a:"Nodes are painful in both acute and chronic lymphadenitis, and painless in syphilis, in primary malignant lymphomas and in secondary carcinoma. So a painless node is the one to be suspicious of, and a tender warm one is more likely to be reactive.", ref:"Das 8 p.109"},
    {id:"cln22", lv:2, type:"Pathology", q:"What is a collar stud abscess?",
     a:"A cold abscess that lies deep to the deep fascia and bursts through it into the space just beneath the superficial fascia, giving a bilocular or hourglass mass with cross-fluctuation: a deep collection and a superficial one joined by a narrow neck through the fascia. It is stage 4 of five, and if it bursts through the skin it discharges pus and becomes a tuberculous sinus.", ref:"B&L 6 p.87 · SRB 5 p.431, p.432"},
    {id:"cln23", lv:2, type:"Treatment", q:"How would you aspirate a cold abscess, and why that way?",
     a:"Zig-zag aspiration with a wide-bore needle through a non-dependent area, to prevent sinus formation. Wide bore because the pus is thick; zig-zag so the needle track does not become a straight channel to the surface; non-dependent so that gravity does not keep it draining. If it must be drained formally, use a non-dependent incision and close the wound later without placing a drain, because a drain track becomes a sinus. Send the pus for culture and sensitivity.", ref:"SRB 5 p.433 · B&L 6 p.87"},
    {id:"cln24", lv:2, type:"Examination", q:"What does the skin over the swelling tell you?",
     a:"In acute lymphadenitis the skin is inflamed, with redness, oedema and brawny induration. In chronic lymphadenitis it shows no such angriness. Over a tuberculous node or cold abscess it stays cold in the true sense until the abscess is at the point of bursting, when it becomes red and glossy. Over a rapidly growing lymphosarcoma it is tense and shining with dilated subcutaneous veins. In secondary carcinoma it is free early and becomes fixed late, when the disease is beyond the scope of surgery. A scar beside the swelling often means a cold abscess burst there, or a previous operation.", ref:"Das 8 p.111"},
    {id:"cln25", lv:2, type:"Diagnosis", q:"Periodic fever with simultaneous tenderness and swelling of the nodes, in an endemic area.",
     a:"Filarial lymphadenitis. Eosinophilia and the demonstration of microfilariae in blood drawn at night will clinch the diagnosis. The night sample is the detail that earns the mark, because of the nocturnal periodicity of the microfilariae.", ref:"Das 35 p.535"},
    {id:"cln26", lv:2, type:"Diagnosis", q:"Rapidly enlarging painless nodes in an otherwise well young patient.",
     a:"Lymphoma. S Das's wording is that lymphosarcoma gives rapid enlargement of the nodes without other complaints in a young subject. The nodes are smooth, non-tender, firm and of India-rubber consistency. Get a core biopsy rather than an FNAC, because the subtype determines the treatment, and examine every other node group with the liver and the spleen.", ref:"Das 35 p.535 · SRB 5 p.431 · B&L 52 p.781"},
    {id:"cln27", lv:2, type:"Examination", q:"The node is at level II. Where do you look for the primary?",
     a:"Level II sends you to the tonsil, nasopharynx and oropharynx, the posterolateral oral cavity, the superior larynx and the piriform fossa. Level I sends you to the lip, anterior tongue, floor of mouth and cheek; levels III and IV to the larynx, hypopharynx and thyroid; level IV or V on the left to the stomach, pancreas and lung; level VI to the thyroid. Say the level, then say where you are going to look.", ref:"B&L 52 p.778"},
    {id:"cln28", lv:2, type:"Examination", q:"You have examined the node. What else do you examine?",
     a:"The whole upper aerodigestive mucosa: lip, buccal mucosa, gingiva, hard and soft palate, anterior two-thirds and base of tongue, floor of mouth, tonsil and posterior pharyngeal wall, using gauze to aid the examination and palpating intraorally where needed. Then the thyroid, the breast and the abdomen, then every other node group with the liver and the spleen, because generalised lymphadenopathy with splenomegaly moves you towards lymphoma, leukaemia or systemic infection. And always the drainage area of the node, where an insignificant abrasion may be the whole explanation.", ref:"B&L 52 p.778 · Das 8 p.113"},
    {id:"cln29", lv:2, type:"Investigation", q:"How would you get a diagnosis from this node?",
     a:"An ultrasound-guided needle biopsy, and for a node prefer a core biopsy to an FNAC. B&L: needle sampling is the investigation of choice when determining the nature of a neck or thyroid mass, ultrasound-guided FNAC or core biopsy is the standard of care in many units, with CT guidance for deep-seated lesions, and core biopsy is the preferred technique for a neck node because immunohistochemistry can be performed on it. SRB uses FNAC throughout. Both are needling the node; the disagreement is only about which needle, and the reason settles it: FNAC can confirm a carcinoma but cannot subtype a lymphoma.", ref:"B&L 52 p.781 · SRB 5 p.433"},
    {id:"cln30", lv:2, type:"Investigation", q:"You think this is tuberculosis. What do you send, and what do you treat with?",
     a:"FNAC, acid-fast bacilli and culture are SRB's useful investigations, and B&L adds raised ESR and CRP, low haemoglobin, a Mantoux or an interferon-gamma release assay, sputum for Ziehl-Neelsen staining and culture, and aspiration of pus from a cold abscess for culture and sensitivity. Treatment is antituberculous drugs: mainly medical, with surgery for the abscess and not for the disease. Involvement of other systems must be excluded.", ref:"SRB 5 p.433 · B&L 6 p.87, p.88"},
    {id:"cln31", lv:2, type:"Examination", q:"What pressure effects would you look for?",
     a:"Swelling and venous engorgement of the face and neck from nodes at the root of the neck or in the superior mediastinum; oedema of the upper or lower limb from axillary or inguinal nodes; oedema and venous congestion of the legs from retroperitoneal and para-aortic nodes in Hodgkin's disease; dyspnoea from pressure on trachea or bronchus; and dysphagia from pressure on the oesophagus.", ref:"Das 8 p.109, p.111"},
    {id:"cln32", lv:2, type:"Investigation", q:"Would you test this patient for HIV?",
     a:"Yes. SRB lists HIV infection with lymph node involvement alongside tuberculous lymphadenitis and lymphoma in the differential diagnosis of neck node enlargement, and B&L notes that the increased prevalence of HIV worldwide has made tuberculosis more common. In India the two travel together, so offer the test.", ref:"SRB 5 p.431, p.433 · B&L 6 p.88"},

    {id:"cln40", lv:3, type:"Investigation", q:"Would you ever simply excise the node?",
     a:"Yes, in one situation the books name: B&L says that if a tuberculous nodal mass is still in the early stages of adenitis, excision biopsy should be done, with part of the node sent fresh and unfixed to a laboratory that has been warned of its arrival so the tissue is processed immediately. For a node that may be a metastasis from a head and neck primary, the first step is ultrasound-guided needle sampling, with core biopsy preferred, and the primary hunted by panendoscopy with biopsy of the likely sites. The familiar teaching that an open biopsy of such a node prejudices a later neck dissection is not stated in these three books, so do not attribute it to them.", ref:"B&L 6 p.87 · B&L 52 p.781"},
    {id:"cln41", lv:3, type:"Investigation", q:"The node is EBV positive and you cannot find a primary. Where do you look?",
     a:"The nasopharynx. B&L: biopsy of the fossa of Rosenmüller will reveal the site of the primary tumour in a patient with a malignant neck lump that shows EBV positivity. Nasopharyngeal carcinoma also gives unilateral deafness from Eustachian tube obstruction with secretory otitis media in about 20% of patients, and cranial nerve palsies from skull base disease occur late and are a poor prognostic sign, as is trismus from involvement of the pterygoid musculature.", ref:"B&L 52 p.784"},
    {id:"cln42", lv:3, type:"Examination", q:"The tongue deviates to the right on protrusion and there is a hard node high in the right neck. Explain it.",
     a:"Secondary carcinoma in the upper deep cervical nodes has involved the hypoglossal nerve, giving hemiparesis of that half of the tongue, which therefore deviates towards the side of the lesion on protrusion. S Das records the same nerve being involved by nodes of Hodgkin's disease or secondary carcinoma.", ref:"Das 8 p.113, p.111"},
    {id:"cln43", lv:3, type:"Pathology", q:"What would the histology of a tuberculous node show?",
     a:"Caseating material with Langhans-type giant cells, and the caseating type is more common than the hyperplastic type. The cut specimen shows yellowish caseating material with periadenitis, which is what you feel as matting. The cold abscess is the clinical manifestation of that underlying caseation.", ref:"SRB 5 p.432 · B&L 6 p.87"},
    {id:"cln44", lv:3, type:"Anatomy", q:"Why does an abdominal cancer declare itself in the left supraclavicular fossa, and is the node or the sign the eponym?",
     a:"Because the thoracic duct enters the venous system at that point, so malignant cells from an abdominal primary disseminate into that node easily. The node is Virchow's and the sign is Troisier's: Virchow described the node, and Troisier, forty years later, reported many abdominal cancers presenting with left supraclavicular involvement as an external indicator. S Das adds the laterality rule: supraclavicular nodes are involved on the same side in carcinoma of the breast or lung, but only on the left in carcinoma of the stomach or the testis.", ref:"SRB 20 p.841 · Das 8 p.112"},
    {id:"cln45", lv:3, type:"Diagnosis", q:"Which conditions give generalised lymphadenopathy?",
     a:"Hodgkin's disease, tuberculosis, lymphosarcoma, lymphatic leukaemia, brucellosis and sarcoidosis. S Das's instruction is that a general examination should always be done in any case of lymph node involvement, because it not infrequently reveals hidden generalised involvement of the lymphatic system.", ref:"Das 8 p.111, p.113"},
    {id:"cln46", lv:3, type:"Investigation", q:"What would an ultrasound add before you needle anything?",
     a:"It separates solid from cystic. B&L: ultrasound is useful in differentiating solid lesions, for example malignant lymph nodes, from cystic lesions such as a branchial cyst, and is particularly helpful when fine-needle aspiration is needed to establish the diagnosis; it is also invaluable in salivary gland pathology. SRB's differential for a tuberculous node is exactly those two, branchial cyst and lymph cyst.", ref:"B&L 52 p.780 · SRB 5 p.433"},
    {id:"cln47", lv:3, type:"Anatomy", q:"Divide level II, and say what the dividing structure is.",
     a:"The spinal accessory nerve. Level IIa lies below and in front of the nerve, level IIb above and posterior to it. Level II runs from the base of the skull to the hyoid, bounded by the lateral border of sternohyoid and the posterior border of sternocleidomastoid.", ref:"SRB 5 p.435 · B&L 52 p.778"},
    {id:"cln48", lv:3, type:"Investigation", q:"What would you do with a chest radiograph in this case?",
     a:"Look for pulmonary tuberculosis, for mediastinal nodes and for metastases. B&L adds that if a head and neck malignancy is suspected, CT imaging of the thorax should also be performed to detect distant metastases.", ref:"B&L 52 p.780"},
    {id:"cln49", lv:3, type:"Investigation", q:"The Mantoux test is positive. Does that settle it?",
     a:"No. B&L is explicit that a positive Mantoux is usual but is not significant in a patient from an endemic area, which in India means most patients. It has now been superseded by interferon-gamma release assays, an in vitro test of cellular immune response in which antigens unique to M. tuberculosis stimulate T-cell release of interferon-gamma, which earmarks latent or subclinical infection. The diagnosis is clinched by culture of the pus and biopsy of the node.", ref:"B&L 6 p.87"},
    {id:"cln50", lv:3, type:"Examination", q:"There is a discharging sinus in the neck. How would you describe the ulcer it leaves?",
     a:"A tuberculous ulcer with a watery discharge and undermined, overhanging edges, following a collar stud abscess that has burst through the skin. It is stage 5, the last of SRB's five, and it is usually iatrogenic in the sense that it follows drainage through a dependent incision or a drain track.", ref:"B&L 6 p.87 · SRB 5 p.432, p.433"},
  ],

  "neck-swellings": [
    {id:"nck01", lv:1, type:"Classification", q:"Classify the swellings of the neck by position.",
     a:"Midline: thyroglossal cyst, a swelling of the thyroid isthmus, subhyoid bursa, dermoid, enlarged prelaryngeal or Delphian node, retrosternal extension of a goitre. Upper anterior triangle: branchial cyst, parotid and submandibular swellings, carotid body tumour, lymph nodes, cold abscess. Lower anterior triangle: thyroid, lymph nodes, laryngocele, pharyngeal pouch. Posterior triangle: cystic hygroma, lymph nodes, cervical rib, lipoma, sternomastoid tumour. Any site: lymph nodes, cold abscess, lipoma, sebaceous cyst, neurofibroma, lymph cyst.", ref:"SRB 5 p.414 · SRB 6 p.448"},
    {id:"nck02", lv:1, type:"Examination", q:"What signs must you establish and record in any neck lump?",
     a:"B&L's own instruction: size, site, shape, consistency, fixation to skin or deep structures, pulsation, compressibility, transillumination and the presence of a bruit, all established and recorded, alongside the history, the surface and the margin. Pulsation and bruit are on that list because of the carotid body tumour, and transillumination because of the cystic hygroma.", ref:"B&L 52 p.805"},
    {id:"nck03", lv:1, type:"Examination", q:"Which neck swelling is brilliantly transilluminant?",
     a:"The cystic hygroma, and B&L says this is the characteristic that distinguishes it from all other neck swellings, which is as strong a claim as the book makes for any sign.", ref:"B&L 52 p.805 · SRB 5 p.424"},
    {id:"nck04", lv:1, type:"Examination", q:"Which neck swellings move on swallowing, and why?",
     a:"Those adherent to the larynx or trachea: thyroid swellings, a thyroglossal cyst and subhyoid bursitis. S Das adds the trap: tuberculous and malignant lymph nodes also move on deglutition once they become fixed to the larynx or trachea.", ref:"Das 26 p.366"},
    {id:"nck05", lv:1, type:"Examination", q:"What moves upwards when the patient protrudes the tongue, and why?",
     a:"A thyroglossal duct cyst. The thyroglossal duct develops from the median bud of the pharynx, and the foramen caecum at the junction of the anterior two-thirds and posterior third of the tongue is the vestigial remnant of the duct, so the tract runs from there in close continuity with, and sometimes through, the hyoid.", ref:"B&L 55 p.850 · Das 27 p.377, p.378"},
    {id:"nck06", lv:1, type:"Pathology", q:"What is a cystic hygroma?",
     a:"A cystic swelling due to sequestration of a portion of the jugular lymph sac from the lymphatic system during development in utero, the lymphatics failing to communicate with the venous system, with abnormal budding of lymphatics. It contains clear lymph with an endothelial lining, and the fluid does not coagulate. B&L: the cysts are filled with clear lymph and lined by a single layer of epithelium with a mosaic appearance. The synonym is cavernous lymphangioma.", ref:"SRB 5 p.424 · B&L 52 p.805"},
    {id:"nck07", lv:1, type:"Pathology", q:"Where does a branchial cyst come from, and where and when does it present?",
     a:"From the vestigial remnants of the second branchial cleft, lined by squamous epithelium and containing thick turbid fluid. It presents in the upper neck in early or middle adulthood, at the junction of the upper third and middle third of sternocleidomastoid at its anterior border. It is fluctuant, may transilluminate, and is often soft in its early stages so that it can be difficult to palpate.", ref:"B&L 52 p.805 · SRB 5 p.419"},
    {id:"nck08", lv:1, type:"Examination", q:"Where does a branchial fistula open?",
     a:"The external orifice is nearly always in the lower third of the neck near the anterior border of sternocleidomastoid, and the internal orifice on the anterior aspect of the posterior faucial pillar. S Das gives the same site as typical. If it opens only onto the lateral pharyngeal wall it is a sinus and not a fistula.", ref:"B&L 52 p.805 · Das 26 p.366"},
    {id:"nck09", lv:1, type:"History", q:"How does the patient's age narrow a neck swelling?",
     a:"Sternomastoid tumour in the newborn, often with a history of difficult labour. Cystic hygroma in infancy or early childhood. Branchial cyst and fistula, though congenital, more often in early adult life. Inflammatory swellings at any age but commonly in early adults. Carcinomatous swellings in the old.", ref:"Das 26 p.364"},
    {id:"nck10", lv:1, type:"Examination", q:"How do you palpate a swelling in the neck?",
     a:"From behind, with the patient sitting on a stool. The patient's natural tendency is to extend the neck, which obscures the swelling, so flex the neck passively with one hand on the head and palpate with the other. B&L gives the same method: examine from behind, one side at a time, with the chin flexed slightly downwards and the neck tilted towards the side being palpated, to remove tension in the strap muscles, platysma and sternocleidomastoid. Ask the patient to point to the lump first, and ask whether it is tender.", ref:"Das 26 p.366 · B&L 52 p.779"},
    {id:"nck11", lv:1, type:"Examination", q:"How far do you expose the neck, and which area is forgotten?",
     a:"Up to the level of the nipples, with the patient sitting, so that both clavicles are clearly seen. The forgotten area is the supraclavicular fossa, and enlargement of the left supraclavicular nodes matters for carcinoma of the breast and of many abdominal organs.", ref:"Das 26 p.364 · B&L 52 p.779"},
    {id:"nck12", lv:1, type:"Examination", q:"What do you do before you touch this patient?",
     a:"Hand hygiene, introduce yourself and check the patient's name and date of birth, request a chaperone as appropriate, explain what you are going to do, obtain verbal consent, and make sure the patient is comfortable.", ref:"B&L 35 p.472 · B&L 21 p.285"},

    {id:"nck20", lv:2, type:"History", q:"What do the duration and the pain tell you?",
     a:"Swellings with a long history are generally benign, and tuberculous lymphadenopathy and cold abscess usually give a history of more than a month; a swelling grown quickly in a short span is mostly a malignant tumour, though acute lymphadenitis is also short. Inflammatory swellings are always painful, which separates acute lymphadenitis from a malignant growth: the first is extremely painful, the second painless until late when nerves are involved. A submandibular swelling that appears with meals and hurts is calculous obstruction of the submandibular duct.", ref:"Das 26 p.364"},
    {id:"nck21", lv:2, type:"Examination", q:"How do you decide whether a swelling is deep or superficial to sternomastoid?",
     a:"Put the muscle into action and watch the swelling. To test one side, place your hand against the side of the chin opposite the lesion and ask the patient to nod the head to that side against your resistance; to test both, put your hand under the point of the chin and ask the patient to press down against resistance. A swelling deep to the muscle disappears under the taut muscle, completely or partly, and its mobility becomes restricted; a swelling superficial to it becomes more prominent and stays mobile.", ref:"Das 26 p.367"},
    {id:"nck22", lv:2, type:"Examination", q:"Give the signs of a cystic hygroma.",
     a:"In the posterior triangle; smooth, soft, fluctuant, partially compressible, brilliantly transilluminant, and not completely reducible. It visibly increases in size when the child coughs or cries, and it may be bilateral. SRB names the thing that worries the family more than the swelling: disfigurement of the child's face.", ref:"SRB 5 p.424 · B&L 52 p.805"},
    {id:"nck23", lv:2, type:"Diagnosis", q:"Does a cystic hygroma only occur in the neck?",
     a:"No. Besides the neck it may involve the face, the submandibular region, the tongue and the floor of the mouth, and less frequently the cheek, axilla, groin and mediastinum. Tongue or floor-of-mouth involvement makes it an airway problem rather than a lump.", ref:"B&L 52 p.805"},
    {id:"nck24", lv:2, type:"Investigation", q:"You aspirate a lateral neck cyst in a young adult. What would it show?",
     a:"Cholesterol crystals, which is SRB's classical finding on FNAC of a branchial cyst. The wall shows plenty of lymphoid tissue, which is why one proposed origin is epithelial inclusion within a lymph node, and MRI allows finer resolution for preoperative planning.", ref:"SRB 5 p.420"},
    {id:"nck25", lv:2, type:"Examination", q:"A pulsatile neck swelling with a bruit. What is it, and what must you not do?",
     a:"A carotid body tumour, a paraganglioma. SRB's rule is three prohibitions: no FNAC, no trucut biopsy, no partial excision, because it is vascular and partial excision leaves disease on the carotid. It is the one neck swelling where the right answer to \"would you aspirate it?\" is an emphatic no, and it is why pulsatility and bruit are on B&L's list of signs for every neck lump.", ref:"SRB 5 p.429 · B&L 52 p.805"},
    {id:"nck26", lv:2, type:"Treatment", q:"A fluctuant, non-tender neck swelling with no warmth and no redness. What is it and how do you treat it?",
     a:"A cold abscess, from tuberculous lymph nodes or spine. Aspirate zig-zag with a wide-bore needle through a non-dependent area to prevent sinus formation; if formal drainage is needed, use a non-dependent incision and close later without placing a drain. Send material for acid-fast bacilli, culture and cytology, examine the spine, and treat with antituberculous drugs.", ref:"SRB 5 p.433"},
    {id:"nck27", lv:2, type:"Examination", q:"Which neck swellings are compressible, and what distinguishes them?",
     a:"A cystic hygroma is partially compressible and increases on crying or coughing. A laryngocele enlarges on Valsalva. A pharyngeal pouch may empty on pressure and gurgle. Compressibility is on B&L's list of signs to establish for exactly this reason.", ref:"SRB 5 p.424, p.414 · B&L 52 p.805"},
    {id:"nck28", lv:2, type:"Examination", q:"There is a fold of skin standing out above the swelling. What does that mean?",
     a:"The skin and platysma are infiltrated by growth, and S Das calls that fold a characteristic feature of secondary carcinoma of the lymph nodes. Redness and oedema mean inflammation, and dilated subcutaneous veins over a swelling suggest lymphosarcoma.", ref:"Das 26 p.366"},
    {id:"nck29", lv:2, type:"Examination", q:"There is a sinus in the neck. What are you looking at?",
     a:"A tuberculous sinus or ulcer from a burst caseous node, whose undermining edge is typical, often with a puckered scar after healing. A single sinus a little below the jaw suggests osteomyelitis of the mandible; multiple sinuses over an indurated mass high in the neck suggest actinomycosis, and sulphur granules in the pus are confirmatory. A branchial fistula lies just in front of the lower third of the anterior border of sternomastoid.", ref:"Das 26 p.366"},
    {id:"nck30", lv:2, type:"Investigation", q:"How would you investigate a neck swelling of uncertain nature?",
     a:"Ultrasound first, because its best use here is separating solid from cystic, that is a malignant node from a branchial cyst, and because it guides the needle; it is also invaluable in salivary pathology. Then ultrasound-guided FNAC or core biopsy, preferring core for a node because immunohistochemistry needs tissue. MRI for preoperative planning in a branchial cyst, and CT of the thorax if a head and neck malignancy is suspected. Do not needle a pulsatile swelling.", ref:"B&L 52 p.780, p.781 · SRB 5 p.420, p.429"},
    {id:"nck31", lv:2, type:"Diagnosis", q:"An infant with a neck swelling and a twisted head.",
     a:"A sternomastoid tumour with torticollis, which SRB groups together and which S Das links to a difficult labour in the newborn. It is not a tumour but a fibrous contracture within the muscle belly, so it becomes less distinct when the muscle is put into action. S Das also notes torticollis in acute or tuberculous cervical lymphadenitis.", ref:"SRB 5 p.414 · Das 26 p.364, p.366"},
    {id:"nck32", lv:2, type:"Treatment", q:"How is a thyroglossal cyst treated?",
     a:"Sistrunk's operation: excision of the cyst and the whole thyroglossal tract up to the foramen caecum, including removal of the central part, the body, of the hyoid bone, because the tract passes through or close behind it, together with a core of tissue on either side. It minimises recurrence, most notably from small side branches of the tract, and an incomplete excision is what recurs.", ref:"B&L 52 p.806, p.807 · SRB 6 p.448"},

    {id:"nck40", lv:3, type:"Management", q:"A 50-year-old has a cystic swelling in the upper lateral neck. Would you excise it?",
     a:"Not before excluding malignancy. In a young adult at the junction of the upper and middle thirds of sternomastoid this would be a branchial cyst, confirmed on ultrasound and aspiration, and excised when quiescent. But B&L 28e warns that in patients over 35 years of age a high index of suspicion for a necrotic metastatic lymph node should exist, and malignancy should be excluded before excision. SRB's differential for a branchial cyst is entirely benign, cold abscess, lipoma, lymph cyst and chronic lymphadenitis, so this is the one place the two books part company, and the consequence of the error is not a recurrence but a worse cancer operation, since excising a metastatic node breaches its capsule and compromises the definitive neck dissection.", ref:"B&L 52 p.805, p.780 · SRB 5 p.420"},
    {id:"nck41", lv:3, type:"Procedure", q:"Which structures are at risk when you excise a branchial cyst?",
     a:"The cyst passes superficial to the hypoglossal and glossopharyngeal nerves but deep to the posterior belly of digastric, and those structures together with the spinal accessory nerve must be positively identified to avoid damage. Excision must be complete and is best undertaken when the lesion is quiescent.", ref:"B&L 52 p.805"},
    {id:"nck42", lv:3, type:"Investigation", q:"How would you investigate a carotid body tumour, and what else could it be?",
     a:"By imaging, and SRB names a pentetreotide scan using a radiolabelled somatostatin analogue for paragangliomas. The differential is a carotid artery aneurysm, a soft tissue sarcoma, lymph node enlargement, and a vagal neurofibroma, which presents in the carotid triangle as a vertically placed, oval, hard swelling.", ref:"SRB 5 p.429"},
    {id:"nck43", lv:3, type:"Anatomy", q:"Explain how a branchial cyst forms, and what lies superficial and deep to a branchial fistula.",
     a:"Normally the second, third and fourth clefts disappear to leave a smooth neck. A persistent second cleft is the cervical sinus of His, which becomes sequestered to form the cyst. S Das's rule for the fistula follows the same embryology: structures developed from the second branchial arch lie superficial to the tract, and those from the third and fourth arches lie deep to it.", ref:"SRB 5 p.419 · Das 26 p.364"},
    {id:"nck44", lv:3, type:"Complications", q:"Can a branchial fistula be acquired?",
     a:"Yes. SRB: rupture of a branchial cyst may cause an acquired branchial fistula, at the upper third of sternocleidomastoid rather than the lower third where the congenital one opens. The cyst's complications are recurrent infection and rupture producing that fistula.", ref:"SRB 5 p.420"},
    {id:"nck45", lv:3, type:"Examination", q:"A hard swelling in the posterior triangle with tingling in the hand. How would you test it?",
     a:"Suspect a cervical rib and do Adson's manoeuvre: the radial pulse disappears when the patient takes a deep breath and turns the head, which tightens the scalenes and unmasks the arterial obstruction. SRB notes that first rib resection can be done thoracoscopically through three ports.", ref:"SRB 1 p.166 · SRB 5 p.419"},
    {id:"nck46", lv:3, type:"Diagnosis", q:"Separate a laryngocele from a pharyngeal pouch, and give the risks of operating on a laryngocele.",
     a:"Both lie in the lower anterior triangle and both are compressible and may gurgle; a laryngocele enlarges on Valsalva, while a pharyngeal pouch may empty on pressure. Both are on SRB's list of neck swellings. The operative complications of a laryngocele are laryngocutaneous fistula, injury to the superior or internal laryngeal nerve, and recurrence.", ref:"SRB 5 p.424, p.414"},
    {id:"nck47", lv:3, type:"Diagnosis", q:"Which neck swellings are not short cases at all?",
     a:"Ludwig's angina, and parapharyngeal and retropharyngeal abscess, all three on SRB's list of neck conditions. Ludwig's angina is a rapidly progressive polymicrobial cellulitis of the sublingual and submandibular spaces involving the floor of the mouth and the suprahyoid area on both sides, commonest after dental infection of the second or third molar; there is diffuse painful swelling with woody brawny induration, non-fluctuant, with bilateral submandibular oedema and a bull's neck appearance, toxic features, drooling and difficulty with speech, and the cellulitis may extend into the pharyngomaxillary space, the retropharynx and the superior mediastinum. SRB's general rule is that cellulitis should never be incised, and names Ludwig's angina as one of the exceptions. An acute retropharyngeal abscess is suppuration of the retropharyngeal nodes, most often in children under one year; the chronic form occurs almost solely in adults, from tuberculosis of the cervical spine, with bone destruction and loss of the normal cervical curvature on radiology.", ref:"SRB 5 p.414 · SRB 1 p.36, p.35 · B&L 52 p.787, p.788"},
    {id:"nck48", lv:3, type:"Examination", q:"The sinus in this patient's neck discharges mucus. What does that tell you?",
     a:"That it is branchial. SRB's rule is that mucus discharge from a neck fistula means a branchial origin, and the reason is the lining: the tract of a branchial fistula is lined by ciliated columnar epithelium, so the discharge is recurrently mucopurulent. An MR sinusogram is beneficial in working out the tract.", ref:"SRB 1 p.31, p.33 · B&L 52 p.805"},
    {id:"nck49", lv:3, type:"Examination", q:"What would you look for on the face and chest in a patient with neck nodes?",
     a:"Venous engorgement of the face and upper chest from pressure of cervical lymphadenopathy on the jugular vein, torticollis from acute or tuberculous cervical lymphadenitis or a sternomastoid tumour, and wasting of muscles where enlarged nodes press on nearby nerves.", ref:"Das 26 p.366"},
    {id:"nck50", lv:3, type:"Pathology", q:"When does a cystic hygroma present, and what is the obstetric consequence?",
     a:"Usually in the neonate or early infancy, and it may be present at birth and large enough to obstruct labour. Both books make that point, which is why it is worth saying.", ref:"SRB 5 p.424 · B&L 52 p.805"},
    {id:"nck51", lv:3, type:"Examination", q:"The swelling turns out to be a lymph node. What must your answer include?",
     a:"The level, because the level is where the primary is. All five palpable levels, I to V, should be examined systematically, and if malignancy is suspected, that is a hard, irregular node, or one fixed to the overlying skin or to deep structures, then inspection of the whole upper aerodigestive tract mucosa is mandatory.", ref:"SRB 5 p.435 · B&L 52 p.779"},
    {id:"nck52", lv:3, type:"Examination", q:"The midline swelling moves on tongue protrusion. Does that prove it is a thyroglossal cyst?",
     a:"Not on its own. B&L is explicit that although the cyst classically moves upwards on swallowing and with tongue protrusion, this can also occur with other midline cysts such as a dermoid, because it merely indicates attachment to the hyoid bone. Two further warnings in the same passage: the cyst may lie slightly off the midline near the thyroid cartilage, and rarely what looks like a thyroglossal cyst is an incompletely migrated thyroid gland containing the only functioning thyroid tissue in the body, which is why ultrasound is used to confirm the cyst and the presence of a normally sited thyroid before operating.", ref:"B&L 52 p.806"},
  ],

  "ulcer": [
    {id:"ulc01", lv:1, type:"Pathology", q:"Define an ulcer and name its parts.",
     a:"A disruption or break in the continuity of any lining, whether skin, mucous membrane or other, and one of the types of wound. Its parts are the margin, the edge, the floor and the base.", ref:"SRB 1 p.1, p.15 · Das 4 p.64"},
    {id:"ulc02", lv:1, type:"Examination", q:"Distinguish edge from margin, and floor from base.",
     a:"The margin is the junction of normal skin with the ulcer; the edge is the area between the margin and the floor, and S Das is explicit that the two terms should not be confused. The floor is what you can see, the exposed surface; the base is what the ulcer rests on, which may be bone or soft tissue, and it is palpated rather than looked at. Palpating the base instead of only describing the floor is the commonest thing candidates get wrong.", ref:"Das 4 p.63, p.64 · SRB 1 p.15"},
    {id:"ulc03", lv:1, type:"Examination", q:"Name the types of edge and what each means.",
     a:"Sloping: a healing ulcer. Undermined: tuberculous. Punched out: gummatous, that is syphilitic, and trophic. Raised, beaded and pearly-white: rodent ulcer, a basal cell carcinoma. Everted or rolled out: squamous cell carcinoma. And the inflamed, irregular, oedematous edge of a spreading ulcer.", ref:"SRB 1 p.15, p.16 · Das 4 p.63, p.64"},
    {id:"ulc04", lv:1, type:"Examination", q:"Describe this ulcer to me.",
     a:"In order: site; size and shape; edge; floor; and base, which is palpated. Then the surrounding skin, the discharge, and the regional lymph nodes. Name the edge and the diagnosis usually names itself; everything after that is confirmation.", ref:"SRB 1 p.15 · Das 4 p.63, p.64"},
    {id:"ulc05", lv:1, type:"Classification", q:"Give the clinical classification of ulcers, with the findings of each.",
     a:"Spreading: inflamed, irregular, oedematous edge; floor with no healthy granulation, profuse purulent discharge and slough; red oedematous surroundings; nodes enlarged and tender; acutely painful. Healing: sloping edge; healthy pink or red granulation with scanty serous discharge and no slough; no surrounding inflammation; nodes may be enlarged but are always non-tender. Chronic or callous: indolent, often thickened edge; unhealthy pale flat granulation; fibrosed surroundings; usually painless.", ref:"SRB 1 p.16, p.19"},
    {id:"ulc06", lv:1, type:"Classification", q:"Classify ulcers pathologically.",
     a:"Specific: tuberculous, syphilitic, actinomycotic. Malignant: carcinomatous, rodent and melanotic. Non-specific: traumatic, which may be mechanical, physical or chemical and is the commonest; arterial, from atherosclerosis or thromboangiitis obliterans; venous or gravitational; trophic or neuropathic; and the ulcers of systemic disease, which SRB lists as anaemia, polycythaemia, sickle cell disease, hereditary spherocytosis, leukaemia, vasculitis and autoimmune disease.", ref:"SRB 1 p.17, p.29 · Das 4 p.68, p.69"},
    {id:"ulc07", lv:1, type:"Examination", q:"How does the site of an ulcer help you?",
     a:"S Das's map: cutaneous tuberculosis on the face, fingers and hand, with lupus vulgaris on the face; Hunterian chancre and soft sores on the external genitalia; gummatous ulcers over subcutaneous bones such as the tibia, sternum and skull; perforating or trophic ulcers on the heel or the ball of the foot, which carries maximum body weight; and malignant ulcers anywhere but commonly on the lips, tongue, breast, penis and anus.", ref:"Das 4 p.63"},
    {id:"ulc08", lv:1, type:"Examination", q:"What is induration, and where is it best felt?",
     a:"A clinical palpatory sign meaning a specific type of hardness in the diseased tissue. It is obvious in well-differentiated carcinomas and is better felt in squamous cell carcinoma. Palpate the base and the margin between finger and thumb, and report it as a finding separate from the edge.", ref:"SRB 1 p.15"},
    {id:"ulc09", lv:1, type:"Examination", q:"What does the granulation tissue tell you?",
     a:"Healthy, pink or red, flat granulation means a healing ulcer. Unhealthy, pale, flat granulation means a chronic non-healing or callous ulcer. Exuberant granulation, proud flesh, protrudes out of the ulcer bed like a proliferating mass.", ref:"SRB 1 p.16, p.19"},
    {id:"ulc10", lv:1, type:"Investigation", q:"Where would you take the biopsy from, and why not the floor?",
     a:"From the edge, including a margin of adjacent normal skin, because the edge is where the active disease is and where the architecture that gives the diagnosis survives; the floor is slough and granulation tissue and will not be diagnostic. In a chronic non-healing ulcer biopsy is mandatory rather than optional, with culture, because a chronic wound unresponsive to dressings requires biopsy and culture study before definitive treatment.", ref:"SRB 1 p.4"},
    {id:"ulc11", lv:1, type:"Examination", q:"Where is a venous ulcer, and where is it never?",
     a:"Around the ankle: vertically oval, commonly on the medial side, occasionally lateral, sometimes both, but never above the middle third of the leg. It is due to ambulatory chronic venous hypertension, and it is initially painful but becomes painless once chronicity develops.", ref:"SRB 1 p.27"},
    {id:"ulc12", lv:1, type:"Examination", q:"What do you do before you examine this ulcer?",
     a:"Hand hygiene, introduce yourself and check the patient's name and date of birth, request a chaperone as appropriate, explain what you are going to do, obtain verbal consent, and make sure the patient is comfortable. Examine the tender part last, and watch the patient's face rather than only your hands.", ref:"B&L 35 p.472 · B&L 21 p.285"},

    {id:"ulc20", lv:2, type:"Examination", q:"Why is a tuberculous ulcer's edge undermined, and how would you demonstrate it?",
     a:"Because the disease process advances in the deeper plane, in the subcutaneous tissue, while the epidermis proliferates inwards over it, leaving the skin edge overhanging an undermined cavity. The bedside proof is that a probe can be insinuated easily between the edge and the floor. S Das adds the rest of the picture: the edge is thin, reddish-blue and undermined, the floor has pale granulation with scanty serosanguineous discharge, the base is slightly indurated, and the regional nodes are enlarged, non-tender and matted.", ref:"SRB 1 p.15 · Das 4 p.63, p.70"},
    {id:"ulc21", lv:2, type:"Pathology", q:"Why is a gummatous ulcer punched out?",
     a:"Endarteritis. The tissue dies in a block because its artery dies, so the edge drops vertically rather than sloping or being undermined. The same mechanism gives the punched-out edge of a trophic ulcer.", ref:"SRB 1 p.15"},
    {id:"ulc22", lv:2, type:"Diagnosis", q:"An ulcer near the medial malleolus. Arterial or venous, and how do you decide?",
     a:"S Das's discriminator is the malleolus itself: a venous ulcer usually occurs above the medial malleolus, an arterial ulcer tends to occur below it. Then the pain: a venous ulcer is painless once chronic, while pain is the main complaint in arterial disease, with a history of intermittent claudication and often rest pain. Elevating the leg above heart level makes an arterial ulcer hurt more and shows no sign of healing. The arterial ulcer is punched out with destruction of the deep fascia, tendon, bone or joint may be exposed in the floor, granulation is minimal, and the dorsalis pedis pulse is almost always feeble or absent, with pallor, dry skin, loss of hair and nail fissuring.", ref:"Das 4 p.69"},
    {id:"ulc23", lv:2, type:"Diagnosis", q:"A painless ulcer on the ball of the foot. What is it, and what must you test?",
     a:"A trophic or neuropathic ulcer at the site of maximum weight bearing. Test sensation, because loss of sensation is the cause: the ulcer results from repeated trauma to an insensitive part. S Das's causes are spinal disease, leprosy, peripheral nerve injury, diabetic neuropathy, tabes dorsalis, transverse myelitis and meningomyelocele, and in a non-ambulatory patient the sites are the buttock and the back of the heel instead. B&L illustrates bilateral trophic ulceration of the feet from anaesthesia in leprosy.", ref:"Das 4 p.70, p.63 · B&L 6 p.80"},
    {id:"ulc24", lv:2, type:"Examination", q:"What do the regional nodes add?",
     a:"Enlarged and tender nodes mean active infection, as in a spreading ulcer. Enlarged but non-tender nodes in a healing ulcer are reactive hyperplasia. Enlarged, non-tender and matted nodes go with a tuberculous ulcer. Stony hard nodes suggest secondary involvement by carcinoma, and S Das's warning in a malignant ulcer is that nodes may be enlarged because of secondary infection rather than anything else, so palpation of the nodes matters but their enlargement alone does not prove metastasis.", ref:"SRB 1 p.16 · Das 4 p.67, p.70"},
    {id:"ulc25", lv:2, type:"History", q:"What would you ask this patient?",
     a:"How it started and how long ago, since a long history suggests a benign cause. Whether there was trauma or a burn, because a malignant ulcer, Marjolin's, may develop on the scar of a burn. Whether it is painful. Whether the sensation around it is normal. Whether there are varicose veins, claudication or diabetes, because the three commonest chronic leg ulcers are venous, arterial and neuropathic. And any contact with tuberculosis, weight loss or evening fever.", ref:"Das 4 p.61 · SRB 1 p.16, p.17"},
    {id:"ulc26", lv:2, type:"Investigation", q:"How would you investigate this ulcer?",
     a:"Biopsy from the edge, and in a chronic non-healing ulcer that is mandatory. Discharge for culture, and for acid-fast bacilli where tuberculosis is possible: SRB's sequence in a tuberculous ulcer is discharge study, biopsy, then antituberculous drugs. Ankle-brachial pressure index and duplex, because you must know the arterial supply before compressing or grafting anything. Blood glucose and sensation testing for the diabetic and neuropathic foot. And a radiograph of the underlying bone if the base is bone, for osteomyelitis or a sequestrum.", ref:"SRB 1 p.4, p.17, p.31"},
    {id:"ulc27", lv:2, type:"Treatment", q:"How would you treat a chronic non-healing ulcer?",
     a:"Treat the cause, not the hole. Biopsy and culture it first. Then prepare the bed: debridement, control of infection, and vacuum-assisted closure where available. Scoop out proud flesh and look for the retained foreign body. Close it with a skin graft once there is healthy granulation, or a flap where the base is bone or tendon. Then deal with the cause: the venous hypertension, with a definitive procedure for the varicose veins after evaluation; revascularisation for the arterial supply; offloading and glycaemic control; or antituberculous drugs.", ref:"SRB 1 p.4, p.18, p.19"},
    {id:"ulc28", lv:2, type:"Examination", q:"There is exuberant granulation standing out of the ulcer. What does that mean, and what do you do?",
     a:"Proud flesh, granulation protruding out of the ulcer bed or sinus opening like a proliferating mass. SRB gives the reason it matters: it is commonly associated with a retained foreign body. It should be scooped out using a Volkmann's scoop before skin grafting. A pyogenic granuloma is a type of it, a well-localised red swelling that bleeds on touching.", ref:"SRB 1 p.19"},
    {id:"ulc29", lv:2, type:"Diagnosis", q:"What is a rodent ulcer?",
     a:"The ulcerative form of basal cell carcinoma, common on the face. B&L: a slow-growing, locally invasive malignant tumour of pluripotential epithelial cells arising from the basal epidermis and hair follicles, so it affects pilosebaceous skin; the risk factor is ultraviolet radiation; 90% are nodular or nodular cystic, and it is divided into high- and low-risk types. Its edge is raised, beaded and pearly-white. It is locally invasive and does not metastasise, which is what rodent means: it gnaws.", ref:"SRB 1 p.24, p.15 · B&L 45 p.651"},
    {id:"ulc30", lv:2, type:"Treatment", q:"How would you manage a diabetic foot ulcer?",
     a:"SRB's list: control the diabetes with insulin, antibiotics, nutritional supplements, regular cleaning, debridement and dressing, and cover with a skin graft or flap once it granulates. Revascularisation by endarterectomy, thrombectomy, balloon angioplasty or arterial bypass, though the success rate is lower when distal vessels are involved. Amputation of toe, foot or leg where it comes to that. And microcellular rubber footwear with care of the foot, to prevent further injury. S Das's three mechanisms explain why all of that is needed: neuropathy, atherosclerotic ischaemia, and glucose-laden tissue vulnerable to infection.", ref:"SRB 1 p.26 · Das 4 p.70"},
    {id:"ulc31", lv:2, type:"Diagnosis", q:"What is a tropical ulcer?",
     a:"An ulcer of the legs and feet of people in tropical countries, associated with malnutrition, which S Das attributes to infection by Vincent's organisms, Bacteroides fusiformis, entering through a small abrasion or an insect bite. Its most important feature is its callousness towards healing: the edge is slightly raised, it exudes copious serosanguineous discharge, and it retains the same size for months or years, though it may spread widely and destroy surrounding tissue until amputation is needed.", ref:"Das 4 p.68, p.70, p.75"},
    {id:"ulc32", lv:2, type:"Diagnosis", q:"What is lupus vulgaris, and what is the apple-jelly nodule?",
     a:"A form of cutaneous tuberculosis, commonest on the face, hand and forearm, and usually in children and young adults. It starts as a typical apple-jelly nodule with congestion of the skin around it, and eventually a superficial ulcer with an undermined edge forms. The nodule is demonstrated by pressing a glass slide firmly on the skin, which blanches the congestion and leaves the apple-jelly colour visible.", ref:"SRB 1 p.26 · Das 4 p.70, p.63"},

    {id:"ulc40", lv:3, type:"Pathology", q:"What is Marjolin's ulcer, and does it metastasise?",
     a:"A squamous cell carcinoma arising in a long-standing unstable scar, classically a burn scar or after snake bite. The classical teaching, which is SRB's, is that it is well differentiated and does not spread through lymphatics or blood, and the reason is that the scar is relatively avascular and alymphatic, so there is no route for early spread; its treatment is wide local excision with skin grafting, block dissection of nodes being reserved for ordinary squamous carcinoma. B&L 28e gives only the definition, that when an SCC appears in a scar it is known as Marjolin's ulcer, and makes no exception at all for its behaviour, listing scars among the risk factors for squamous carcinoma alongside sun exposure, chronic wounds and immunosuppression. So give the classical claim with its mechanism, then treat it as a squamous carcinoma and follow the nodes, because once it grows beyond the scar into vascularised tissue it can metastasise.", ref:"SRB 1 p.24 · B&L 45 p.652"},
    {id:"ulc41", lv:3, type:"Diagnosis", q:"What is Bazin's ulcer?",
     a:"S Das: an ulcer found in fatty adolescent girls, particularly on the calves, appearing as purplish nodules followed by indolent ulcers.", ref:"Das 4 p.69"},
    {id:"ulc42", lv:3, type:"Diagnosis", q:"What is Martorell's ulcer?",
     a:"The hypertensive ulcer, found in people with hypertension, usually on the leg, where patches of skin necrosis are first noticed; S Das describes a local patch of skin on the back or outer side of the calf suddenly necrosing and sloughing away, in old age and with atherosclerosis. His point about classification is the examinable one: it cannot be put in the arterial group, because it is not generally associated with atherosclerosis.", ref:"Das 4 p.69, p.74"},
    {id:"ulc43", lv:3, type:"Diagnosis", q:"What is Meleney's ulcer?",
     a:"Postoperative progressive bacterial synergistic gangrene, described in 1924. It is commonly seen in postoperative wounds of the abdomen and chest wall, after empyema drainage, lung abscess or surgery for peritonitis, and occasionally in the limbs, where it can arise de novo with ulcerative colitis or in a pre-existing venous ulcer; it is common in the old and the immunosuppressed. B&L uses the name differently, for necrotising fasciitis of the abdominal wall, with Fournier's gangrene as its scrotal counterpart, treated by radical repeated excision with oxygen and penicillin, so say which you mean.", ref:"SRB 1 p.26 · B&L 5 p.58 · B&L 33 p.456, p.457"},
    {id:"ulc44", lv:3, type:"Diagnosis", q:"An arterial ulcer in a man of thirty. What are you thinking?",
     a:"Buerger's disease, thromboangiitis obliterans, which affects younger men between 20 and 40, where patches of dry gangrene may accompany the ulcer. Arterial ulcers are rarer than venous, and in the older patient atherosclerosis is the commonest cause, followed by Buerger's and Raynaud's. They occur on the anterior and outer aspects of the leg, the dorsum of the foot, the toes or the heel, the parts exposed to trauma.", ref:"Das 4 p.69"},
    {id:"ulc45", lv:3, type:"Diagnosis", q:"Which systemic diseases give ulcers, and how?",
     a:"S Das: gout, where the skin over a tophus ulcerates and the chalky contents exude; diabetes, where slight injury to glucose-laden tissue causes chronic infection, or ischaemia from atherosclerosis and polyneuropathy does; and anaemia, avitaminosis, erythrocyanosis frigida and rheumatoid arthritis. SRB adds polycythaemia, sickle cell disease, hereditary spherocytosis, leukaemia, vasculitis and autoimmune disease.", ref:"Das 4 p.69 · SRB 1 p.29"},
    {id:"ulc46", lv:3, type:"Treatment", q:"A basal cell carcinoma on the side of the nose. Is there anything better than wide excision?",
     a:"B&L names Mohs' micrographic surgery for difficult sites, developed by Mohs in 1938 for cutaneous malignant lesions; it allows complete excision with the narrowest possible margin, which is what matters on the face.", ref:"B&L 45 p.652"},
    {id:"ulc47", lv:3, type:"Classification", q:"What makes an ulcer callous, and why can you not just dress it?",
     a:"A callous ulcer has an indolent, often thickened edge, unhealthy pale flat granulation in the floor, and fibrosed surroundings, and it is usually painless; the base is indurated, which is what tells you it is chronic. SRB's rule for chronic wounds is that they are unresponsive to dressing treatment and require biopsy, culture study and definitive treatment such as debridement, vacuum-assisted closure, skin grafting or a flap. So dressings alone are not a plan, and the biopsy is there to find the carcinoma in the scar.", ref:"SRB 1 p.19, p.4 · Das 4 p.70"},
    {id:"ulc48", lv:3, type:"Pathology", q:"How does a trophic ulcer form, step by step?",
     a:"It starts with a callosity, under which suppuration takes place; the pus escapes and the central hole becomes the ulcer, which gradually burrows through muscles and tendons down to bone. The result is a callous ulcer with a punched-out corny edge, a floor covered with offensive slough through which tendon and even bone can be seen, a slightly indurated base, and surrounding skin with no sensation.", ref:"Das 4 p.70"},
    {id:"ulc49", lv:3, type:"Examination", q:"An ulcer over the front of the tibia with the edge stuck to the bone.",
     a:"A gummatous ulcer. S Das places it over the convexity of an anteriorly bowed tibia, with the edges densely adherent to the bone, which forms its base, and the edge punched out from endarteritis. Gummatous ulcers sit over subcutaneous bones: tibia, sternum, skull.", ref:"Das 4 p.75, p.63 · SRB 1 p.15"},
    {id:"ulc50", lv:3, type:"Examination", q:"Why should the three zones of a healing ulcer's edge be described, not just called sloping?",
     a:"Because the zones are the evidence of healing and they are what the examiner is listening for. From the centre outwards: red granulation tissue, then a blue zone of thin growing epithelium, which SRB explains as the middle part being blue due to epithelial proliferation, then a white zone of scar. A sloping edge with those zones is also the edge of a venous ulcer once it granulates well.", ref:"Das 4 p.64 · SRB 1 p.15, p.27"},
  ],

  "salivary-swelling": [
    {id:"slv01", lv:1, type:"Anatomy", q:"Why are the facial nerve and lymph nodes inside the parotid gland?",
     a:"Because of its embryology. Unlike other glands the parotid does not become encapsulated early to form a regular gland, and the other structures in the vicinity, the vessels, nerves and lymphatics, develop before encapsulation, so they end up enveloped within it. The facial nerve is enveloped as the gland grows laterally, dividing it into the surgical superficial and deep lobes, with about 80% of the functional gland superficial and the deep lobe largely the retromandibular component with minimal gland tissue. Most of the lymph nodes lie in the superficial, preauricular, lobe lateral to the masseter.", ref:"B&L 54 p.831, p.832"},
    {id:"slv02", lv:1, type:"Examination", q:"What is the curtain sign, and why does it happen?",
     a:"A parotid swelling cannot be moved above the zygomatic bone, because the deep fascia is attached above to the zygoma and acts as a curtain. It goes with a smooth, firm, lobulated, mobile swelling in front of the ear, often with a raised ear lobule.", ref:"SRB 4 p.402"},
    {id:"slv03", lv:1, type:"Examination", q:"Where is the parotid gland, and what does a parotid swelling do to the surface anatomy?",
     a:"It lies below, behind and slightly in front of the lobule of the ear, so a swelling of the gland obliterates the normal hollow just below the ear lobule. S Das stresses that position because lymph node swellings here are often mistaken for a parotid tumour and the reverse.", ref:"Das 25 p.354"},
    {id:"slv04", lv:1, type:"Anatomy", q:"Where does the parotid duct open?",
     a:"Stensen's duct passes over the masseter and enters the buccal mucosa through the buccinator at the level of the upper second molar tooth. Inspect that orifice in every parotid case, for pus or a stone.", ref:"B&L 54 p.832"},
    {id:"slv05", lv:1, type:"Pathology", q:"Is a salivary gland tumour likely to be benign?",
     a:"It depends which gland. Over 80% of salivary gland tumours occur in the major glands and the majority of those are benign; minor salivary gland tumours in contrast are more likely to be malignant, over 50%. So the smaller the gland, the likelier the malignancy.", ref:"B&L 54 p.838"},
    {id:"slv06", lv:1, type:"Pathology", q:"What is the commonest benign salivary tumour, and the commonest malignant one?",
     a:"Pleomorphic adenoma, mostly in the parotid, is the commonest benign neoplasm; mucoepidermoid carcinoma is the commonest malignant tumour. SRB adds that epithelial tumours account for 90%.", ref:"B&L 54 p.838 · SRB 4 p.400"},
    {id:"slv07", lv:1, type:"Examination", q:"How do you palpate the submandibular gland, and how does that separate it from a lymph node?",
     a:"Bimanually. With the mouth open, place one finger on the floor of the mouth medial to the alveolus and lateral to the tongue, pressed as far back as possible, and the fingers of the other hand outside, just medial to the inferior margin of the mandible, pushed upwards. That palpates both the superficial and deep parts of the gland and finds a calculus. The discriminator is the mylohyoid: the finger inside the mouth can feel the deep part of the gland, which lies above mylohyoid, but not lymph nodes, which lie below it.", ref:"Das 25 p.359"},
    {id:"slv08", lv:1, type:"Examination", q:"What must you test before the examiner asks, and what does it mean?",
     a:"The facial nerve, all five branches. B&L: a sudden increase in size, or facial nerve palsy, is associated with malignant transformation, and SRB lists facial nerve palsy among the features of malignancy, with difficulty closing the eyelid, blowing and clenching the teeth. So a palsy with a parotid swelling means malignancy until proved otherwise. Facial nerve function is also one of the four things B&L says must be weighed in planning the operation. The caveat, from SRB: facial nerve involvement is late in mucoepidermoid carcinoma of the parotid, so an intact nerve does not exclude a malignant tumour.", ref:"B&L 54 p.839, p.846 · SRB 4 p.402, p.405"},
    {id:"slv09", lv:1, type:"Pathology", q:"Where do salivary calculi occur, and how often are they radio-opaque?",
     a:"SRB's two figures: 80% are in the submandibular gland, and 80% are radio-opaque. They are commonly calcium phosphate and calcium carbonate, single in 75% of cases, and only 1% occur in the sublingual gland.", ref:"SRB 4 p.396"},
    {id:"slv10", lv:1, type:"History", q:"The swelling becomes tense and painful during meals. What is it?",
     a:"Obstruction of the duct by a stone, or a stricture, with colicky pain at meals and the gland swelling at the same time. It is the one history in this case that makes the diagnosis before you touch the patient.", ref:"Das 25 p.354"},
    {id:"slv11", lv:1, type:"Examination", q:"What do you look for inside the mouth?",
     a:"The duct orifice opposite the upper second molar, for pus or a stone; the whole length of the duct, palpated bimanually, to exclude an impacted stone; and the tonsil and uvula, because a deep lobe tumour deviates the uvula and pharyngeal wall towards the midline. SRB's instruction is that a deep lobe parotid tumour is examined per orally.", ref:"SRB 4 p.402 · Das 25 p.359 · B&L 54 p.832"},
    {id:"slv12", lv:1, type:"Examination", q:"What do you do before you touch this patient?",
     a:"Hand hygiene, introduce yourself and check the patient's name and date of birth, request a chaperone as appropriate, explain what you are going to do, obtain verbal consent, and make sure the patient is comfortable.", ref:"B&L 35 p.472 · B&L 21 p.285"},

    {id:"slv20", lv:2, type:"Examination", q:"How would you show that this swelling is in the gland and not superficial to it?",
     a:"Ask the patient to clench the teeth and test the mobility of the swelling over the contracted masseter. That, with the position below and in front of the ear lobule, the raised lobule and the curtain sign, places it in the gland. For the deep lobe, add the bimanual examination with one finger inside the mouth just in front of the tonsil.", ref:"Das 25 p.355 · SRB 4 p.402"},
    {id:"slv21", lv:2, type:"Pathology", q:"Why are calculi so much commoner in the submandibular gland?",
     a:"SRB's list: the secretion is viscous and rich in mucin, it contains more calcium, drainage is non-dependent, there is consequent stasis, and the duct hooks around the nerve. Parotid secretion in contrast is serous with less calcium, so stones there are uncommon.", ref:"SRB 4 p.396"},
    {id:"slv22", lv:2, type:"Diagnosis", q:"Both parotids are enlarged. What are you thinking?",
     a:"A systemic cause rather than a tumour. S Das: generalised enlargement of all the major salivary glands including the lacrimal glands is Mikulicz's syndrome, and with dry eyes and generalised arthritis it is Sjögren's syndrome. Mumps is the commonest cause of bilateral parotitis. SRB's chapter adds sialosis, sialectasis and parotid lymphoma.", ref:"Das 25 p.354 · SRB 4 p.392"},
    {id:"slv23", lv:2, type:"Diagnosis", q:"Separate acute parotitis from a parotid abscess.",
     a:"Acute parotitis is painful, and in a dehydrated patient with poor oral hygiene it presents as sudden enlargement of both parotids with considerable pain. A parotid abscess gives a brawny oedematous swelling of the parotid region, with throbbing or excruciating pain, slight swelling and redness. Mumps is the commonest cause of bilateral parotitis and is non-suppurative, often starting unilaterally and becoming bilateral within days, with constitutional disturbance.", ref:"Das 25 p.354, p.359"},
    {id:"slv24", lv:2, type:"Examination", q:"Which features would make you call this swelling malignant?",
     a:"SRB's list for a salivary swelling turning malignant: nodularity, involvement of the skin with ulceration, involvement of the masseter, facial nerve palsy, involvement of the neck lymph nodes, restriction of jaw movements, and eventually bone. Add pain, rapid growth and a hard consistency. B&L's equivalent is that a sudden increase in size or a facial nerve palsy is associated with malignant transformation.", ref:"SRB 4 p.402 · B&L 54 p.839 · Das 25 p.354"},
    {id:"slv25", lv:2, type:"Diagnosis", q:"A parotid lump present for ten years has suddenly grown and become painful.",
     a:"Malignant transformation of a pleomorphic adenoma, carcinoma ex pleomorphic adenoma, which S Das describes in exactly those words: a slow-growing tumour of years or months that suddenly starts growing rapidly and becomes painful is highly suggestive of malignant transformation of the mixed parotid tumour. It is on SRB's list of salivary carcinomas.", ref:"Das 25 p.354 · SRB 4 p.400"},
    {id:"slv26", lv:2, type:"Diagnosis", q:"A slow-growing painless swelling at the angle of the jaw in an older man who smokes.",
     a:"Warthin's tumour, adenolymphoma, a monomorphic adenoma. B&L: Warthin's tumours are commoner in older men, and there is a strong association with smoking, while pleomorphic adenomas are slightly commoner in women. S Das adds the site, which is the examinable part: adenolymphoma arises in the lower part of the parotid at the level of the lower border of the mandible, slightly lower than the usual site of a pleomorphic adenoma.", ref:"B&L 54 p.838 · Das 25 p.354 · SRB 4 p.400"},
    {id:"slv27", lv:2, type:"Investigation", q:"Would you biopsy this parotid lump?",
     a:"Not by open or incisional biopsy. Use ultrasound, which is invaluable for salivary gland pathology, with ultrasound-guided FNAC or core biopsy, which is the standard of care for determining the nature of such a mass. The reason B&L gives for condemning enucleation applies to anything that breaches the capsule: it may cause capsular breach and tumour spillage, increasing local recurrence. Open biopsy is also on SRB's list of causes of a salivary fistula.", ref:"B&L 52 p.780, p.781 · B&L 54 p.840 · SRB 4 p.399"},
    {id:"slv28", lv:2, type:"Investigation", q:"You suspect a stone and the plain film is normal. What now?",
     a:"A normal film does not exclude a stone, because only 80% are radio-opaque; in such cases CT scanning or ultrasound is used. An occlusal view is the film for a submandibular stone, and SRB notes that parotid stones are the radiolucent ones, identified by sialography rather than plain radiography.", ref:"B&L 54 p.837 · SRB 4 p.396"},
    {id:"slv29", lv:2, type:"Investigation", q:"What does a sialogram show, and when must you not do one?",
     a:"Findings: narrowing from a stricture, a grape-like cluster appearance in sialectasis, dilatations, communications in a fistula, and mass lesions. Never in acute inflammation, and it is contraindicated in acute suppurative sialadenitis; it is also not useful in neoplasm. Only 1 ml of dye is injected, because more causes extravasation and chemical sialadenitis, and antibiotics and anti-inflammatories are given afterwards for the same reason.", ref:"SRB 4 p.395, p.396"},
    {id:"slv30", lv:2, type:"Treatment", q:"What operation would you offer for a pleomorphic adenoma of the parotid?",
     a:"Surgery is the first-line treatment. If only the superficial lobe is involved, superficial parotidectomy, removing the parotid superficial to the facial nerve; if both lobes are involved, total conservative parotidectomy, retaining the facial nerve. B&L's spectrum of increasing radicality runs extracapsular dissection, adequate parotidectomy, superficial parotidectomy, total conservative parotidectomy, radical parotidectomy.", ref:"SRB 4 p.403 · B&L 54 p.846"},
    {id:"slv31", lv:2, type:"Complications", q:"What is Frey's syndrome, and how do you prevent it?",
     a:"Gustatory sweating: sweating and flushing of the skin over the parotid region while eating, in some patients after parotidectomy, which B&L links to the gland's secretomotor supply travelling with mixed sympathetic and parasympathetic fibres. The mechanism is aberrant regeneration, cut parasympathetic secretomotor fibres growing into the sweat glands of the overlying skin, so a stimulus that should produce saliva produces sweat. Prevent it by separating the subcutaneous gland and overlying skin from the auriculotemporal nerve at closure.", ref:"B&L 54 p.833, p.848"},
    {id:"slv32", lv:2, type:"Examination", q:"The patient reports watery discharge from a sinus near the gland, worst at meals.",
     a:"A parotid fistula. S Das gives that history as significant of one, and SRB's causes are after superficial parotidectomy, after drainage of a parotid abscess or a ruptured abscess, after biopsy, and trauma.", ref:"Das 25 p.354 · SRB 4 p.399"},

    {id:"slv40", lv:3, type:"Treatment", q:"Enucleation is condemned. Why is extracapsular dissection not the same thing?",
     a:"Because one breaches the capsule and the other never opens it. Enucleation shells the tumour out of its capsule, leaving the capsule and the pseudopods pushing through it behind, and SRB gives recurrence as 50% for that reason, while B&L says it may result in capsular breach and tumour spillage and should be avoided. Extracapsular dissection removes the tumour with its capsule intact and a cuff of normal gland, dissecting in the plane outside the capsule: the fascia is incised in a cruciate or curvilinear manner to expose the tumour, which is then dissected in an extracapsular plane while visualising the facial nerve branches. It needs no formal facial nerve dissection, which reduces temporary facial palsy, and is reported to be as safe as parotidectomy for selected benign tumours. In an Indian examination lead with superficial parotidectomy and offer extracapsular dissection as the modern alternative; never offer enucleation.", ref:"SRB 4 p.403 · B&L 54 p.840, p.846, p.848"},
    {id:"slv41", lv:3, type:"Treatment", q:"How would you plan the operation?",
     a:"B&L's four considerations, in order: the presumed tumour histology; the relation of the tumour to the facial nerve plane, Patey's faciovenous plane; the location of the tumour, particularly deep lobe involvement; and facial nerve function. Adequate parotidectomy means removing the tumour with a cuff of normal tissue in tail-of-parotid lesions, preserving function, though a cuff is not always possible when the lump abuts the nerve.", ref:"B&L 54 p.846"},
    {id:"slv42", lv:3, type:"Anatomy", q:"How is the facial nerve found at operation?",
     a:"By the retromandibular vein, which generally lies deep to the facial nerve and is a constant landmark useful during the retrograde method of identifying the main trunk. The plane the nerve defines is Patey's faciovenous plane.", ref:"B&L 54 p.832, p.846"},
    {id:"slv43", lv:3, type:"Complications", q:"Name the complications of parotidectomy.",
     a:"Temporary facial palsy, commonly seen in the lower branches; permanent facial nerve injury; Frey's syndrome; salivary fistula; haematoma, which is why a suction drain is anchored beneath the posterior belly of digastric and brought out posterior to the suture line; and numbness.", ref:"B&L 54 p.848"},
    {id:"slv44", lv:3, type:"Complications", q:"A salivary fistula after parotid surgery. Which type, and how do you treat it?",
     a:"SRB gives an incidence of 0.2 to 3% and two types. A duct fistula after superficial parotidectomy is profuse and often persistent: ligate the duct with a non-absorbable suture as far anteriorly as possible, so that saliva from the deep lobe still drains normally, and note that if the common duct is ligated the deep lobe simply atrophies without a fistula. A gland fistula, from the raw surface after superficial parotidectomy, is mild and settles within a month with anticholinergic drugs, and Jacobson's tympanic neurectomy stops the secretion completely.", ref:"SRB 4 p.399"},
    {id:"slv45", lv:3, type:"Pathology", q:"Which salivary malignancy is the most aggressive, and where is it common?",
     a:"Adenoid cystic carcinoma: SRB calls it very aggressive, about 10% of salivary carcinomas, and common in the minor salivary glands. For the rest of the proportions: mucoepidermoid is the commonest malignancy, acinic cell carcinoma about 1%, squamous cell carcinoma about 2%, with adenocarcinoma, carcinoma ex pleomorphic adenoma and undifferentiated carcinoma making up the rest.", ref:"SRB 4 p.400"},
    {id:"slv46", lv:3, type:"Classification", q:"Classify the salivary gland tumours.",
     a:"SRB: adenomas, that is pleomorphic adenoma and the monomorphic adenomas, adenolymphoma or Warthin's tumour, oncocytoma or oxyphil adenoma seen in the elderly and in the parotid, and the rare basal cell adenoma. Then the carcinomas: mucoepidermoid, acinic cell, adenoid cystic, adenocarcinoma, squamous cell, carcinoma ex pleomorphic adenoma and undifferentiated carcinoma. The formal scheme is the WHO classification, first published in 1972 and last updated in 2017.", ref:"SRB 4 p.400 · B&L 54 p.838"},
    {id:"slv47", lv:3, type:"Pathology", q:"What is known about the cause of salivary tumours?",
     a:"Radiation exposure is implicated in both benign and malignant salivary tumours, and there is a strong association of smoking with Warthin's tumour. Also implicated: viral infections, environmental factors, and industrial exposure including rubber manufacturing, nickel compounds and hair dyes.", ref:"B&L 54 p.838"},
    {id:"slv48", lv:3, type:"Treatment", q:"The facial nerve has to be sacrificed. What then?",
     a:"Reconstruct it, using cable grafts from either the greater auricular nerve or the sural nerve.", ref:"B&L 54 p.848"},
    {id:"slv49", lv:3, type:"Investigation", q:"How radio-opaque are salivary stones, exactly? The books give different answers.",
     a:"Take the three together. SRB: 80% of stones are in the submandibular gland and 80% are radio-opaque, with parotid stones described as radiolucent, not seen on a plain film and identified by sialography. B&L: only 80% of stones are radio-opaque, so a normal film does not exclude one, and CT or ultrasound is then used. S Das: the majority of stones here are radio-opaque, so plain radiography is very helpful. Nobody contradicts anyone on the number; what differs is the inference, and the safe answer is B&L's, that a negative plain film does not exclude a stone.", ref:"SRB 4 p.396 · B&L 54 p.837 · Das 25 p.359"},
    {id:"slv50", lv:3, type:"Pathology", q:"Does the gland involved change the odds of malignancy? Give the figures.",
     a:"S Das: approximately 90% of salivary neoplasms occur in the parotid, 10% in the submandibular gland, and very rarely in the sublingual and ectopic glands; about three-quarters of parotid epithelial lesions are clearly benign, while in the submandibular gland the majority of tumours are malignant. B&L puts it the other way round, that over 80% of tumours are in the major glands and most of those are benign, with minor gland tumours over 50% malignant. The two are compatible if you keep the submandibular gland separate, and the safe formulation is that the risk of malignancy rises as the gland gets smaller.", ref:"Das 25 p.360 · B&L 54 p.838"},
    {id:"slv51", lv:3, type:"Diagnosis", q:"Recurrent parotid swelling at meals, with purulent saliva from the duct.",
     a:"Subacute or chronic parotitis, which may be unilateral or bilateral: the gland feels firmer, slightly tender and rubbery, and the diagnosis is confirmed if purulent or watery saliva can be expressed from the duct orifice while gentle pressure is applied over the gland. The chronic childhood form is sialectasis, dilatation of the ductules and alveoli, usually in one gland, with attacks beginning in infancy, and a sialogram shows the grape-like cluster.", ref:"Das 25 p.360, p.359 · SRB 4 p.396"},
  ],

  "varicocele": [
    {id:"vrc01", lv:1, type:"Pathology", q:"Define a varicocele, and say which veins are involved.",
     a:"An abnormal dilatation and enlargement of the scrotal venous plexus draining the testis: dilatation and tortuosity of the pampiniform plexus, and so of the testicular veins. The veins draining the testis and epididymis form the pampiniform plexus and gradually join each other as they traverse the inguinal canal.", ref:"B&L 86 p.1563 · SRB 26 p.1063"},
    {id:"vrc02", lv:1, type:"Pathology", q:"Give the incidence figures for varicocele.",
     a:"Varicoceles affect 10 to 20% of adult males, about 90% are left sided, and if a left varicocele is identified there is a 30 to 40% probability that the condition is bilateral. They are unusual in boys and typically develop during late childhood and adolescence. The figure that matters most: they occur in around 15 to 20% of all males but are found in about 40% of infertile males.", ref:"B&L 86 p.1563"},
    {id:"vrc03", lv:1, type:"Anatomy", q:"Why are 90% of varicoceles on the left?",
     a:"Because of the drainage asymmetry: the right testicular vein drains into the low-pressure inferior vena cava below the right renal vein, while the left drains into the left renal vein. Three consequences: the left vein is longer, so the column of blood it supports is taller; it enters the renal vein at a right angle rather than obliquely; and it drains into a higher-pressure vein rather than directly into the cava. S Das adds two more reasons: at times the left testicular artery arches over the left renal vein and compresses it, and the loaded left colon may press on the left testicular vein.", ref:"B&L 86 p.1563 · Das 39 p.613 · SRB 26 p.1063"},
    {id:"vrc04", lv:1, type:"Examination", q:"Describe the findings in a varicocele.",
     a:"A soft, irregular swelling in the upper scrotum behind and above the testis, classically a bag of worms, separate from the testis, which should be palpable normally below it. It appears when the patient stands and disappears when he lies down with the scrotum elevated. SRB adds that patients often take it for an additional testis.", ref:"Das 39 p.613 · SRB 26 p.1063"},
    {id:"vrc05", lv:1, type:"History", q:"Who gets a varicocele?",
     a:"SRB: tall, thin young men. B&L: unusual in boys, typically developing during late childhood and adolescence, and affecting 10 to 20% of adult males. S Das adds the occupational point, that prolonged standing may be a cause.", ref:"SRB 26 p.1063 · B&L 86 p.1563 · Das 39 p.611"},
    {id:"vrc06", lv:1, type:"History", q:"What symptoms does a varicocele cause?",
     a:"Early on an aching or dragging pain, particularly after prolonged standing, with a swelling that appears on standing and goes on lying down. Most cause neither symptoms nor infertility, which is why most need no treatment.", ref:"Das 39 p.613 · B&L 86 p.1563"},
    {id:"vrc07", lv:1, type:"Examination", q:"Is there a cough impulse, and what is it like?",
     a:"Yes, and it is thrill-like rather than the typical expansile impulse of a hernia. B&L says plainly that there may be a cough impulse and that the veins empty when the patient lies down. The sign settles nothing on its own, because a cough impulse is shared by a hernia, a varicocele, a saphena varix, a lymph varix and an undescended testis with an associated hernia.", ref:"Das 39 p.612, p.613 · B&L 86 p.1563 · B&L 64 p.1061"},
    {id:"vrc08", lv:1, type:"Classification", q:"Grade this varicocele using B&L's system.",
     a:"By palpability. Subclinical: not palpable or visible at rest or on Valsalva, but shown by special tests such as Doppler ultrasound. Grade 1: palpable during Valsalva only. Grade 2: palpable at rest but not visible. Grade 3: visible and palpable at rest. B&L calls it useful in clinical practice, and it is, because every rung is something you do at the bedside.", ref:"B&L 86 p.1564"},
    {id:"vrc09", lv:1, type:"Examination", q:"What do you do before you examine this patient's scrotum?",
     a:"Hand hygiene, introduce yourself and check the name and date of birth, explain what you are going to do and why, obtain verbal consent, and make the patient comfortable. This examination is intimate, so a chaperone is not a courtesy: B&L says a chaperone should be present especially for intimate examinations, and that this should be part of a local guideline or policy. Offer one whatever your sex and the patient's, say you have offered, and say you would record it. If consent is refused, explain again, offer a chaperone, document the refusal, and do not proceed.", ref:"B&L 21 p.285 · B&L 35 p.472"},
    {id:"vrc10", lv:1, type:"Examination", q:"Why must the patient be examined standing?",
     a:"Because a varicocele is a venous lesion that fills against gravity, so it is seen and felt standing and decompresses on lying down. Failure to decompress on lying flat is the finding that sends you to image the abdomen.", ref:"B&L 86 p.1563"},
    {id:"vrc11", lv:1, type:"Examination", q:"What else must you measure, and why?",
     a:"The size of both testes. Testicular atrophy on the affected side is objective evidence of harm and is one of the accepted indications for repair, particularly in an adolescent. Ultrasound can measure the volume properly.", ref:"B&L 86 p.1564, p.1563"},

    {id:"vrc20", lv:2, type:"Examination", q:"How do you show that a varicocele fills from below?",
     a:"S Das's test: occlude the superficial inguinal ring with the thumb while the patient is lying down, then ask him to stand up. The varicocele still fills, and it fills from below, because the blood is coming up the pampiniform plexus rather than down through the canal.", ref:"Das 39 p.613"},
    {id:"vrc21", lv:2, type:"Diagnosis", q:"A varicocele of recent onset in a middle-aged man. What must you do?",
     a:"Examine the kidney and image the abdomen, because a rapid onset of varicocele suggests carcinoma of the kidney: the tumour spreads along the lumen of the renal vein on the left, or the inferior vena cava on the right, and obstructs the testicular vein. The same applies to a right-sided varicocele or one that does not decompress on lying down. Image the abdomen rather than operating on the scrotum.", ref:"Das 39 p.613 · B&L 86 p.1563"},
    {id:"vrc22", lv:2, type:"Diagnosis", q:"A soft doughy swelling of the cord that appears on standing, in a man from an endemic area.",
     a:"A lymph varix, lymphangiectasis: the lymphatic vessels of the cord dilated and tortuous from filarial obstruction. The history is periodic attacks of fever with simultaneous pain and swelling of the cord; the swelling appears on standing and disappears on lying down, though more slowly than a varicocele; the cough impulse is thrill-like, not expansile; and it feels soft, cystic and doughy. Eosinophilia and living microfilariae in blood drawn at night are diagnostic.", ref:"Das 39 p.614"},
    {id:"vrc23", lv:2, type:"Diagnosis", q:"Give the differential diagnosis of an inguinoscrotal swelling other than a hernia.",
     a:"S Das's list: encysted hydrocele of the cord, varicocele, lymph varix or lymphangiectasis, funiculitis, diffuse lipoma of the cord, inflammatory thickening of the cord extending up from testis and epididymis, malignant extension from the testis, ectopic testis, undescended testis, torsion, retractile testis, enlarged external iliac and inguinal nodes, an inguinal abscess, and an aneurysm of the external iliac artery.", ref:"Das 39 p.613"},
    {id:"vrc24", lv:2, type:"Pathology", q:"What is the relationship between varicocele and infertility?",
     a:"Varicoceles occur in around 15 to 20% of all males but are found in about 40% of infertile males, which is a strong association. The proposed mechanisms are raised scrotal temperature from pooled venous blood impairing spermatogenesis, venous stasis with hypoxia, and reflux of adrenal metabolites down the left testicular vein, with testicular atrophy as the visible end point. B&L is candid that the exact association between reduced male fertility and varicocele is unknown, and SRB's own note concedes it is a debate whether it really causes subfertility.", ref:"B&L 86 p.1563, p.1564 · SRB 26 p.1064"},
    {id:"vrc25", lv:2, type:"Investigation", q:"How would you investigate this varicocele?",
     a:"Scrotal ultrasound with Doppler, which confirms the dilated plexus, demonstrates reflux, and measures testicular volume; it is also what identifies a subclinical varicocele. Semen analysis where fertility is the issue, before and after any intervention, because the semen parameters and not the size of the varicocele are what justify operating. And ultrasound or CT of the abdomen for a right-sided, sudden-onset or non-decompressing varicocele, to exclude a renal or retroperitoneal mass.", ref:"B&L 86 p.1563, p.1564 · SRB 26 p.1064"},
    {id:"vrc26", lv:2, type:"Management", q:"When would you treat a varicocele, and when would you leave it?",
     a:"Leave most of them: they affect 10 to 20% of adult men and the majority cause neither symptoms nor infertility, so reassurance and scrotal support are enough. Intervene for pain or a dragging sensation not relieved by support; for testicular atrophy, particularly in an adolescent; and for infertility with abnormal semen parameters and a palpable varicocele. Not for a subclinical varicocele or one with normal semen parameters.", ref:"B&L 86 p.1563, p.1564"},
    {id:"vrc27", lv:2, type:"Treatment", q:"Embolisation or operation first?",
     a:"B&L: when the discomfort is significant, percutaneous embolisation of the gonadal veins is the usual first-line intervention; if that is not possible, or if the varicocele recurs, as it does in around 20% after embolisation, surgical ligation of the testicular veins is the appropriate treatment. Where interventional radiology with gonadal-vein experience is not available, which is the setting SRB writes for, the operation is the realistic first move.", ref:"B&L 86 p.1564 · SRB 26 p.1064"},
    {id:"vrc28", lv:2, type:"Treatment", q:"Name the operative approaches, from high to low.",
     a:"SRB gives five by anatomical level: Palomo's operation, suprainguinal extraperitoneal ligation of the testicular vein; the inguinal approach of Ivanissevich, which SRB calls easier and safer; the subinguinal approach of Marc Goldstein, at the superficial inguinal ring outside the external oblique aponeurosis without opening it; the scrotal approach, reserved for grade IV where the veins have to be excised; and the laparoscopic approach, which SRB marks as accepted but controversial.", ref:"SRB 26 p.1064"},
    {id:"vrc29", lv:2, type:"Complications", q:"What are the complications of varicocele repair?",
     a:"Recurrence, from missed collateral veins; hydrocele, from ligation of the lymphatics, which is the commonest complication of the non-microsurgical techniques; and testicular atrophy, from injury to the testicular artery. Preserving the artery and the lymphatics is exactly what the microsurgical technique is for.", ref:"B&L 86 p.1564"},
    {id:"vrc30", lv:2, type:"Treatment", q:"What is the recurrence rate after treatment?",
     a:"Two different figures for two different procedures: SRB gives 5 to 10% after surgery, and B&L gives around 20% after embolisation. They are not two estimates of one thing, so say which procedure you mean.", ref:"SRB 26 p.1064 · B&L 86 p.1564"},
    {id:"vrc31", lv:2, type:"Diagnosis", q:"Separate an epididymal cyst from a spermatocele.",
     a:"The epididymal cyst is congenital, lies behind the body of the testis, is multilocular with a bunch-of-grapes appearance, contains clear fluid, is brilliantly transilluminant, and excision should be avoided in the young. A spermatocele is an acquired retention cyst, lies behind and above the testis, is unilocular, looks like a third testis, contains barley-water fluid which holds spermatozoa, is transilluminant, and can be excised.", ref:"SRB 26 p.1063"},
    {id:"vrc32", lv:2, type:"Examination", q:"Does a varicocele transilluminate?",
     a:"Clinically no: it is a mass of blood-filled veins, so a torch does not light it up, and transillumination is what you use to separate a hydrocele or an epididymal cyst from it. Note what SRB prints, though, because an examiner may quote it: SRB describes a varicocele as soft, cystic and transilluminant. Treat that as SRB's wording rather than a sign to demonstrate, and rely on the bag of worms, the filling on standing, and the normal testis felt separately below.", ref:"SRB 26 p.1063 · B&L 86 p.1563"},

    {id:"vrc40", lv:3, type:"Classification", q:"How many grades of varicocele are there, and what does grade 3 mean?",
     a:"Say whose system you are using, because both books run to four and both use the number three for different patients. B&L grades by palpability: subclinical, shown only on Doppler; grade 1 palpable on Valsalva only; grade 2 palpable at rest but not visible; grade 3 visible and palpable at rest. SRB grades by size and tortuosity: I small, II moderate, III large, IV severely tortuous, and SRB's grade IV carries a consequence, being the one taken through a scrotal approach. So a B&L grade 3 is simply one you can see standing, which may be moderate in size, while an SRB grade III is a large one with a further grade above it. Name the system, and remember that neither grade decides treatment: the testicular volume and the semen analysis do.", ref:"B&L 86 p.1564 · SRB 26 p.1064"},
    {id:"vrc41", lv:3, type:"Management", q:"Does repairing a varicocele improve fertility?",
     a:"Semen parameters improve more reliably than pregnancy rates. B&L cites a 2012 Cochrane review which concluded there is some evidence that treating a varicocele in men from couples with otherwise unexplained subfertility may improve the couple's chance of spontaneous pregnancy, but that repair in men with a subclinical varicocele or normal semen parameters is considered ineffective for increasing that chance; it adds that treatment in adolescents poses a risk of overtreatment, since most boys with a varicocele will have no fertility problem later, and concedes that the exact association is unknown. SRB states the benefit flatly, that in 6 to 12 weeks oligospermia improves very well and so does the conception rate, and calls it correctable infertility, while conceding in its own note that it is a debate whether varicocele really causes subfertility. Both can be true at once because they answer different questions, one about live births and one about the sperm count.", ref:"B&L 86 p.1564 · SRB 26 p.1063, p.1064"},
    {id:"vrc42", lv:3, type:"Treatment", q:"Which operation has the best results?",
     a:"B&L is explicit: current evidence indicates that microsurgical varicocelectomy is the most effective method among the different surgical varicocelectomy techniques, with fewer complications and lower recurrence rates. The reason is that individual veins can be ligated while the testicular artery and the lymphatics are preserved, which is what prevents atrophy and hydrocele.", ref:"B&L 86 p.1564"},
    {id:"vrc43", lv:3, type:"Procedure", q:"What is Palomo's operation, and what is the risk at that level?",
     a:"Suprainguinal extraperitoneal ligation of the testicular vein. It is the highest approach, so only one or two veins need ligating, but the testicular artery lies alongside them at that level, which is the hazard.", ref:"SRB 26 p.1064"},
    {id:"vrc44", lv:3, type:"Procedure", q:"Describe the subinguinal approach.",
     a:"Marc Goldstein's approach: the cord is reached at the superficial inguinal ring, outside the external oblique aponeurosis, without opening the aponeurosis, through a small incision. It is the level at which microsurgical repair is done.", ref:"SRB 26 p.1064"},
    {id:"vrc45", lv:3, type:"Procedure", q:"When is a scrotal approach used?",
     a:"SRB reserves it for grade IV, the severely tortuous varicocele, because at that stage the veins have to be excised rather than simply ligated.", ref:"SRB 26 p.1064"},
    {id:"vrc46", lv:3, type:"Complications", q:"Why does a hydrocele follow varicocele surgery?",
     a:"Because the lymphatics running with the cord have been ligated along with the veins, so the tunica loses its lymphatic drainage. It is the commonest complication of the non-microsurgical techniques, and avoiding it is one of the reasons for operating under the microscope.", ref:"B&L 86 p.1564"},
    {id:"vrc47", lv:3, type:"Anatomy", q:"Trace the venous drainage from the scrotum upwards.",
     a:"The numerous veins of the pampiniform plexus in the scrotum join to form about four to eight veins in the inguinal canal, and above, on the posterior abdominal wall, these join to form a single testicular vein, which drains into the left renal vein on the left and directly into the inferior vena cava on the right. That coalescence is why a high ligation controls the varicocele with few vessels, and why missed collaterals cause recurrence.", ref:"SRB 26 p.1063 · B&L 86 p.1563"},
    {id:"vrc48", lv:3, type:"Diagnosis", q:"How would you separate funiculitis from a small strangulated hernia?",
     a:"By palpating just above the deep inguinal ring. In a strangulated hernia the abdominal contents can be felt entering the deep ring; in funiculitis no such structures are felt. The distinction is imperative because funiculitis is treated conservatively while a strangulated hernia needs immediate operation. Funiculitis presents with aching in the groin and variable fever, sometimes beginning as acute prostatitis, with a red, oedematous, shiny inguinal and inguinoscrotal region, and in India filariasis as well as gonococcal infection causes it.", ref:"Das 39 p.614"},
    {id:"vrc49", lv:3, type:"Diagnosis", q:"What else would a renal tumour occluding the left renal vein produce?",
     a:"S Das: occlusion of the left renal and testicular veins may give a varicocele of recent onset, with oedema of both legs if the inferior vena cava is occluded, and hypertension from increased renin production is sometimes the presenting feature. So a new varicocele is examined alongside the kidney, the legs and the blood pressure.", ref:"Das 37 p.581 · Das 39 p.613"},
    {id:"vrc50", lv:3, type:"Management", q:"A 14-year-old with a left varicocele and equal-sized testes. What do you advise?",
     a:"Reassurance and follow-up rather than operation. B&L warns that treatment of varicocele in adolescents poses a risk of overtreatment, because most boys with a varicocele will have no fertility problem later in life. What would change the decision is testicular atrophy on the affected side, pain not relieved by support, or later abnormal semen parameters, so measure both testes and keep measuring them.", ref:"B&L 86 p.1564, p.1563"},
  ],

  "sinus-and-fistula": [
    {id:"snf01", lv:1, type:"Pathology", q:"Define a sinus.",
     a:"SRB: a blind track lined by granulation tissue leading from an epithelial surface into the surrounding tissues. Add the cavity in the next breath, because it is what earns the follow-up mark: there is usually a cavity, often an abscess cavity, at the blind end, and inadequate drainage of that cavity is what keeps the sinus open. The operative word is blind: a sinus has one opening. Sinus is Latin for a hollow or a bay.", ref:"SRB 1 p.30 · Das 5 p.76 · B&L 45 p.663"},
    {id:"snf02", lv:1, type:"Pathology", q:"Define a fistula.",
     a:"SRB: an abnormal communication between the lumen of one viscus and another, or the body surface, or between vessels. S Das: a communicating track between two epithelial surfaces, commonly between a hollow viscus and the skin, an external fistula, or between two hollow viscera, an internal fistula; the track is lined with granulation tissue which is subsequently epithelialised. Two openings, or one opening and an internal communication. Fistula is Latin for a flute or pipe.", ref:"SRB 1 p.30 · Das 5 p.76 · B&L 45 p.663"},
    {id:"snf03", lv:1, type:"Pathology", q:"Why does a sinus persist?",
     a:"SRB's seven: a foreign body or necrotic tissue underneath, such as a suture or a sequestrum; insufficient or non-dependent drainage; persistent obstruction in the lumen, as with distal obstruction in a faecal or biliary fistula; lack of rest with persistent infection; a wall lined with epithelium or endothelium; dense fibrosis preventing contraction and healing; and specific infections, tuberculosis and actinomycosis. S Das adds the mechanism for the fibrosis: dense fibrosis around the track and the cavity prevents their collapse, as in chronic empyema. Every one of the seven is something you can act on, which is why they are also the answer to how you would treat it.", ref:"SRB 1 p.31 · Das 5 p.76"},
    {id:"snf04", lv:1, type:"Examination", q:"What does the discharge tell you?",
     a:"SRB's table, which is the most useful thing in this case. Purulent: bacterial infection. Gaseous: tuberculous. Sulphur granules: actinomycosis. Mucus: branchial fistula. Saliva: parotid fistula. Faeces: faecal fistula. Bile: biliary or duodenal fistula. Bony spicules: osteomyelitis. So the first question at the bedside is not where it goes but what comes out of it.", ref:"SRB 1 p.31 · Das 5 p.78"},
    {id:"snf05", lv:1, type:"Classification", q:"Classify the causes of a sinus.",
     a:"S Das: congenital, such as a preauricular sinus; traumatic, where a foreign body implanted in deep tissue becomes infected; and inflammatory, such as an osteomyelitic, tuberculous or actinomycotic sinus, or the sinus of a chronic abscess discharging pus after inadequate treatment of an acute abscess. B&L groups the acquired causes by mechanism, which is the better way to recite them: a retained foreign body such as an ingrown hair or suture material; chronic infection, that is tuberculosis, osteomyelitis or actinomycosis; chronic inflammation, that is Crohn's disease; malignancy; and inadequate surgical drainage of a cavity, which is the one candidates forget.", ref:"Das 5 p.79 · B&L 45 p.663 · SRB 1 p.30"},
    {id:"snf06", lv:1, type:"Classification", q:"Name the congenital and the acquired fistulae.",
     a:"Congenital: branchial fistula, tracheo-oesophageal fistula, congenital arteriovenous fistula, umbilical fistula. Acquired: fistula-in-ano, faecal and gastrointestinal fistula, parotid fistula, biliary fistula, acquired arteriovenous fistula.", ref:"SRB 1 p.30"},
    {id:"snf07", lv:1, type:"Examination", q:"What do you note about the opening?",
     a:"The number, the site, and whether the edge is everted, indurated or healthy. A single opening means a sinus; two or more raise a fistula. SRB's pilonidal sinus illustration shows primary and secondary openings, and S Das notes that a tuberculous sinus's opening is often wide with a thin, blue, undermined margin.", ref:"SRB 1 p.31 · Das 5 p.78"},
    {id:"snf08", lv:1, type:"Examination", q:"What do you palpate for?",
     a:"S Das's four: tenderness, since a sinus from an inflammatory source such as osteomyelitis is tender; thickening of the wall, because a chronic sinus has a thick wall from surrounding fibrosis; mobility over the deep structures, because a sinus from osteomyelitis is fixed to the bone, which is itself irregular, thickened and tender; and a lump in the neighbourhood, which often means tuberculous lymphadenitis.", ref:"Das 5 p.78"},
    {id:"snf09", lv:1, type:"Investigation", q:"What does a sinogram or fistulogram show?",
     a:"Radio-opaque fluid injected into the track delineates its course and so indicates the cause: the extent of the track, any cavity at its end, and any communication with a hollow viscus. SRB names the MR sinusogram as beneficial, for instance in a preauricular sinus.", ref:"Das 5 p.79 · SRB 1 p.33"},
    {id:"snf10", lv:1, type:"Examination", q:"What do you do before you examine this patient?",
     a:"Hand hygiene, introduce yourself and check the patient's name and date of birth, request a chaperone as appropriate, explain what you are going to do, obtain verbal consent, and make sure the patient is comfortable. Examine the tender part last.", ref:"B&L 35 p.472 · B&L 21 p.285"},
    {id:"snf11", lv:1, type:"Examination", q:"What must you not forget to examine?",
     a:"The draining lymph nodes. S Das is emphatic that this examination is always essential and should not be missed under any circumstances. Also the underlying structure, bone, joint, bowel or nodes, and the surrounding skin.", ref:"Das 5 p.78"},
    {id:"snf12", lv:1, type:"Diagnosis", q:"A sinus just in front of the lower third of sternomastoid, discharging mucus.",
     a:"A branchial fistula: S Das gives that as its typical site, and SRB's discharge rule is that mucus from a neck fistula means branchial. It represents a persistent second branchial cleft, and it needs complete excision of the tract to avoid recurrence.", ref:"Das 5 p.77 · SRB 1 p.31 · B&L 52 p.805"},

    {id:"snf20", lv:2, type:"Examination", q:"What does examination with a probe tell you, and what is the caution?",
     a:"Four things: the direction and depth of the sinus; the presence of a foreign body such as a sequestrum, which will be mobile at the depth of the wound; whether the fistula communicates with a hollow viscus; and whether fresh discharge comes out as the probe is withdrawn. S Das's caution is that it is important but must be performed with due precaution, so probe gently and only where it is safe.", ref:"Das 5 p.78"},
    {id:"snf21", lv:2, type:"Diagnosis", q:"Which lesions give multiple openings?",
     a:"S Das: most fistulae are single, but a few are notorious for multiplicity. Watering-can perineum; Crohn's disease of the rectum and anal canal, which produces multiple anal fistulae; actinomycosis, which always produces multiple sinuses; and sometimes ulcerative colitis.", ref:"Das 5 p.77"},
    {id:"snf22", lv:2, type:"History", q:"What in the past and family history matters here?",
     a:"S Das: a few diseases are prone to produce a sinus or fistula later in life, that is tuberculosis, Crohn's disease, ulcerative colitis and actinomycosis, and colloid carcinoma of the rectum may produce an anal fistula at a later stage; a sinus or fistula may also follow an earlier operation. In the family history, tuberculosis, Crohn's disease and ulcerative colitis run in families, and even fistula-in-ano is often seen in more than one member.", ref:"Das 5 p.77"},
    {id:"snf23", lv:2, type:"History", q:"What history goes with an osteomyelitic sinus, and with a tuberculous one?",
     a:"Osteomyelitis: high fever followed by swelling and pain in the bone, then an abscess which moves to the surface and bursts, leaving a discharging sinus, sometimes with a history of discharging bone chips; it persists as long as there is necrotic bone at the depth. Tuberculosis: a previous history of lymph node enlargement or of tuberculous bone or joint disease, then a cold abscess which bursts or is incised, leaving a sinus. For a perianal sinus or fistula, a previous perianal or ischiorectal abscess.", ref:"Das 5 p.76"},
    {id:"snf24", lv:2, type:"Examination", q:"What does the skin around the opening tell you?",
     a:"A scar nearby may indicate chronic osteomyelitis or a previously healed tuberculous sinus. Surrounding dermatitis and pigmentation are characteristic of Crohn's disease and of actinomycosis. Excoriation points to an irritant discharge, and SRB's practical measure for a postoperative gastrointestinal fistula is zinc oxide cream applied locally.", ref:"Das 5 p.78 · SRB 1 p.31"},
    {id:"snf25", lv:2, type:"Diagnosis", q:"A discharging sinus at the point of the chin.",
     a:"A median mental sinus. Infection of the root or roots of one or both lower incisors forms a root abscess which tracks down in the midline between the two halves of the lower jaw and presents as a usually painless discharging sinus at the point of the chin. SRB's warning is that it is often mistaken for an infected sebaceous cyst; the differential is that, a tuberculous sinus, and osteomyelitis, and osteomyelitis of the mandible is the possible complication.", ref:"SRB 1 p.32"},
    {id:"snf26", lv:2, type:"Investigation", q:"How do you prove a median mental sinus, and how do you cure it?",
     a:"A dental radiograph is diagnostic, and a plain radiograph of the mandible may not reveal the disease at all. Treatment is antibiotics after a discharge study, then laying open and excising the sinus track with extraction of the offending incisor tooth or teeth. You cannot cure it without removing the tooth, because the tooth is the foreign body: it is cause-of-persistence number one in action.", ref:"SRB 1 p.32"},
    {id:"snf27", lv:2, type:"Diagnosis", q:"A sinus in front of the ear since childhood.",
     a:"A preauricular sinus, congenital, occurring from imperfect fusion of the six tubercles which form the ear cartilage. The opening is at the root of the helix or on the tragus, and the track runs deep, backwards and slightly upwards towards the helix, usually ending blindly. If the outer opening closes, a swelling forms. The differential is a cold abscess or a sebaceous cyst.", ref:"SRB 1 p.33 · Das 5 p.77"},
    {id:"snf28", lv:2, type:"Treatment", q:"How is a preauricular sinus treated?",
     a:"Excision under general anaesthesia with removal of the entire track, because if the track is not removed properly recurrence will occur. Methylene blue is injected into the track first and the track excised through an elliptical incision. Investigate beforehand with a sinusogram, ideally MR, and a discharge study.", ref:"SRB 1 p.33"},
    {id:"snf29", lv:2, type:"Pathology", q:"What is a sequestrum, and how do the varieties differ?",
     a:"Dead bone in situ. SRB's appearances by cause: pyogenic; tubercular, which is feathery; Salmonella, which is granular; and syphilitic. It is the commonest foreign body keeping a sinus open, and it is treated by sequestrectomy and saucerisation.", ref:"SRB 1 p.32, p.33"},
    {id:"snf30", lv:2, type:"Investigation", q:"What would you send the discharge for?",
     a:"S Das: examine it macroscopically, physically, chemically, microscopically, for instance for sulphur granules in actinomycosis, and bacteriologically. SRB's routine is culture and sensitivity, cytology, and acid-fast bacilli, which in India is the set to name.", ref:"Das 5 p.79 · SRB 1 p.32"},
    {id:"snf31", lv:2, type:"Examination", q:"There is exuberant granulation tissue at the opening. What does that suggest?",
     a:"Proud flesh, granulation sprouting out of the sinus opening, which SRB says is commonly associated with a retained foreign body, so look for one. It should be scooped out with a Volkmann's scoop before any grafting.", ref:"SRB 1 p.19"},
    {id:"snf32", lv:2, type:"Treatment", q:"How would you treat a sinus, in principle?",
     a:"B&L reduces it to a sentence: treatment of a sinus is directed at removing the underlying cause, and management of a fistula is directed at the underlying aetiology. In full: remove the cause of persistence, then excise the track. Take out the foreign body or sequestrum; relieve the distal obstruction; provide dependent drainage; rest the part; treat the specific infection; and excise the epithelialised or densely fibrosed track. Excise the whole track or it recurs.", ref:"B&L 45 p.663 · SRB 1 p.31, p.33"},

    {id:"snf40", lv:3, type:"Pathology", q:"Which is lined by granulation tissue, the sinus or the cavity, and does it matter?",
     a:"The books word it differently. S Das and SRB put the lining in the sinus and run the track inwards from the surface: a blind track lined by granulation tissue leading from an epithelial surface into the surrounding tissues. B&L puts the lining in the cavity and runs the track outwards: a blind-ending tract connecting a cavity lined with granulation tissue, often an abscess cavity, to an epithelial surface. For naming the lesion it makes no difference, because it is the same thing described from either end. It matters for why a sinus persists: B&L's wording points at the cavity as the engine, and it lists inadequate surgical drainage of a cavity among the causes, while the Indian books' wording points at the track and its epithelialisation as what must be excised. Both are true, and the complete answer uses both: drain the cavity and excise the track.", ref:"Das 5 p.76 · SRB 1 p.30 · B&L 45 p.663"},
    {id:"snf41", lv:3, type:"Pathology", q:"Is an arteriovenous fistula a fistula?",
     a:"By SRB's definition yes, by B&L's strict wording no. B&L defines a fistula as an abnormal communication between two epithelium-lined surfaces and then lists arteriovenous among the acquired fistulae four lines later; a blood vessel is lined by endothelium, not epithelium, so the example fails the definition. SRB writes it so that vessels are included from the start, an abnormal communication between the lumen of one viscus and another, or the body surface, or between the vessels. Use SRB's wording. If you have already said two epithelium-lined surfaces and the examiner asks about an arteriovenous fistula, do not retreat: say that vessels are endothelium-lined, so the strict epithelial definition takes the arteriovenous fistula as a recognised exception, which is why SRB words it to include vessels.", ref:"B&L 45 p.663 · SRB 1 p.30"},
    {id:"snf42", lv:3, type:"Investigation", q:"Would you biopsy the track?",
     a:"Always. B&L states it as a rule: biopsies should always be taken from the wall of a sinus to exclude malignancy or specific infection. The reason is that a long-standing sinus can harbour a squamous carcinoma in its wall and no imaging will tell you. SRB's approach in a chronic sinus with a cold abscess is the same: send material for histology, then antibiotics, antitubercular drugs, rest and adequate drainage.", ref:"B&L 45 p.663 · SRB 1 p.32"},
    {id:"snf43", lv:3, type:"Investigation", q:"Name the dye and marker tests for a fistula.",
     a:"S Das's three: sterilised methylene blue pushed through a catheter into the urinary bladder, which confirms a vesicovaginal fistula if the colour appears in the vagina; charcoal powder in the food, which confirms an upper gastrointestinal fistula if charcoal particles appear in the discharge a few hours later; and a coloured drug such as pyridium, excreted in the urine, to confirm a urinary fistula.", ref:"Das 5 p.79"},
    {id:"snf44", lv:3, type:"Pathology", q:"Why does a true fistula rarely close on its own, and what is the one thing that makes them heal?",
     a:"S Das: once a true fistula has formed it seldom shows any intention towards healing, and irritant discharge such as urine, faeces or bile passing through it prevents healing. Then his own answer, which is the sentence worth quoting: if the natural passage is made patent, all abnormal offshoots heal spontaneously. So relieve the distal obstruction and the fistula closes itself.", ref:"Das 5 p.76"},
    {id:"snf45", lv:3, type:"Diagnosis", q:"A sinus in the thigh with bony spicules in the discharge.",
     a:"Chronic osteomyelitis with a sequestrum; SRB's illustration is a sinus in the thigh from osteomyelitis of the greater trochanter. The sinus is tender, fixed to the irregular thickened bone, and the history is of high fever followed by swelling and pain in that bone. Radiograph the bone for the sequestrum and for an opaque foreign body, remove the sequestrum, and saucerise.", ref:"SRB 1 p.30 · Das 5 p.76, p.78, p.79"},
    {id:"snf46", lv:3, type:"Diagnosis", q:"A chronic sinus in the neck. What are you thinking, and what else could it be?",
     a:"Tuberculous lymphadenitis with a cold abscess underneath, which is what SRB illustrates. Send the discharge for culture, cytology and acid-fast bacilli, take material for histology, and treat with antitubercular drugs, antibiotics, rest and adequate drainage. The differential by discharge: a branchial fistula discharges mucus, actinomycosis discharges sulphur granules and produces multiple sinuses, and osteomyelitis of the mandible gives a single sinus a little below the jaw.", ref:"SRB 1 p.31, p.32 · Das 5 p.77, p.78"},
    {id:"snf47", lv:3, type:"Pathology", q:"What is a pilonidal sinus associated with?",
     a:"It has primary and secondary openings, and SRB lists it alongside acne and Crohn's disease in association with hidradenitis suppurativa, for which smoking is the important aetiological factor, with obesity, poor hygiene, polycystic ovarian disease, diabetes mellitus and steroid therapy as other associations, and a genetic association at chromosome 15q24q25.", ref:"SRB 1 p.31, p.44"},
    {id:"snf48", lv:3, type:"Treatment", q:"A faecal fistula on the abdominal wall. What decides whether it closes?",
     a:"The causes of persistence, taken one at a time: distal obstruction in the lumen, which must be relieved; inadequate or non-dependent drainage; a foreign body such as suture material; epithelialisation of the track; dense fibrosis; and specific infection, including tuberculosis and Crohn's disease. Protect the skin with zinc oxide cream, attend to nutrition, and remember S Das's rule that once the natural passage is patent the abnormal offshoots heal on their own.", ref:"SRB 1 p.31 · Das 5 p.76"},
  ],

  "undescended-testis": [
    {id:"udt01", lv:1, type:"Pathology", q:"Define undescended and ectopic testis.",
     a:"Incomplete descent of the testis, also called cryptorchidism, occurs when one or both testes are arrested at some point in the normal path to the scrotum. An ectopic testis is one abnormally placed outside that path. Undescended is on the path but short of the scrotum; ectopic is off the path.", ref:"B&L 86 p.1558"},
    {id:"udt02", lv:1, type:"Pathology", q:"The testis cannot be made to touch the bottom of the scrotum. What do you call that, and what are the possibilities?",
     a:"A maldescended testis, which is SRB's umbrella term and the cleanest definition in the three books. The possibilities under it are an undescended testis, cryptorchidism, which SRB reserves for bilateral undescended testis and which literally means hidden testis, an ectopic testis, and anorchism, complete agenesis, which is distinguished from the others by an HCG test. A vanishing testis is one that develops but disappears before birth, probably from prenatal torsion.", ref:"SRB 26 p.1065, p.1066"},
    {id:"udt03", lv:1, type:"Anatomy", q:"Where does an undescended testis lie, and where does an ectopic one go?",
     a:"Undescended, SRB's three positions: in the abdomen just above the internal ring, extraperitoneally; in the inguinal canal; or in the superficial inguinal pouch. Ectopic, B&L: the commonest site is the superficial inguinal pouch, just inferior and medial to the superficial inguinal ring, and the others are femoral, perineal, at the root of the penis, and crossed to the opposite scrotum.", ref:"SRB 26 p.1066 · B&L 86 p.1559"},
    {id:"udt04", lv:1, type:"Pathology", q:"Give the incidence of undescended testis.",
     a:"B&L: about 3% of full-term and 30% of premature male infants are born with one or both testes undescended; about two-thirds reach the scrotum during the first three months of life, but full descent after that is uncommon; and the incidence at one year is around 1%. SRB's figures differ slightly: 30% in premature infants, 4% at full term, and 2% in later childhood, with the right testis alone involved in 50%, the left alone in 30% and both in 20%.", ref:"B&L 86 p.1558 · SRB 26 p.1066"},
    {id:"udt05", lv:1, type:"Examination", q:"How do you examine a boy with a suspected undescended testis?",
     a:"B&L: it is helpful to have the boy as relaxed as possible in a warm room, usually in a supine position. The reason is in the next sentence of the same passage: the cremasteric reflex is active in childhood, so any stimulation of the skin of the scrotum or thigh makes the testis ascend into the inguinal canal. A cold room and a nervous child manufacture the diagnosis. Then sweep along the line of the canal towards the scrotum with a flat warm hand and hold the testis there with the other, and record whether it reaches the bottom of the scrotum, which is SRB's criterion. The sweeping technique itself is standard clinical practice rather than a described method in these three books.", ref:"B&L 86 p.1559 · SRB 26 p.1065"},
    {id:"udt06", lv:1, type:"Examination", q:"How do you distinguish a retractile from an undescended testis?",
     a:"A retractile testis can be coaxed into the scrotum and will stay there, at least briefly; a truly undescended testis cannot be brought to the bottom of the scrotum. Then look at the scrotum: it is underdeveloped in true undescent, but relatively well developed in a retractile testis, because a retractile testis has lived in it.", ref:"SRB 26 p.1065 · B&L 86 p.1559"},
    {id:"udt07", lv:1, type:"Physiology", q:"Why does a child's testis retract at all?",
     a:"Because during childhood the testes are mobile and the cremasteric reflex is active, so in some boys any stimulation of the skin of the scrotum or the thigh causes the testis to ascend and temporarily disappear into the inguinal canal.", ref:"B&L 86 p.1559"},
    {id:"udt08", lv:1, type:"Complications", q:"What are the consequences of an undescended testis?",
     a:"Four: infertility, malignancy, hernia and torsion. Around 90% of boys with an undescended testis have a patent processus vaginalis, though a clinically apparent hernia is much less common, and the undescended testis is more prone to torsion because of a developmental abnormality between the testis and its mesentery. SRB's list adds trauma and epididymo-orchitis.", ref:"B&L 86 p.1559 · SRB 26 p.1067"},
    {id:"udt09", lv:1, type:"Examination", q:"What do you do before you examine this boy?",
     a:"Hand hygiene, introduce yourself, check the name and date of birth, explain what you are going to do and obtain consent, and make him comfortable. This examination is intimate, so offer a chaperone, which B&L says should be part of a local guideline or policy; explain it to the child and ask the parent. If consent is refused, explain again, offer a chaperone, document the refusal and do not proceed.", ref:"B&L 21 p.285 · B&L 35 p.472"},
    {id:"udt10", lv:1, type:"Treatment", q:"What is the treatment, and at what age?",
     a:"Surgery, always. SRB: between two and four years of age. B&L: orchidopexy is usually performed between 6 and 18 months, using corrected age in premature babies. Give SRB's window to an Indian examiner and add B&L's in a sentence.", ref:"SRB 26 p.1067 · B&L 86 p.1560"},
    {id:"udt11", lv:1, type:"Treatment", q:"What are the principles of orchidopexy?",
     a:"SRB's three: mobilisation of the cord, repair of the associated hernia, and adequate scrotal fixation without tension. In practice: open the inguinal canal, do the herniotomy since the patent processus is present in about 90%, mobilise the cord, create a scrotal pouch by finger dissection, and fix the testis in a subdartos pouch with interrupted non-absorbable sutures.", ref:"SRB 26 p.1067 · B&L 86 p.1559, p.1560"},

    {id:"udt20", lv:2, type:"Management", q:"You decide it is a retractile testis. Do you discharge him?",
     a:"No. B&L: for retractile testes a yearly physical examination is recommended, because of the 2 to 50% reported risk of a retractile testis becoming an acquired undescended testis, and its paediatric chapter says follow-up is needed because some permanently ascend and require an orchidopexy. So the answer is retractile, and I would review him yearly, not retractile, so discharge.", ref:"B&L 86 p.1559 · B&L 17 p.257"},
    {id:"udt21", lv:2, type:"Management", q:"At what age do you stop waiting for a testis to descend?",
     a:"Three months. Two-thirds of undescended testes reach the scrotum in the first three months but full descent after that is uncommon, and B&L's paediatric chapter turns that into a plan: examine at birth and at 6 weeks, and if an undescended testis is found, see the boy at 3 months, since a testis is unlikely to descend after that time. Three months settles the diagnosis; it is not the age of operation.", ref:"B&L 86 p.1558 · B&L 17 p.257"},
    {id:"udt22", lv:2, type:"Pathology", q:"What happens to fertility?",
     a:"It is reduced, even after orchidopexy. The infertility rate in unilateral cases is not believed to be very different from the general population. The fertility reduction after orchidopexy for bilateral cryptorchidism is about 38%. Patients with bilateral undescended testes who are operated as adults are almost always infertile and azoospermic, though pregnancies have been reported through sperm retrieval and assisted reproduction.", ref:"B&L 86 p.1559"},
    {id:"udt23", lv:2, type:"Investigation", q:"How would you investigate an impalpable testis?",
     a:"SRB: ultrasound of the abdomen, with the warning that an intra-abdominal testis is difficult to detect on ultrasound; assessment of FSH and HCG, and a high FSH in a young boy means bilateral anorchia; CT; a gonadal venogram; and laparoscopy, which is useful and therapeutic as well. B&L: for non-palpable testes under anaesthesia, diagnostic laparoscopy is recommended. A blind-ending vas at laparoscopy is the vanishing testis, meaning the testis is completely atrophied.", ref:"SRB 26 p.1067 · B&L 86 p.1560"},
    {id:"udt24", lv:2, type:"Treatment", q:"The testis is found inside the abdomen at laparoscopy. What are the options?",
     a:"Laparoscopic orchidopexy preserving the vessels, in which the testis is dissected off a triangular pedicle containing the testicular vessels and the vas; or a laparoscopic one-stage Fowler-Stephens orchidopexy, dividing the testicular vessels and relying on the collateral supply through the vasal and cremasteric vessels. In the two-stage version the vessels are clipped first and the testis brought down at a second operation six months later, so the collateral supply develops fully; bringing it down sooner risks atrophy.", ref:"B&L 86 p.1560"},
    {id:"udt25", lv:2, type:"Procedure", q:"The cord will not reach the scrotum. What do you do?",
     a:"SRB's sequence: ligate the inferior epigastric vessels to lengthen the cord; if more length is needed, mobilise the vas and testicular vessels retroperitoneally; and if more still is needed, apply a soft clamp to the testicular artery and check the viability of the testis, because if it stays viable it is also supplied by the artery of the vas and the cremasteric vessels, so the testicular artery can be ligated safely, which is the Stephen-Fowler technique.", ref:"SRB 26 p.1067"},
    {id:"udt26", lv:2, type:"Treatment", q:"When would you remove the testis rather than bring it down?",
     a:"B&L: orchidectomy if the incompletely descended testis is atrophic or there is suspicion of malignancy, particularly in a postpubertal boy with a normal contralateral testis. SRB adds atrophy, torsion, and inability to bring down an abdominal testis, and insists on consent, because even a non-functioning testis is highly prone to malignant transformation. The logic is that such a testis adds nothing to fertility and carries five to six times the normal cancer risk.", ref:"B&L 86 p.1560 · SRB 26 p.1067"},
    {id:"udt27", lv:2, type:"Treatment", q:"Is there any place for hormone therapy?",
     a:"Not much, in SRB's words. The only indications it gives are cryptorchidism associated with hypogenitalism and obesity, and a doubtful retractile testis, and it should be given at or after the age of eight. HCG is the agent.", ref:"SRB 26 p.1067"},
    {id:"udt28", lv:2, type:"Diagnosis", q:"A swelling in the groin and no testis in the scrotum.",
     a:"S Das: ordinarily a swelling in the inguinal region with absence of the testis from the scrotum is an undescended testis, and the patient will say the swelling was in that position from the beginning. Remember that it can descend the canal and emerge through the external opening without being a hernia, and that an undescended testis with an associated hernia gives a cough impulse. If the skin over it is red and oedematous, think of funiculitis or a late torsion.", ref:"Das 39 p.611, p.612 · Das 38 p.599"},
    {id:"udt29", lv:2, type:"Complications", q:"An undescended testis becomes acutely painful. What is it?",
     a:"Torsion until proved otherwise, because the undescended testis is more prone to torsion as a consequence of a developmental abnormality between the testis and its mesentery. An impalpable testis with groin pain is therefore a surgical emergency, and torsion heads SRB's list of complications.", ref:"B&L 86 p.1559 · SRB 26 p.1067"},
    {id:"udt30", lv:2, type:"Diagnosis", q:"What else would you look for in a boy with bilateral impalpable testes?",
     a:"A disorder of sex development, and the associations SRB lists: Klinefelter's syndrome, hypogonadotrophic hypogonadism, Prune-Belly syndrome, renal agenesis, bladder exstrophy, gastroschisis, horseshoe kidney and anorectal malformations. Check the karyotype and the endocrine axis, and use an HCG test to distinguish undescended testes from anorchism, with a high FSH suggesting bilateral anorchia. The first step is assessment, not an operation.", ref:"SRB 26 p.1065, p.1067"},
    {id:"udt31", lv:2, type:"Anatomy", q:"How does the testis normally descend?",
     a:"The primitive testis develops from the genital fold, attached to the posterior abdominal wall by the mesorchium, lying below the developing kidneys; the Wolffian duct becomes the epididymis and vas, and a fold of peritoneum at their junction, traceable to the developing scrotum, is the gubernaculum, whose muscular fibres, with hormonal factors, assist descent. The testis reaches the deep inguinal ring in the ninth month of gestation and descends into the scrotum just before or after delivery. Increased intra-abdominal pressure and differential growth of the abdominal wall are the mechanical factors; Müllerian inhibiting substance from fetal Sertoli cells, androgens and HCG are the hormonal ones. SRB's summary is that normally the kidney ascends and the testis descends.", ref:"SRB 26 p.1066"},
    {id:"udt32", lv:2, type:"Pathology", q:"Why does the testis fail to descend?",
     a:"SRB's causes: gubernacular dysfunction; lack of gonadotrophin; lack of calcitonin gene related peptide produced by the genitofemoral nerve, which is responsible for testicular descent; Prune-Belly syndrome, through a weak abdominal wall; familial factors; retroperitoneal adhesions; a short vas deferens or short testicular vessels; and an altered hypothalamo-pituitary-gonadal axis with androgen deficiency or deficiency of Müllerian inhibiting substance.", ref:"SRB 26 p.1066"},

    {id:"udt40", lv:3, type:"Pathology", q:"Does orchidopexy reduce the risk of testicular cancer?",
     a:"Apparently not, and both books say so, which contradicts what is commonly taught. SRB: orchidopexy may not alter the chances or risk of developing carcinoma of the testis, but it makes observation and evaluation by ultrasound easier, so changes are detected early. B&L gives the figures: the risk of testicular cancer if orchidopexy is done before puberty is around two to three times that of the general population, five to six times higher if done after puberty, and the risk does not seem to be different when orchidopexy is done early in infancy compared with later in childhood. So operating before puberty matters, the year within childhood does not, and what early surgery buys is fertility and a testis you can examine. A candidate who says we operate early to prevent cancer is giving the answer both books have abandoned.", ref:"SRB 26 p.1067 · B&L 86 p.1559"},
    {id:"udt41", lv:3, type:"Pathology", q:"Which tumour arises in an undescended testis, and at what age?",
     a:"In untreated undescended testes the commonest type is seminoma, with a peak age range of 15 to 45 years; after orchidopexy, seminomas represent only 30% of testicular tumours in previously undescended testes. It is treatable if caught early, so boys who had an orchidopexy as infants should be taught testicular self-examination.", ref:"B&L 86 p.1559"},
    {id:"udt42", lv:3, type:"Management", q:"The books give different ages for orchidopexy. Which do you give, and why do they differ?",
     a:"Three answers exist. B&L's testis chapter says 6 to 18 months; its own paediatric chapter says 6 to 12 months; SRB says two to four years, which begins after B&L's window has closed. The reason behind the earlier window is in B&L: the recommendation for early surgery is due to degeneration of spermatogenic tissue and reduced spermatogonia counts after the second year of life. SRB's pathology explains its own later window: up to the age of six microscopic changes are uncommon, and after that the testis gradually atrophies with irreversible destructive changes of the germinal epithelium. So the disagreement is about when the damage starts, not about whether to operate. Give SRB's two to four years to an Indian examiner, add B&L's 6 to 18 months with its reason, and say that current practice follows the earlier window.", ref:"B&L 86 p.1560, p.1559 · B&L 17 p.257 · SRB 26 p.1067, p.1066"},
    {id:"udt43", lv:3, type:"Pathology", q:"What happens histologically to an undescended testis?",
     a:"SRB: up to the age of six microscopic changes are uncommon; after that the testis gradually atrophies and reduces both its external and internal secretory activity, and eventually there are grossly immature epithelial elements with irreversible destructive changes of the germinal epithelium. B&L's version is positional as well as temporal: the higher the testis, the greater the degree of histological change, with degeneration of spermatogenic tissue and reduced spermatogonia counts after the second year of life.", ref:"SRB 26 p.1066 · B&L 86 p.1559"},
    {id:"udt44", lv:3, type:"Procedure", q:"What is Ombredanne's operation?",
     a:"In bilateral cases, passing the testis into the opposite side of the scrotum through an opening made in the scrotal septum, so that each testis sits in a pouch without tension.", ref:"SRB 26 p.1067"},
    {id:"udt45", lv:3, type:"Investigation", q:"At laparoscopy you find a blind-ending vas deferens. What does that mean?",
     a:"A vanishing testis: the testis is completely atrophied, having developed and then disappeared before birth, probably from prenatal torsion. Nothing further needs to be brought down on that side.", ref:"SRB 26 p.1067, p.1065"},
    {id:"udt46", lv:3, type:"Management", q:"A 25-year-old man has an undescended testis in the groin and a normal testis on the other side. What do you advise?",
     a:"Orchidectomy rather than orchidopexy, with consent. After puberty the cancer risk is five to six times that of the general population, the testis contributes nothing to fertility since bilateral cases operated as adults are almost always azoospermic and a unilateral case has near-normal fertility from the other side, and B&L names suspicion of malignancy or atrophy in the postpubertal boy with a normal contralateral testis as the indication for removal. SRB adds that even a non-functioning testis is highly prone to malignant transformation.", ref:"B&L 86 p.1559, p.1560 · SRB 26 p.1067"},
    {id:"udt47", lv:3, type:"Complications", q:"Why is the hernia repaired at the same operation?",
     a:"Because around 90% of boys with an undescended testis have a patent processus vaginalis, even though a clinically apparent hernia is much less common, and SRB makes repair of the associated hernia one of the three principles of the operation, doing the herniotomy as a routine part of mobilising the cord.", ref:"B&L 86 p.1559 · SRB 26 p.1067"},
    {id:"udt48", lv:3, type:"Management", q:"What do you tell the parents after a successful orchidopexy?",
     a:"That the testis is now where it can be examined, and that he should be taught testicular self-examination when he is old enough, because the operation does not abolish the cancer risk: it is treatable if caught early. That the fertility outlook is good for a unilateral case and reduced by about 38% after bilateral orchidopexy. And that the testis should be checked to confirm it has stayed in the scrotum.", ref:"B&L 86 p.1559 · SRB 26 p.1067"},
  ],

  "hydrocele": [
    {id:"hyd01", lv:1, type:"Pathology", q:"Define a hydrocele.",
     a:"B&L: an abnormal collection of serous fluid in a part of the processus vaginalis, usually the tunica vaginalis around the testis and occasionally along the spermatic cord. SRB puts it more simply as a collection of fluid between the two layers of the tunica.", ref:"B&L 86 p.1564 · SRB 26 p.1057"},
    {id:"hyd02", lv:1, type:"Classification", q:"Give the types of hydrocele.",
     a:"SRB's four anatomical types, which is the Indian exam answer: vaginal, around the testis and the commonest; infantile, where the tunica and processus are distended up to the internal ring but the sac has no connection with the peritoneal cavity; congenital, which communicates with the peritoneal cavity through a patent processus at the internal ring; and encysted hydrocele of the cord. B&L's structural three are communicating or congenital, non-communicating or vaginal, and the cord variety. Then the clinical division that decides management: primary or idiopathic, against secondary to epididymal or testicular disease.", ref:"SRB 26 p.1057 · B&L 86 p.1564"},
    {id:"hyd03", lv:1, type:"Examination", q:"Give the three signs that make the diagnosis.",
     a:"You can get above it, feeling only cord structures and nothing else at the root of the scrotum, unlike a hernia. It transilluminates brilliantly. And in a vaginal hydrocele you cannot feel the testis separately, because the fluid surrounds it, though testicular sensation can be elicited by transmitting pressure through the fluid. It is also fluctuant, with no cough impulse and no reducibility.", ref:"SRB 26 p.1058 · Das 38 p.597, p.598"},
    {id:"hyd04", lv:1, type:"Examination", q:"How do you distinguish a hydrocele from an inguinoscrotal hernia?",
     a:"You can get above a hydrocele, feeling only normal cord above it, because it is a purely scrotal swelling; you cannot get above an inguinoscrotal hernia, which is continuous with the inguinal canal and has no upper limit. The hydrocele also transilluminates, has no cough impulse, and is not reducible.", ref:"Das 38 p.597, p.598 · SRB 26 p.1058"},
    {id:"hyd05", lv:1, type:"Examination", q:"Which swellings are brilliantly transilluminant?",
     a:"SRB's list: vaginal hydrocele, epididymal cyst, cystic hygroma, ranula and meningocele.", ref:"SRB 26 p.1058"},
    {id:"hyd06", lv:1, type:"Pathology", q:"Describe the hydrocele fluid.",
     a:"Amber-coloured, with a specific gravity of 1.022 to 1.024, containing water, salts, albumin and fibrinogen, and often cholesterol and tyrosine crystals. The sentence to memorise: per se hydrocele fluid does not clot, but if it comes in contact with blood the fibrinogen is activated and it clots firmly. That is why a traumatic or repeated aspiration leaves a thickened, loculated sac that is harder to operate on later.", ref:"SRB 26 p.1057"},
    {id:"hyd07", lv:1, type:"Pathology", q:"How does a primary hydrocele form?",
     a:"SRB's four mechanisms: defective absorption of fluid by the tunica vaginalis, probably from damage to the endothelial wall by low-grade infection; excessive production, as in a secondary hydrocele; interference with the drainage of fluid; and a patent processus vaginalis.", ref:"SRB 26 p.1057"},
    {id:"hyd08", lv:1, type:"Examination", q:"What is the single most important thing to establish in an adult hydrocele?",
     a:"Whether the testis underneath it is normal, because an acquired hydrocele is either primary and idiopathic or secondary to epididymal or testicular disease. In a tense hydrocele you cannot palpate the testis, which is exactly why every adult hydrocele needs an ultrasound of the testis.", ref:"B&L 86 p.1564, p.1565"},
    {id:"hyd09", lv:1, type:"Diagnosis", q:"Hydrocele or epididymal cyst?",
     a:"In a vaginal hydrocele the fluid surrounds the testis, so the testis cannot be felt separately. In an epididymal cyst the testis is palpable separately, below and in front of the cyst. Both transilluminate, both are fluctuant, and you can get above both. SRB's scrotal differentials are haematocele, pyocele, cyst of the epididymis, spermatocele, varicocele, and primary and secondary vaginal hydrocele.", ref:"SRB 26 p.1056, p.1058"},
    {id:"hyd10", lv:1, type:"Pathology", q:"Why do most congenital hydroceles need no operation?",
     a:"Because more than 80% of newborn boys have a patent processus vaginalis and most close spontaneously, closure beginning in late gestation and continuing through infancy and childhood. So observe in infancy, and operate if it persists beyond about two years or if there is an associated hernia, through the groin with ligation of the patent processus.", ref:"B&L 86 p.1564"},
    {id:"hyd11", lv:1, type:"Examination", q:"What do you do before you examine this patient's scrotum?",
     a:"Hand hygiene, introduce yourself and check the name and date of birth, explain what you are going to do and why, obtain verbal consent, and make the patient comfortable. The examination is intimate, so offer a chaperone, which B&L says should be especially for intimate examinations and part of a local guideline or policy; say you have offered and that you would record it. If consent is refused, explain again, offer a chaperone, document the refusal and do not proceed.", ref:"B&L 21 p.285 · B&L 35 p.472"},
    {id:"hyd12", lv:1, type:"Investigation", q:"What would you do if the swelling does not transilluminate?",
     a:"Reconsider the diagnosis and get an ultrasound. SRB lists the reasons transillumination fails: a long-standing hydrocele, a thick sac, thick dartos, thick skin, infected fluid, or a chylocele. The other possibilities are blood, a haematocele, pus, a pyocele, and a solid swelling such as a tumour.", ref:"SRB 26 p.1058"},

    {id:"hyd20", lv:2, type:"Diagnosis", q:"Primary or secondary? Separate them at the bedside.",
     a:"Primary: large, often tense, long history, no pain, and the testis impalpable within it. Secondary: usually small and lax, so the testis is palpable and the underlying disease can be felt, often with pain or a history of fever, trauma or weight loss. The rule of thumb is counter-intuitive and therefore examinable: a big tense hydrocele is usually primary, and a small lax one is the one hiding a tumour. SRB adds the exception that matters in India: the secondary hydrocele of filariasis can be very large.", ref:"SRB 26 p.1059 · B&L 86 p.1564"},
    {id:"hyd21", lv:2, type:"Investigation", q:"Why must every adult hydrocele have an ultrasound?",
     a:"Because the ultrasound is examining the testis, not the fluid. A hydrocele may be secondary to epididymal or testicular disease, a testicular tumour can present as a hydrocele, and in a tense hydrocele the testis cannot be palpated. If the testis is abnormal, send alpha-fetoprotein, beta-HCG and lactate dehydrogenase before any intervention.", ref:"B&L 86 p.1564, p.1565"},
    {id:"hyd22", lv:2, type:"Pathology", q:"What causes a secondary hydrocele?",
     a:"Epididymal or testicular disease. SRB's causes by heading: infection, that is filariasis, tuberculosis of the epididymis, where 30% of cases have a secondary hydrocele, and syphilis; injury, that is trauma and post-herniorrhaphy hydrocele; and tumour. In India filariasis comes first: B&L says filarial hydroceles and chyloceles account for up to 80% of hydroceles in tropical countries where Wuchereria bancrofti is endemic, following repeated attacks of filarial epididymo-orchitis.", ref:"SRB 26 p.1059 · B&L 86 p.1566, p.1564"},
    {id:"hyd23", lv:2, type:"Treatment", q:"What are the operations for an adult hydrocele, and what decides between them?",
     a:"B&L gives three main surgical techniques. Plication, Lord's operation, suitable when the sac is reasonably thin walled: the sac is neither excised nor everted but bunched up with a series of sutures, so there is minimal dissection and less risk of haematoma. Eversion: the sac is opened and everted behind the testis, with the testis placed in a pouch prepared in the fascial planes of the scrotum, used for a thicker sac because a thick sac will not bunch. And aspiration. SRB adds subtotal excision of the sac for a thick sac, a large hydrocele or a chylocele. The thickness of the sac is what decides: thin sac, plicate; thick sac, evert or partly excise.", ref:"B&L 86 p.1565, p.1566 · SRB 26 p.1059, p.1060"},
    {id:"hyd24", lv:2, type:"Procedure", q:"Why is excision of the sac only ever subtotal?",
     a:"SRB's reason, which is the sentence to remember: as the tunica vaginalis is reflected onto the cord structures and the epididymis posteriorly, total excision leads to orchidectomy with division of the cord. That anatomy is why a surgeon never tries to take the sac out whole.", ref:"SRB 26 p.1060"},
    {id:"hyd25", lv:2, type:"Treatment", q:"Would you aspirate this hydrocele?",
     a:"Not as definitive treatment. SRB: aspiration must be avoided as much as possible, as it is only a temporary measure with very early recurrence and higher chances of haematocele and infection. B&L agrees on the facts, that the fluid always reaccumulates within a week or so and that aspiration can cause bleeding into the sac and a haematocele, but allows it for men unfit for scrotal surgery, while undercutting its own indication by noting that hydrocele surgery can be done under local anaesthetic. And the prohibition that outranks both: if a tumour is suspected the hydrocele should not be punctured, because of the risk of malignant needle-track implantation.", ref:"SRB 26 p.1060 · B&L 86 p.1566, p.1564"},
    {id:"hyd26", lv:2, type:"Complications", q:"What are the complications of a hydrocele itself?",
     a:"SRB's list: infection, pyocele, haematocele, infertility, hernia of the hydrocele sac, which is rare, and atrophy of the testis.", ref:"SRB 26 p.1059"},
    {id:"hyd27", lv:2, type:"Diagnosis", q:"A cystic inguinoscrotal swelling that becomes less mobile when you pull the testis down.",
     a:"An encysted hydrocele of the cord: fluid in a portion of the patent funicular process of the tunica vaginalis, closed above and below, lying in the inguinal, inguinoscrotal or scrotal part of the cord, fluctuant and transilluminant. The sign is the traction test, the swelling becoming less mobile on gentle traction on the testis. The differential is an epididymal cyst, an inguinal hernia, a lipoma of the cord and a varicocele, and treatment is excision under local anaesthesia.", ref:"SRB 26 p.1058 · Das 39 p.613"},
    {id:"hyd28", lv:2, type:"Diagnosis", q:"A scrotal swelling that empties slowly on lying down and refills on standing, in a child.",
     a:"A congenital hydrocele, where the processus vaginalis communicates with the peritoneal cavity. SRB's details: the communicating orifice is too small for bowel to descend, so a hernia usually does not develop, and the hydrocele cannot be emptied by digital pressure because of the inverted ink bottle effect. Ascites and tuberculous peritonitis are aetiologies of the same picture.", ref:"SRB 26 p.1058"},
    {id:"hyd29", lv:2, type:"Diagnosis", q:"A large hydrocele with a thickened sac in a man from a coastal district.",
     a:"A chylocele. SRB: it occurs commonly in coastal regions and around the equator, usually after repeated attacks of filarial epididymitis; the hydrocele is usually large and the sac thickened; the fluid contains fat, is rich in cholesterol, and is derived from a ruptured lymph varix into the tunica; and it is often difficult to differentiate from a primary hydrocele. B&L adds that in long-standing chyloceles there are dense adhesions between the scrotum and its contents, that the fluid may contain microfilariae, and that filarial elephantiasis supervenes in a small number of cases.", ref:"SRB 26 p.1059 · B&L 86 p.1566"},
    {id:"hyd30", lv:2, type:"Complications", q:"A hydrocele appears six weeks after an inguinal hernia repair.",
     a:"A post-herniorrhaphy hydrocele, a secondary hydrocele from damage to the lymphatic vessels of the tunica vaginalis, which SRB puts at 0.2%. It is treated like any hydrocele, but usually only after about six months.", ref:"SRB 26 p.1059"},
    {id:"hyd31", lv:2, type:"Treatment", q:"How do you treat a secondary hydrocele?",
     a:"Treat the cause. Draining the fluid without addressing a tuberculous epididymitis or a tumour achieves nothing, and in the case of a tumour it is harmful, because a scrotal puncture risks needle-track implantation and changes the surgical approach. So: ultrasound the testis, treat the infection or the tumour, and deal with the fluid afterwards.", ref:"B&L 86 p.1564 · SRB 26 p.1059"},
    {id:"hyd32", lv:2, type:"Examination", q:"The swelling is fluctuant in one direction only. Does that prove there is fluid in it?",
     a:"No. SRB's note is that a relaxed muscle can demonstrate fluctuation in one direction even though there is no fluid in it, which is why fluctuation must be elicited in two planes at right angles before it counts.", ref:"SRB 26 p.1058"},

    {id:"hyd40", lv:3, type:"Procedure", q:"What exactly is Jaboulay's operation?",
     a:"The two books attach the name to different procedures, so describe the operation and then name it. B&L lists eversion as its second technique and attaches the eponym to the pouch: the sac is opened and everted behind the testis, with placement of the testis in a pouch prepared by dissection in the fascial planes of the scrotum, which it calls Jaboulay's procedure. SRB splits the two apart: partial excision of the sac followed by eversion is what SRB calls Jaboulay's operation, while placing the sac with the testis in a newly created pocket between the fascial layers of the scrotum is Sharma and Jhawer's technique, a name that does not appear in B&L at all. SRB's list of operations is accordingly five: subtotal excision, Jaboulay's, evacuation and eversion, Lord's plication, and Sharma and Jhawer's. All of them start by opening and everting the sac and differ only in what is done next, which is why the eponym drifted. Say what you would do to the sac, then say whose name you are using.", ref:"B&L 86 p.1565 · SRB 26 p.1059, p.1060"},
    {id:"hyd41", lv:3, type:"Treatment", q:"How would you treat a filarial hydrocele? The books disagree.",
     a:"B&L makes aspiration the treatment: for the filarial hydrocele, treatment is by rest and aspiration, with chronic cases treated by excision of the sac. SRB's prohibition on aspiration is general, and the operation it names for this group is the other one: if the sac is thick, in a large hydrocele and in chylocele, subtotal excision of the sac is done. These are the same patient, since SRB describes the filarial hydrocele as following repeated attacks of filarial epididymitis with a thickened sac, so this is not an exception one book grants. Follow SRB and excise, quote B&L's sentence if asked what the book says, and in either case puncture nothing until a tumour has been excluded. Outside the three books, and flagged as outside them: current filarial morbidity management treats an established hydrocele surgically rather than by aspiration, because a thickened adherent sac refills almost at once.", ref:"B&L 86 p.1566 · SRB 26 p.1060, p.1059"},
    {id:"hyd42", lv:3, type:"Diagnosis", q:"A scrotal swelling with a second swelling above it in the groin, and cross-fluctuation between them.",
     a:"A hydrocele-en-bisac, or bilocular hydrocele: two intercommunicating sacs, one above and one below the neck of the scrotum, the upper one lying superficially or in the inguinal canal, or insinuating itself between the muscle layers, so that the two are cross-fluctuant. SRB's other conditions where cross-fluctuation is elicited are a plunging ranula, a psoas abscess and a compound palmar ganglion.", ref:"SRB 26 p.1059"},
    {id:"hyd43", lv:3, type:"Diagnosis", q:"What is a hydrocele of the canal of Nuck?",
     a:"A hydrocele occurring in females, in relation to the round ligament, and always in the inguinal canal.", ref:"SRB 26 p.1059"},
    {id:"hyd44", lv:3, type:"Diagnosis", q:"What is a hydrocele of the hernial sac?",
     a:"Fluid collecting within a hernial sac whose contents have become adherent: adhesions of the contents shut the sac off, the fluid secreted collects in it, and the result is a hydrocele of the hernial sac.", ref:"SRB 26 p.1059"},
    {id:"hyd45", lv:3, type:"Pathology", q:"Which hydrocele cannot you always get above, and why?",
     a:"The infantile hydrocele. In it the tunica and processus vaginalis are distended up to the internal ring, though the sac has no connection with the general peritoneal cavity, so the swelling reaches the root of the scrotum and there is no normal cord to feel above it. Working from the internal ring down keeps SRB's four types straight: congenital reaches the peritoneum, infantile reaches the internal ring but is shut off from it, vaginal is confined to the tunica, and encysted is an isolated pocket on the cord.", ref:"SRB 26 p.1057, p.1058"},
    {id:"hyd46", lv:3, type:"Treatment", q:"Is there any non-operative treatment other than aspiration?",
     a:"B&L mentions one: injection of a sclerosant such as tetracycline can be effective but painful. It is not first-line, and it shares aspiration's problem of being done through a scrotal needle, so a tumour must be excluded first.", ref:"B&L 86 p.1566"},
    {id:"hyd47", lv:3, type:"Procedure", q:"Which operation carries the least risk of a scrotal haematoma, and why?",
     a:"Lord's plication, because the sac is neither excised nor everted but bunched up with sutures, so there is minimal dissection and no raw cut surface. B&L's warning for eversion is that the cut edge bleeds, and that overrunning stitches at the cut edge can be used to reduce the risk of scrotal haematoma. The principle is that the less tunica you raw-surface, the less there is to bleed.", ref:"B&L 86 p.1565, p.1566"},
    {id:"hyd48", lv:3, type:"Diagnosis", q:"A craggy, non-tender epididymis with a hydrocele.",
     a:"Tuberculous epididymitis. S Das's findings are the ones to give: the vas deferens is thickened and beaded from submucous tubercles, nodules may be felt on the anterior aspect, a secondary hydrocele is present in 30% of cases, the contralateral epididymis may be diseased in long-untreated cases, and on rectal examination the seminal vesicles should be felt. His instruction for the general examination is to examine the chest, particularly where tuberculous epididymitis is extending upwards. The treatment is antituberculous drugs rather than drainage of the fluid.", ref:"Das 40 p.627, p.623 · Das 39 p.613 · SRB 26 p.1059"},
  ],

  "liver-secondaries": [
    {id:"lvs01", lv:1, type:"Examination", q:"Describe the liver in secondaries.",
     a:"Enlarged, irregular, hard, with multiple nodules of varying size and shape, the nodules showing central softening and umbilication. Add the rest of SRB's summary: poor general condition, a palpable liver that is hard and multinodular with umbilication, the clinical features of the primary, and ascites and jaundice variably present.", ref:"Das 35 p.524 · SRB 11 p.605"},
    {id:"lvs02", lv:1, type:"Pathology", q:"Why do the nodules umbilicate?",
     a:"Central necrosis. The nodule outgrows its blood supply, the centre softens, and the surface is drawn in.", ref:"SRB 11 p.605 · Das 35 p.524"},
    {id:"lvs03", lv:1, type:"Pathology", q:"By what routes does a tumour reach the liver?",
     a:"SRB's four: direct spread, from stomach, colon, gallbladder and bile ducts; the hepatic artery, classically melanoma; the portal vein, carcinoid and other gastrointestinal malignancies; and lymphatics, breast and lung. S Das puts it as the portal vein from the gastrointestinal tract and lymphatics from organs like the breast.", ref:"SRB 11 p.605 · Das 35 p.524"},
    {id:"lvs04", lv:1, type:"Classification", q:"Synchronous or metachronous: define them.",
     a:"Synchronous means the primary and the secondaries are identified at the same time, as with carcinoma of the stomach. Metachronous means the secondaries develop much later, possibly long after treatment of the primary, as with melanoma and breast carcinoma. In colorectal cancer, 15 to 25% are synchronous and 20 to 45% metachronous, and up to 70% of patients develop liver metastases.", ref:"SRB 11 p.605 · B&L 69 p.1216"},
    {id:"lvs05", lv:1, type:"Examination", q:"How do you prove this mass is the liver?",
     a:"S Das: hepatic swellings are continuous with the liver dullness and move up and down with respiration, and it is difficult to move them sideways. Establish enlargement by palpating the lower border and percussing the upper limit, and do not forget the upper limit, because a pushed-up liver is otherwise mistaken for hepatomegaly.", ref:"Das 35 p.523"},
    {id:"lvs06", lv:1, type:"Examination", q:"Which abdominal swellings move well with respiration, and which do not?",
     a:"Swellings of the liver, gallbladder, stomach and spleen move well; a renal or suprarenal swelling moves very little. And the movement to look for is up and down, which must not be confused with the anteroposterior movement of the abdominal wall during breathing.", ref:"Das 35 p.518, p.519"},
    {id:"lvs07", lv:1, type:"Examination", q:"How does percussing the loin help?",
     a:"S Das's test: percuss just outside the erector spinae, where the area is normally resonant. A liver or splenic swelling is dull there; a renal swelling is resonant, because a retroperitoneal organ keeps bowel in front of it.", ref:"Das 35 p.521"},
    {id:"lvs08", lv:1, type:"Examination", q:"What does jaundice tell you in this case, and what does ascites tell you?",
     a:"Jaundice depends on the extent of liver involvement, and S Das says the patient may be jaundiced sooner or later, so its absence does not mean limited disease and its presence does not mean inoperable disease, since it may be the primary obstructing the bile duct. Ascites suggests peritoneal disease, which CT is poor at detecting, so clinical ascites adds information the imaging may miss and it is the finding that most often moves a patient from operable to inoperable.", ref:"SRB 11 p.605 · Das 35 p.524 · B&L 69 p.1196"},
    {id:"lvs09", lv:1, type:"Diagnosis", q:"What else gives a nodular liver?",
     a:"SRB's differential: multicentric hepatoma, macronodular cirrhosis, polycystic liver disease and hydatid cyst of the liver. Add chronic amoebic liver abscess, which gives a smooth, firm or hard, non-tender palpable liver.", ref:"SRB 11 p.605, p.590"},
    {id:"lvs10", lv:1, type:"Diagnosis", q:"What is Riedel's lobe, and what is it mistaken for?",
     a:"A congenital tongue-shaped projection from the lower border of the right lobe of the liver. S Das: it is likely to be mistaken for an enlarged gallbladder, but it is wider and flatter than the gallbladder and lacks the spherical outline of a distended gallbladder.", ref:"Das 35 p.523"},
    {id:"lvs11", lv:1, type:"History", q:"Run the checklist for finding the primary at the bedside.",
     a:"SRB's organ-by-organ list. Stomach: vomiting, visible gastric peristalsis, a palpable mass. Pancreas: jaundice, steatorrhoea, itching, a palpable gallbladder. Colon: altered bowels, a palpable mass, obstruction. Testis: fullness, a hard mass, loss of testicular sensation. And first of all, any previous cancer surgery, such as a mastectomy or wide excision of a melanoma.", ref:"SRB 11 p.605"},
    {id:"lvs12", lv:1, type:"Examination", q:"What do you do before you examine this patient's abdomen?",
     a:"Hand hygiene, introduce yourself and check the name and date of birth, explain what you are going to do, obtain verbal consent, and make the patient comfortable. B&L asks for permission to begin the consultation in ensured privacy, and adds the reason it matters here: a tense patient without a relaxed abdominal wall will substantively affect the accuracy of the clinical examination, and if the patient is still uncomfortable the presence of a close family member as a chaperone can help.", ref:"B&L 63 p.1051 · B&L 35 p.472 · B&L 21 p.285"},
    {id:"lvs13", lv:1, type:"Examination", q:"Which two examinations for the primary are free and usually skipped?",
     a:"Rectal examination, for rectovesical secondaries, the Blumer shelf; and palpation of the left supraclavicular fossa, for Virchow's node, that is Troisier's sign. Either one can settle the diagnosis.", ref:"SRB 11 p.605"},

    {id:"lvs20", lv:2, type:"History", q:"What is the first question you ask this patient, and why?",
     a:"Whether he has ever had an operation for cancer, when, and for what, because it may settle the whole case in one answer: SRB lists a history of earlier surgery such as mastectomy or wide excision of a melanoma among the features. Then date it, because a long interval suggests a metachronous deposit, classically melanoma or breast, while simultaneous discovery is synchronous disease. Do not use a short interval to write the patient off: a disease-free interval of less than a year was once a reason to call the disease irresectable and is no longer.", ref:"SRB 11 p.605 · B&L 69 p.1216"},
    {id:"lvs21", lv:2, type:"History", q:"Which primary are you most anxious to find, and why?",
     a:"A colorectal one, because it is the one with about 50% five-year survival after liver resection. So ask about change in bowel habit, blood in the stool and tenesmus, and look for SRB's colonic pointers, constipation or diarrhoea, a palpable mass and features of obstruction. Finding a colorectal primary changes the case from palliative to potentially curative.", ref:"B&L 69 p.1216 · SRB 11 p.605"},
    {id:"lvs22", lv:2, type:"Pathology", q:"Why does the liver hurt, and where?",
     a:"SRB gives two mechanisms and a caveat: pain in liver secondaries is due to stretching of the liver capsule or to tumour necrosis, and often the pain may be of the primary tumour. So pain over the liver points to deposits large or peripheral enough to stretch the capsule, which is not the same as inoperable, and pain elsewhere may be the primary speaking. S Das's contrast is the amoebic abscess, where the pain is in the right hypochondrium and referred to the right shoulder, with real tenderness.", ref:"SRB 11 p.605 · Das 35 p.523"},
    {id:"lvs23", lv:2, type:"Diagnosis", q:"A tender enlarged liver with fever and a history of dysentery.",
     a:"Amoebic liver abscess. S Das's picture: amoebic dysentery months or years ago, now right hypochondrial pain referred to the right shoulder with fever, a pale and slightly icteric patient, a palpable and very tender liver, intercostal tenderness that can be elicited even when the liver is not palpable, and a raised upper limit of liver dullness. Entamoeba histolytica in the stool is diagnostic, and aspiration of anchovy-sauce, chocolate-coloured pus leaves no doubt. SRB's chronic form, a firm or hard, smooth, non-tender liver without acute features, is the one mistaken for secondaries.", ref:"Das 35 p.523 · SRB 11 p.590"},
    {id:"lvs24", lv:2, type:"Diagnosis", q:"The patient keeps sheep and gives a history of urticaria. What must you think of, and what must you not do?",
     a:"A hydatid cyst, and you must not put a needle into it. S Das: a cyst near the lower margin of the liver gives a palpable spherical smooth swelling with a hydatid thrill and fluctuation, diagnosed by the history of urticaria, eosinophilia, the complement fixation test and Casoni's intradermal reaction. SRB lists hydatid disease as a contraindication to liver biopsy because it will precipitate anaphylaxis, along with haemangioma, bleeding disorders and ascites.", ref:"Das 35 p.524 · SRB 11 p.586"},
    {id:"lvs25", lv:2, type:"Investigation", q:"You cannot find the primary. How do you look for it?",
     a:"SRB: gastroscopy, colonoscopy, contrast radiographs and CT. Add CEA as a tumour marker, and liver function tests. And take the history and examination seriously first: previous cancer surgery, the organ-by-organ checklist, a rectal examination for a rectovesical shelf, and the left supraclavicular fossa. Liver biopsy is reserved for when the primary cannot be identified by any of these.", ref:"SRB 11 p.605"},
    {id:"lvs26", lv:2, type:"Investigation", q:"What does an ultrasound give you here?",
     a:"Four answers from one cheap test, in SRB's list: multiple hypo- or hyperechoic lesions in the liver; the site of a possible primary; nodal status; and ascites.", ref:"SRB 11 p.605"},
    {id:"lvs27", lv:2, type:"Investigation", q:"What is CT good for in this case, and what is its blind spot?",
     a:"CT is used for assessing stage and resectability of liver tumours, apart from peritoneal metastases, which is the blind spot to remember. MRI of the liver is superior to CT in characterising focal lesions, with better resolution for small metastases, improved further by liver-specific contrast agents. So CT stages the patient and MRI counts and characterises the liver lesions.", ref:"B&L 69 p.1196"},
    {id:"lvs28", lv:2, type:"Investigation", q:"How would you stage this patient?",
     a:"Through a specialist multidisciplinary team, which B&L says should coordinate both the staging and the treatment plan. Routine staging is triple-phase CT of chest, abdomen and pelvis, contrast MRI of the liver, whole-body PET-CT to identify metastatic disease, with or without laparoscopy and intraoperative ultrasonography.", ref:"B&L 69 p.1217"},
    {id:"lvs29", lv:2, type:"Investigation", q:"What does laparoscopy add after a full set of scans?",
     a:"It finds what the scans missed. SRB: laparoscopy with laparoscopic ultrasound is very useful to detect small secondaries, and it is how the peritoneal disease that CT under-detects is found, before a laparotomy is wasted.", ref:"SRB 11 p.605 · B&L 69 p.1196, p.1217"},
    {id:"lvs30", lv:2, type:"Investigation", q:"Would you biopsy the liver lesion?",
     a:"Not one I intend to resect. B&L, where resection is being considered, is explicit that biopsy should be avoided, and that in borderline cases diagnostic laparoscopy and intraoperative ultrasonography will exclude additional hepatic or peritoneal disease. Biopsy is for patients you are not going to operate on: SRB does a liver biopsy only if the primary is not identified by any of the other methods, and that is also the setting where the histology will direct chemotherapy. Before any liver biopsy, exclude hydatid disease.", ref:"B&L 69 p.1216 · SRB 11 p.605, p.586"},
    {id:"lvs31", lv:2, type:"Procedure", q:"If you do biopsy the liver, how, and what can go wrong?",
     a:"SRB: a Vim-Silverman needle or, better, a Menghini needle, usually through the right mid-axillary line. Complications: haemorrhage, infection, bile leak and biliary peritonitis. Contraindications: hydatid disease, because it precipitates anaphylaxis, haemangioma, bleeding disorders and ascites.", ref:"SRB 11 p.586"},
    {id:"lvs32", lv:2, type:"Management", q:"The primary is an obstructing colonic cancer and there are liver deposits. What do you do about the colon?",
     a:"Deal with it: SRB's position is that if the primary is in the colon a palliative hemicolectomy is done, and if a solitary liver secondary is present it can be resected along with it. An obstructing or bleeding primary needs treating whatever the state of the liver disease, and the decision on the liver belongs to a hepatobiliary multidisciplinary team.", ref:"SRB 11 p.605 · B&L 69 p.1217"},

    {id:"lvs40", lv:3, type:"Management", q:"Is this patient curable?",
     a:"Possibly, and that is the point of the case. B&L: despite recent advances in chemotherapeutic agents, resection remains the only potentially curative option, but only 20% of patients will be candidates at presentation and a further 20 to 30% become operable following chemotherapy. Thirty years ago metastatic colorectal cancer carried a five-year survival of less than 3%; liver resection in selected patients with liver-only metastatic disease has demonstrated five-year survival of 50%. SRB's position, that chemotherapy is the treatment of choice with surgery having a definitive role for a colonic or renal primary, is right for unresectable disease and wrong as a general rule. So the first question is not which chemotherapy but whether this patient can be made resectable, and liver-only metastatic colorectal cancer belongs in a hepatobiliary unit rather than in palliation.", ref:"B&L 69 p.1216, p.1210 · SRB 11 p.605"},
    {id:"lvs41", lv:3, type:"Management", q:"What makes liver metastases unresectable?",
     a:"Not the number and not the size. B&L: resection with curative intent is defined as the ability to successfully remove all residual disease from the liver with clear surgical margins, leaving adequate disease-free viable liver, and the technical contraindications are anatomical, principally involvement of major vascular or biliary structures. Previously, synchronous metastases, a rectal primary, multiple diffuse metastases, metastases larger than 5 cm, a disease-free interval of less than a year, or a high serum CEA were considered irresectable and suitable only for palliation; modern surgical techniques and chemotherapy mean they are not. SRB's criteria, the stage of the primary, the number of secondaries, the segments involved, the size of the largest lesion and associated liver disease, still predict prognosis; they no longer decide operability.", ref:"B&L 69 p.1216 · SRB 11 p.605"},
    {id:"lvs42", lv:3, type:"Management", q:"How much liver must you leave behind?",
     a:"B&L: there is no clear consensus about the volume required for adequate post-resection liver function, but a future liver remnant to total estimated liver volume ratio of at least 25% is recommended with a normal liver and 40% in the presence of cirrhosis; in the colorectal metastasis section, an FLR of 25% of preoperative volume is considered sufficient to prevent postoperative hepatic failure.", ref:"B&L 69 p.1212, p.1217"},
    {id:"lvs43", lv:3, type:"Treatment", q:"The future liver remnant would be too small. What can you do?",
     a:"Grow it, or change the operation. Preoperative portal vein embolisation induces hypertrophy of one side of the liver before a planned resection of the other, increasing the future liver remnant; B&L notes it was first described by Makuuchi in 1984 before an extended hepatectomy for bile duct carcinoma, and the materials are polyvinyl alcohol particles, coils, gelatin sponge, n-butyl cyanoacrylate with lipiodol, or fibrin glue. The other three tools B&L names for converting an inoperable liver are staged procedures, ablation, and local or multiple segmental resections, alongside downstaging chemotherapy.", ref:"B&L 69 p.1211, p.1212, p.1210"},
    {id:"lvs44", lv:3, type:"Treatment", q:"What margin do you aim for, and what if you cannot get it?",
     a:"An R0 resection with a negative surgical margin of 1 cm is considered the gold standard. But with effective modern chemotherapy, patients with an R1 resection, meaning a margin of at least 1 mm microscopically negative, which occurs in 10 to 30% of patients, have similar survival to those with R0 resections. So a close margin is not a reason to abandon an otherwise feasible resection, which is the same shift as everywhere else in this chapter, from anatomical rules to functional ones.", ref:"B&L 69 p.1216, p.1217"},
    {id:"lvs45", lv:3, type:"Treatment", q:"What is the standard operation for colorectal liver metastases?",
     a:"Multiple segmentectomies and/or metastectomies, which B&L calls the standard of care, rather than a hemihepatectomy by default. It is possible because each segment has its own arterial, portal and biliary supply and its own hepatic vein tributary, which is what makes anatomical segmental resection feasible, and it is the point of departure from SRB's rule that if the secondaries are in a single lobe a hemihepatectomy is done.", ref:"B&L 69 p.1211, p.1193 · SRB 11 p.605"},
    {id:"lvs46", lv:3, type:"Anatomy", q:"Divide the liver surgically.",
     a:"At Cantlie's line. Segments V to VIII, to its right, are supplied by the right hepatic artery and right portal vein and drain by the right hepatic duct; segments I to IV, to its left, by the left hepatic artery and left portal vein, draining by the left hepatic duct. Each segment is drained by a hepatic vein tributary, and B&L's own comment is that this concept facilitates anatomical liver resection, so resections of individual segments, of a whole hemiliver, or combinations are all possible.", ref:"B&L 69 p.1193"},
    {id:"lvs47", lv:3, type:"Treatment", q:"Why does blocking the hepatic artery work?",
     a:"SRB's sentence, worth quoting as written: hepatic artery ligation is one of the surgical palliations for advanced hepatocellular carcinoma and secondaries in the liver, as tumour tissue is supplied exclusively by the hepatic artery but normal tissue is also supplied by the portal vein. That is the rationale for every transarterial therapy in the liver: you can starve the tumour because the liver has a second blood supply and the tumour does not. SRB elsewhere writes that hepatic artery ligation or embolisation is tried, and lists chemoembolisation among the palliative options.", ref:"SRB 11 p.584, p.604 · SRB 21 p.869"},
    {id:"lvs48", lv:3, type:"Management", q:"There are lung metastases as well. Does that rule out liver resection?",
     a:"Not automatically. B&L: historically extrahepatic metastatic disease was considered a contraindication to liver surgery, but long-term survival is now possible in selected patients, and survival after lung resection for colorectal metastases is similar to that after liver resection, 40 to 50%, with low morbidity and mortality. It is a decision for a multidisciplinary team rather than a rule.", ref:"B&L 69 p.1217"},
    {id:"lvs49", lv:3, type:"Management", q:"What happens after resection?",
     a:"Five-year overall survival is about 50%, but tumour recurs in 65% of patients, and in 40% of those the recurrence is limited to the liver. That last figure is the one that matters: because most recurrences are again confined to the liver, re-resection or ablation is often possible, which is why these patients need structured follow-up in a specialist unit.", ref:"B&L 69 p.1216"},
    {id:"lvs50", lv:3, type:"Treatment", q:"What are the Milan criteria?",
     a:"The criteria for liver transplantation in hepatocellular carcinoma, first described by Mazzaferro in 1996: tumours of 5 cm or less, or up to three nodules each of 3 cm or less, with angioinvasion and extrahepatic involvement as exclusions. They achieved four-year overall survival of 75% and recurrence-free survival of 83% and are now universally accepted, and ablation can downstage a tumour into the criteria.", ref:"B&L 69 p.1216"},
    {id:"lvs51", lv:3, type:"Procedure", q:"What has made liver resection safe enough to offer?",
     a:"B&L names three things since the first formal resection in 1952: cross-sectional imaging, liver transection technology, and low central venous pressure anaesthesia, which is the one candidates forget and the one that controls bleeding from the hepatic veins. The parenchyma is divided by CUSA, harmonic scalpel or radiofrequency, and B&L is candid that the choice is a matter of personal preference with no evidence that any method is superior; the hepatic veins and the Glissonian sheath are now routinely stapled with an endoscopic vascular stapler.", ref:"B&L 69 p.1191, p.1211"},
    {id:"lvs52", lv:3, type:"Pathology", q:"What are the primary liver tumours in the differential, and how do they behave?",
     a:"Hepatocellular carcinoma, managed by resection, ablation or transplantation by the Milan criteria. Intrahepatic cholangiocarcinoma, which is 20% of cholangiocarcinomas and 5 to 30% of primary liver tumours, second only to HCC: rare in the West at 0.5 to 2 per 100 000 but 60 per 100 000 in Thailand where Clonorchis sinensis is endemic, with only 30% suitable for resection at presentation even when confined to the liver, and a five-year survival of 3% that remains unchanged. S Das's reminder still holds: primary carcinoma of the liver is rare and may be a hepatoma or a cholangioma, while secondary carcinoma is much commoner.", ref:"B&L 69 p.1216 · Das 35 p.524"},
  ],

  "varicose-veins": [
    {id:"vvn01", lv:1, type:"Pathology", q:"Define varicose veins, and the smaller veins, by calibre.",
     a:"SRB's thresholds: dermal flares are thread veins under 1 mm in diameter, seen in 30% of superficial vein incompetence; reticular veins are 1 to 3 mm, lying just deep to the skin, also in 30%; varicose veins are usually over 3 mm. Incidence of varicose veins is about 5% of the adult population.", ref:"SRB 1 p.222"},
    {id:"vvn02", lv:1, type:"Pathology", q:"Why are varicosities commoner in the lower limb?",
     a:"SRB: because of the erect posture, and because a long column of blood has to be supported, which leads to weakness and incompetency of the valves.", ref:"SRB 1 p.222"},
    {id:"vvn03", lv:1, type:"Anatomy", q:"Compare the superficial and deep venous systems.",
     a:"The superficial veins carry 10% of the venous system, lie in condensed superficial fascia between skin and deep fascia, and have thick muscular walls, low pressure and plenty of valves. The long saphenous vein is the longest vein in the body and has 10 to 20 valves.", ref:"SRB 1 p.222"},
    {id:"vvn04", lv:1, type:"Anatomy", q:"Name the sites of superficial-to-deep communication.",
     a:"SRB's four: the saphenofemoral junction, mid-thigh perforators, the short saphenopopliteal junction, and calf perforators. S Das's order of importance for the long saphenous system: the saphenofemoral junction, which is the most important, the mid-thigh perforator, the lower-thigh perforator, and the lower leg perforators on the medial side.", ref:"SRB 1 p.222 · Das 7 p.103"},
    {id:"vvn05", lv:1, type:"Anatomy", q:"Which system is involved, and how do you tell by looking?",
     a:"Long saphenous: medial side of the leg and thigh, passing anterior to the medial malleolus. Short saphenous: posterior calf, arising from the lateral side of the dorsal venous arch and passing posterior to the lateral malleolus with the sural nerve. The nerve matters because it is the one injured in short saphenous surgery.", ref:"B&L 62 p.1026"},
    {id:"vvn06", lv:1, type:"Examination", q:"Give the skin changes of chronic venous disease, in the order they develop.",
     a:"Pigmentation, that is haemosiderosis, then eczema, then lipodermatosclerosis of the calf skin, then ulceration. SRB adds atrophie blanche, white patches in the skin from severe varicose veins, and thickening of the tibia from periostitis in long-standing disease. S Das's instruction is to look for pitting oedema or thickening, redness or tenderness at the lower part of the leg, which follow chronic venous hypertension after deep vein thrombosis.", ref:"B&L 62 p.1029 · SRB 1 p.222, p.223 · Das 7 p.104"},
    {id:"vvn07", lv:1, type:"Examination", q:"How do you begin the examination?",
     a:"Expose both legs fully and examine the patient standing, because varices only fill against gravity. Mark the varicosities: SRB illustrates marking the veins with marking ink just before surgery. Then look at the distribution to decide which system, and at the skin for the changes of venous hypertension.", ref:"SRB 1 p.228 · Das 7 p.102"},
    {id:"vvn08", lv:1, type:"Classification", q:"Group the symptoms of varicose veins.",
     a:"SRB's three groups. Group I, asymptomatic: venous telangiectasia, thread, reticular or varicose veins. Group II, symptomatic: cramps, heaviness, tenderness, itching, swelling. Group III, complicated: haemorrhage, superficial thrombophlebitis, eczema, lipodermatosclerosis and venous ulcers. The classical symptom is a dragging pain with postural discomfort.", ref:"SRB 1 p.222"},
    {id:"vvn09", lv:1, type:"History", q:"Is the aching worse in the morning or the evening, and why does the answer matter?",
     a:"Worse in the evening: SRB says symptoms are less severe in the morning than in the evening, because they come from ambulatory venous hypertension, which accumulates through a day of standing and is relieved by a night of elevation. The contrast with arterial disease is the separator: claudication comes on walking a predictable distance and is relieved by standing still, while venous aching comes on standing still and is relieved by walking and elevation. If walking helps, think venous.", ref:"SRB 1 p.222 · B&L 62 p.1027"},
    {id:"vvn10", lv:1, type:"Classification", q:"Distinguish primary from secondary varicose veins.",
     a:"Primary: often familial, cause unknown, a weak valve or weak wall, younger patient, the main saphenous veins affected with the deep veins usually patent, only Trendelenburg test I positive, complications fewer and later. Secondary: acquired, adult or elderly, saphenous veins, perforators and often the deep veins involved, both Trendelenburg tests I and II often positive, complications common and quick to develop.", ref:"SRB 1 p.222"},
    {id:"vvn11", lv:1, type:"Diagnosis", q:"A soft swelling in the groin with a cough impulse in a patient with varicose veins.",
     a:"A saphena varix: a large varicosity in the groin which becomes visible on standing, with a positive cough impulse at the saphenofemoral junction. B&L's warning is that it may elicit an impulse and be mistaken for a groin hernia, which is the same trap seen from the other side in the hernia case.", ref:"SRB 1 p.223 · B&L 62 p.1031"},
    {id:"vvn12", lv:1, type:"Physiology", q:"What drives venous return from the leg?",
     a:"B&L: venous pressure in the leg is increased by compression by the surrounding muscles, the calf muscle pump, and to a lesser extent by the tone of the venous wall. The deep calf veins are capacious and joined by blind-ending sacks, the soleal sinusoids, which force blood into the popliteal and crural veins when the calf pump contracts, for instance while walking. That is why exercise relieves venous symptoms, standing worsens them, and compression works.", ref:"B&L 62 p.1027"},
    {id:"vvn13", lv:1, type:"Examination", q:"What do you do before you examine this patient's legs?",
     a:"Hand hygiene, introduce yourself and check the name and date of birth, explain what you are going to do, obtain verbal consent, and make the patient comfortable. Expose both legs fully and keep the patient covered otherwise, and examine standing.", ref:"B&L 35 p.472 · B&L 21 p.285"},

    {id:"vvn20", lv:2, type:"Examination", q:"Describe the Brodie-Trendelenburg test, both parts.",
     a:"With the patient recumbent, raise the leg to empty the veins, milking them proximally. Compress the saphenofemoral junction with the thumb, or apply a tourniquet just below it, and stand the patient up quickly. Part one: release the pressure, and if the varices fill very quickly by a column of blood from above, the saphenofemoral valve is incompetent. Part two: maintain the pressure for about a minute, and gradual filling of the veins while the junction stays occluded means incompetent communicating veins, mostly on the medial side of the lower half of the leg, allowing flow from deep to superficial. Part one tests the junction, part two the perforators, and for the short saphenous system press the saphenopopliteal junction instead.", ref:"Das 7 p.102 · SRB 1 p.223"},
    {id:"vvn21", lv:2, type:"Examination", q:"How does the tourniquet test localise a perforator?",
     a:"It is a variant of the Trendelenburg test. Empty the veins by elevation, tie the tourniquet at a chosen level, and stand the patient up. If the veins above the tourniquet fill while those below stay collapsed, the incompetent perforator is above the tourniquet; if those below fill rapidly while those above stay empty, it is below. Move the tourniquet down in steps and you localise it.", ref:"Das 7 p.102, p.103"},
    {id:"vvn22", lv:2, type:"Examination", q:"What is Perthes' test for?",
     a:"Deep venous patency. Occlude the superficial system, either with an elastic bandage or a thigh tourniquet, and exercise the patient. If the deep veins are patent the varices shrink and the patient is comfortable; if they are obstructed the varices become more distended and the patient develops severe crampy pain, because you have occluded the limb's only drainage. S Das gives two versions on the same page, the original judged by pain and the modified one by the size of the varices, and instructs that arterial occlusive disease be excluded first. The point that survives the method: if the deep veins are obstructed, the superficial veins are the limb's collateral drainage and must not be stripped or ablated.", ref:"Das 7 p.103 · B&L 62 p.1031"},
    {id:"vvn23", lv:2, type:"Examination", q:"What is the Schwartz test?",
     a:"In a long-standing case, a tap on the long saphenous varicosity in the lower leg transmits an impulse that is felt at the saphenous opening with the other hand, and the percussion wave can also be transmitted from above downwards. It demonstrates a continuous column of blood in an incompetent vein.", ref:"Das 7 p.103, p.104"},
    {id:"vvn24", lv:2, type:"Examination", q:"What is Pratt's test?",
     a:"A test for the sites of leg perforators. Apply an Esmarch elastic bandage from toes to groin and tie a tourniquet at the groin, which empties the varices. Keeping the tourniquet on, remove the bandage and then reapply it from the groin downwards: at the site of each perforator a blow-out or visible varix appears, and these are marked with a skin pencil.", ref:"Das 7 p.103, p.104"},
    {id:"vvn25", lv:2, type:"Examination", q:"How do you find the perforators by palpation alone?",
     a:"Mark the sites of excessive bulges while the patient stands. Then lie him down, elevate the limb to empty the veins, and palpate along the marked line for gaps or pits in the deep fascia, which transmit the incompetent perforators. It is the one test that is pure palpation and often the most convincing at the bedside.", ref:"Das 7 p.104"},
    {id:"vvn26", lv:2, type:"Examination", q:"How do you demonstrate saphenofemoral incompetence by cough?",
     a:"Elevate the limb to empty the veins, lay the patient down and ask for a forcible cough. An expansile impulse is felt in the long saphenous vein, particularly at the saphenous opening, if the saphenofemoral valve is incompetent, and a bruit may be heard on auscultation.", ref:"Das 7 p.104"},
    {id:"vvn27", lv:2, type:"History", q:"What is the single most important question in the history?",
     a:"Whether the patient has ever had a swollen painful leg, a clot, a long illness in bed or a fracture, because a post-thrombotic limb changes the treatment completely: the superficial veins may be the limb's collateral drainage and must not be stripped or ablated. SRB's figures make the point: 50% of venous ulcers are due to varicose veins and 50% to deep venous disease, and 50% of venous ulcers occur as a result of recanalisation of a deep vein thrombosis, the leg then being called a postphlebitic limb.", ref:"SRB 1 p.27, p.234"},
    {id:"vvn28", lv:2, type:"Examination", q:"Where should a venous ulcer be, and what if it is elsewhere?",
     a:"Around the ankle, in the gaiter's zone, from ambulatory chronic venous hypertension; SRB adds that it is vertically oval, commonly medial, occasionally lateral, sometimes both, but never above the middle third of the leg. An ulcer elsewhere on the leg is probably not venous. In the post-thrombotic limb the mechanism is deep vein thrombosis causing increased venous pressure around the ankle, transmitted through the perforators.", ref:"SRB 1 p.27"},
    {id:"vvn29", lv:2, type:"Treatment", q:"What does compression do, and what is the hazard?",
     a:"Graduated compression hosiery is the conservative mainstay, working with the calf pump against ambulatory venous hypertension. B&L is blunt about the hazard: misapplication of compression hosiery can have serious consequences, pressure necrosis and tourniquet effects, so assessment, prescription and application should be done properly. Exclude arterial disease before compressing a leg. SRB's options for the ulcer are a Charing Cross elastic multilayered compression bandage once a week, low compression bandaging, graduated elastic compression stockings over a leak-proof absorbent dressing, Unna boots, or crepe bandage and stockings.", ref:"B&L 62 p.1033 · SRB 1 p.234"},
    {id:"vvn30", lv:2, type:"Investigation", q:"What must the duplex scan tell you?",
     a:"B&L's four stated aims: the presence of reflux in the deep and superficial venous systems; the exact distribution and extent of reflux in the superficial system, including which junctions and perforators are affected; the presence of obstruction in the deep venous system; and the suitability of the vein for the planned intervention. Those four map exactly onto what the clinical tests were trying to establish, which is why duplex replaced them.", ref:"B&L 62 p.1031"},
    {id:"vvn31", lv:2, type:"Complications", q:"How do you elicit the signs of a deep vein thrombosis?",
     a:"Two ways of eliciting calf tenderness, one indirect and one direct. Homan's sign: passive forceful dorsiflexion of the foot with the knee extended stretches the calf muscles and produces pain. Moses' sign: calf tenderness elicited directly, by squeezing the calf muscles from side to side. S Das adds the extreme form: with venous obstruction the limb swells and becomes oedematous, and when it becomes congested and blue that is phlegmasia cerulea dolens.", ref:"Das 7 p.106"},
    {id:"vvn32", lv:2, type:"Pathology", q:"What are the secondary causes of varicose veins?",
     a:"SRB's list: recurrent thrombophlebitis; occupational prolonged standing, naming traffic police, guards and sportsmen; obstruction to venous return from an abdominal tumour, retroperitoneal fibrosis, lymphadenopathy or ascites; pregnancy, due to progesterone, with obesity and chronic constipation; arteriovenous malformations; iliac vein thrombosis; and tricuspid incompetence, which is the one nobody expects and is worth naming.", ref:"SRB 1 p.222"},

    {id:"vvn40", lv:3, type:"Investigation", q:"Are the tourniquet tests still worth doing?",
     a:"In the clinical examination yes, and you should perform them, because the examiner is marking from S Das and SRB and doing them competently shows you understand superficial-to-deep reflux. Then locate them: B&L 28e states that tourniquet tests and the use of hand-held Doppler have now been abandoned, and that there is good evidence to support the policy of duplex ultrasound scanning for all patients with varicose veins prior to any intervention. Its reason is the one to quote: the best clinical results come from clinicians who are personally very skilled in the use of duplex and use it to design a bespoke treatment for each individual patient based on their unique anatomy. The tests give a crude yes or no, duplex gives a map, and catheter-directed treatment needs a map. Perthes, Schwartz, Pratt, Fegan and Morrissey do not appear in B&L's venous chapter at all.", ref:"B&L 62 p.1031 · Das 7 p.102 · SRB 1 p.222"},
    {id:"vvn41", lv:3, type:"Treatment", q:"What is the gold standard treatment?",
     a:"B&L: endothermal ablation technologies replaced surgical ligation and stripping as the gold standard once randomised trials showed they were marginally safer, with extremely high technical efficacy, superior quality of life after the procedure with rapid recovery, and equivalent longer-term improvement, and that they are cost-effective because they can be done as an outpatient under local anaesthetic. Open surgery is framed as the traditional alternative, used unless by patient choice. SRB teaches the open operation as the treatment, which is what is done in most Indian hospitals, so give the endovenous gold standard first and the open operation as the alternative, noting that the principle is identical in both: abolish the point of junctional incompetence and deal with the refluxing axial vein. And duplex first, whichever you do.", ref:"B&L 62 p.1033, p.1037, p.1031 · SRB 1 p.228"},
    {id:"vvn42", lv:3, type:"Procedure", q:"Describe the Trendelenburg operation.",
     a:"Juxtafemoral flush ligation of the long saphenous vein, flush with the femoral vein, after ligating the named tributaries: superficial circumflex iliac, superficial external pudendal and superficial epigastric, plus the deep external pudendal and the unnamed tributaries. SRB's warning is the examinable part: all tributaries should be ligated, otherwise recurrence will occur. For a venous ulcer SRB's operation is Trendelenburg's operation, stripping of the veins and perforator ligation.", ref:"SRB 1 p.228, p.234"},
    {id:"vvn43", lv:3, type:"Procedure", q:"How does endovenous laser ablation work?",
     a:"A small flexible glass fibre is inserted into the vein, and laser energy, typically at 1470 nm, travels down the fibre and is absorbed at its tip, generating vigorous thermal energy. Varicosities are marked beforehand if concomitant phlebectomy or foam sclerotherapy is planned; the patient is positioned in the reverse Trendelenburg position, and for the great saphenous vein supine with the hip of the treated leg externally rotated. The vein is surrounded by tumescent local anaesthetic solution, which compresses the vein onto the treatment device and protects the surrounding tissue. The irony worth noticing: the one surviving use of Trendelenburg's name in B&L's venous chapter is the position on the table for the procedure that replaced his operation.", ref:"B&L 62 p.1033"},
    {id:"vvn44", lv:3, type:"Treatment", q:"What are the non-thermal, non-tumescent techniques, and their trade-off?",
     a:"B&L notes that the mechanical devices can make the procedure uncomfortable, and that the device can snag on the vein, tearing it or rarely stripping it altogether. Comparative studies suggest similar early efficacy but increased medium- and long-term recanalisation rates, and although the axial ablation is less painful, that advantage is lost when it is combined with phlebectomy.", ref:"B&L 62 p.1036"},
    {id:"vvn45", lv:3, type:"Treatment", q:"Where does foam sclerotherapy fit?",
     a:"Alongside ablation, for residual varicosities, and B&L names a specific advantage: it allows direct and targeted delivery of adjuvant foam, for example to ablate areas of neovascularisation.", ref:"B&L 62 p.1035"},
    {id:"vvn46", lv:3, type:"Diagnosis", q:"A woman has unilateral left leg swelling with varicose veins. What one diagnosis must you consider?",
     a:"May-Thurner syndrome: compression of the left common iliac vein by the right common iliac artery, clearly described by May and Thurner in 1957. It is why a unilateral left-sided presentation with swelling deserves imaging of the pelvic and iliac veins rather than straight treatment of the superficial veins.", ref:"B&L 62 p.1027"},
    {id:"vvn47", lv:3, type:"Management", q:"Which patients with varicose veins should almost always be treated conservatively?",
     a:"Those with Klippel-Trenaunay syndrome. B&L: virtually all such patients should be treated conservatively with compression hosiery, though some benefit from laser ablation of the naevus, stapling of the bones to avoid leg length discrepancy, and occasional removal of large superficial varicose veins. The reason is the same as in the post-thrombotic limb: the superficial veins may be the limb's main drainage. Think of it in a young patient with unilateral atypical varices and a difference in limb length or girth.", ref:"B&L 62 p.1047 · SRB 1 p.222"},
    {id:"vvn48", lv:3, type:"Anatomy", q:"Which anatomical variation causes recurrence after an otherwise correct operation?",
     a:"Treating the wrong vein. B&L: the anterior accessory great saphenous vein is commonly mistaken for the great saphenous vein itself, and a true duplex great saphenous vein is rare. SRB's surgical equivalent is that a double saphenous vein is the commonest anomaly near the saphenovenous junction. It is one of the reasons for duplex mapping before any intervention.", ref:"B&L 62 p.1026 · SRB 1 p.228"},
    {id:"vvn49", lv:3, type:"Classification", q:"What is CEAP?",
     a:"Clinical, aEtiology, Anatomy, Pathophysiology: the descriptive classification for chronic venous disorders, widely utilised and updated in 2020. SRB gives its own group I to III symptom classification and then adds that the CEAP classification is also important, so both books want it. Give it by name and expand the acronym, which most candidates cannot.", ref:"B&L 62 p.1029, p.1050 · SRB 1 p.222"},
    {id:"vvn50", lv:3, type:"Pathology", q:"What causes primary varicose veins?",
     a:"Be candid first: B&L says the majority of patients with venous disease have a problem primarily with the vein wall structure, in most confined to the superficial veins, and that little is known about the mechanism of initiation. SRB's list is congenital incompetence or absence of valves; weakness or wasting of muscles with defective connective tissue and smooth muscle in the venous wall; stretching of the deep fascia; inheritance, with the FOXC2 gene; and the syndromes with varices of atypical distribution, Klippel-Trenaunay, avalvulia and Parkes-Weber.", ref:"B&L 62 p.1027 · SRB 1 p.222"},
    {id:"vvn51", lv:3, type:"Examination", q:"A thigh tourniquet makes the reflux worse rather than better. What does that mean?",
     a:"Short saphenous incompetence. S Das flags the paradox: in short saphenous varices a tourniquet on the upper thigh increases the strength of the reflux with faster filling, because it blocks the long saphenous route that was carrying most of the superficial return and throws the saphenopopliteal leak into prominence, and he calls this pathognomonic. The definitive test is to mark the saphenopopliteal junction standing, empty the vein by elevation, apply firm thumb pressure to the ink mark, stand the patient and release: immediate filling confirms saphenopopliteal incompetence.", ref:"Das 7 p.103"},
    {id:"vvn52", lv:3, type:"Complications", q:"What must you warn about when a patient with deep venous disease is exercised with a tourniquet on?",
     a:"Pulmonary embolism. SRB describes the manoeuvre and the danger together: after applying a tourniquet at the saphenofemoral junction the patient is made to walk and, without removing the tourniquet, the limb is examined, with the warning of chest pain, breathlessness and haemoptysis. Any discussion of deep venous disease should end with embolism.", ref:"SRB 1 p.217"},
  ],

};
